INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4a867a3a-e313-5d69-afa5-cc237fd015fd', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 19, 19, 'ነዳያን ደስታቸውን በእግዚአብሔር ያበዛሉ፤ በሰዎች መካከል ተስፋ የሌላቸውም ሐሤትን በእስራኤል ቅዱስ ያደርጋሉ።'),
  ('1bb05c0a-aa9a-5ace-ac97-ac75bdbe2157', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 20, 20, 'ኃጥእ ሰው አልቆአልና፥ ትዕቢተኛውም ጠፍቶአልና፥ በክፋት የበደሉም ሁሉ ይነቀላሉና፤'),
  ('cfec94f0-db7a-5cc5-aafb-370a3e3f04cd', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 21, 21, 'እነዚህም ሰውን በነገር በደለኛ የሚያደርጉ፥ በበርም ለሚገሥጸው አሽክላ የሚያኖሩ፥ ጻድቁንም በከንቱ ነገር የሚያስቱ ናቸው።'),
  ('7e4e0528-bf0c-5a0b-ab3d-8924c6e05e1d', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 22, 22, 'ስለዚህ እግዚአብሔር ከአብርሃም ስለ ለየው ስለ ያዕቆብ ቤት እንዲህ ይላል፥ “ያዕቆብ አሁን አታፍርም፤ ፊትህም አሁን አይለወጥም።'),
  ('3de1f63c-3ced-5f84-a85b-65e47985ebef', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 23, 23, 'ነገር ግን ልጆቻቸው የእጄን ሥራ ባዩ ጊዜ ስለ እኔ ስሜን ይቀድሳሉ፤ የያዕቆብንም ቅዱስ ይቀድሳሉ፤ የእስራኤልንም አምላክ ይፈራሉ።'),
  ('9ce6c36c-1230-59fe-a3c5-514d17786a31', 'b050bc51-efbe-5861-ae27-c9789436bf2e', 'ef268135-3272-5dfc-ade8-29a3448834a2', 24, 24, 'በመንፈስም የሳቱ ማስተዋልን ያውቃሉ፤ የሚያጕረመርሙም መታዘዝን ይማራሉ፤ ዲዳ አንደበትም ሰላም መናገርን ይማራል።”'),
  ('846e0b6c-ca39-5122-afbf-6b69b89c8e9c', '052bac2a-b9e5-5cd4-a131-3f2357162611', '5ef9e8d0-3d8a-541c-aa5c-b786a586c69c', 1, 1, 'ለዐመፀኞች ልጆች ወዮላቸው! ይላል እግዚአብሔር፤ ከእኔ ዘንድ ያልሆነን ምክር ይመክራሉ፤ ኀጢአትንም በኀጢአት ላይ ይጨምሩ ዘንድ ከመንፈሴ ዘንድ ያልሆነውን ቃል ኪዳን ያደርጋሉ።'),
  ('3993ca14-edb7-5493-ad80-29ea1e1994bd', '052bac2a-b9e5-5cd4-a131-3f2357162611', '5ef9e8d0-3d8a-541c-aa5c-b786a586c69c', 2, 2, 'እኔን ሳይጠይቁ በፈርዖን ኀይል ይረዱ ዘንድ በግብፅም ይጠበቁ ዘንድ ወደ ግብፅ ይሄዳሉ።'),
  ('b6f2a17a-e8c9-59f3-a1bc-3f8bd39eb843', '052bac2a-b9e5-5cd4-a131-3f2357162611', '5ef9e8d0-3d8a-541c-aa5c-b786a586c69c', 3, 3, 'ስለዚህ የፈርዖን ኀይል እፍረት፥ በግብፅ መታመንም ስድብ ይሆንባችኋል።'),
  ('0910fb87-0059-5316-a8c2-9e5a5c7e2ceb', '052bac2a-b9e5-5cd4-a131-3f2357162611', '5ef9e8d0-3d8a-541c-aa5c-b786a586c69c', 4, 4, 'አለቆች ምንም በጣኔዎስ ቢሆኑ፥ መልእክተኞችም ምንም ወደ ሓኔስ ቢደርሱ፥'),
  ('78c266de-aa18-5ccb-aee7-dfeb3b2bc3fa', '052bac2a-b9e5-5cd4-a131-3f2357162611', '5ef9e8d0-3d8a-541c-aa5c-b786a586c69c', 5, 5, 'ሁላቸው ይጠቅሙአቸው ዘንድ ስለማይችሉ፥ እፍረትና ስድብ እንጂ ረድኤትና ረብ ስለማይሆኑ ሕዝብ ያፍራሉ።'),
  ('941b702a-fe8b-5cb0-abcf-5aa9ec83cd90', '052bac2a-b9e5-5cd4-a131-3f2357162611', '7e9cca3d-f4ee-550a-a080-a76f839d23cd', 1, 6, 'ተባትና እንስት አንበሳ፥ እፉኝትም፥ ነዘር እባብም፥ በሚወጡባት በመከራና በጭንቀት ምድር በኩል ብልጽግናቸውን በአህዮች ጫንቃ ላይ፥ መዛግብቶቻቸውንም በግመሎች ሻኛ ላይ እየጫኑ ወደማይጠቅሙአቸው ሕዝብ ይሄዳሉ።'),
  ('87d7f2d3-e42f-52c1-a161-69cc51d9818f', '052bac2a-b9e5-5cd4-a131-3f2357162611', '7e9cca3d-f4ee-550a-a080-a76f839d23cd', 2, 7, 'የግብፅ ርዳታ ከንቱና ባዶ ነው፤ ስለዚህ፥ “ምክራችሁ ከንቱ ነው” ብለህ ንገራቸው።'),
  ('8feb0406-f549-5b4f-ac7e-80f13a84cba4', '052bac2a-b9e5-5cd4-a131-3f2357162611', '7e9cca3d-f4ee-550a-a080-a76f839d23cd', 3, 8, 'አሁን ተቀመጥ፤ ለሚመጣውም ዘመን ለዘለዓለም እንዲሆን በሰሌዳ ላይ በመጽሐፍም ውስጥ ጻፍላቸው።'),
  ('9b2e14fb-2e03-5d1d-add1-bd217d08c5c9', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 1, 9, 'ዐመፀኛ ወገን፥ የእግዚአብሔርን ሕግ ለመስማት እምቢ ያሉ የሐሰት ልጆች ናቸውና፤'),
  ('bf0d9ddc-8600-58f3-abcd-d52f0364f121', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 2, 10, 'ነቢያትን፥ “አትንገሩን፤ ባለ ራእዮችንም አታውሩን፤ ነገር ግን ሌላውን ስሕተት አስረዱን፤ ንገሩንም” ይላሉ፤'),
  ('5ae6d925-9998-5667-ad96-2487a2cb91cf', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 3, 11, '“ከዚህ መንገድ መልሱን፤ ከዚህም ፈቀቅ አድርጉን በሉ፤ የእስራኤልንም ቅዱስ ትምህርት ከእኛ ዘንድ አስወግዱ” ይሏቸዋል።'),
  ('83803abd-2eb4-5eab-a081-81fc5b372dc1', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 4, 12, 'ስለዚህ የእስራኤል ቅዱስ እንዲህ ይላል፥ “ይህችን ቃል አቃልላችኋልና፥ በሐሰትና በጠማማነት ተስፋ አድርጋችኋልና፥ አጕረምርማችኋልምና፥ በዚህም ቃል ታምናችኋልና፤'),
  ('3cf96208-118e-591a-ab48-ffaa7024aa28', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 5, 13, 'ስለዚህ ይህ በደል አዘብዝቦ ለመፍረስ እንደ ቀረበ፥ አፈራረሱም ፈጥኖ ድንገት እንደሚመጣ እንደ ከተማ ቅጥር ይሆንባችኋል።'),
  ('e9b4a3f8-4dee-5d57-a155-1ac08694762b', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 6, 14, 'አወዳደቁም እንደ ሸክላ ሠሪ ገንቦ የደቀቀ ይሆናል፤ ሳይራራም ያደቅቀዋል፤ ከስባሪውም እሳት ከማንደጃ የሚወስዱበት፥ ወይም ውኃ ከጕድጓድ የሚቀዱበት ገል አይገኝም።”'),
  ('c46485e3-45ea-5507-ac3c-f9ebd14d53b1', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 7, 15, 'የእስራኤል ቅዱስ፥ ጌታ እግዚአብሔር እንዲህ ይላልና፥ “ብትጸጸትና ብታለቅስ ትድናለህ፤ የት እንዳለህም ታውቃለህ፤ በከንቱ ታምነሃልና፤ ኀይላችሁም ከንቱ ይሆናል፤ እናንተ ግን መስማትን እንቢ አላችሁ፤'),
  ('c825642c-a280-5eb2-aabe-c8d5f1e6dee5', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 8, 16, 'ነገር ግን፥ በፈረስ ላይ ተቀምጠን እንሸሻለን እንጂ እንዲህ አይሆንም አላችሁ፤ ስለዚህም ትሸሻላችሁ፤ ደግሞም በፈጣን ፈረስ ላይ እንቀመጣለን አላችሁ፤ ስለዚህም የሚያሳድዱአችሁ ፈጣኖች ይሆናሉ።'),
  ('aa79b021-6846-57f2-a331-45cdd8b4e9df', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 9, 17, 'ከአንድ ሰው ዛቻ የተነሣ ሺህ ሰዎች ይሸሻሉ፤ እናንተም በተራራ ራስ ላይ እንዳለ ምሰሶ፥ በኮረብታም ላይ እንዳለ ምልክት ሆናችሁ እስክትቀሩ ድረስ፥ ከአምስት ሰዎች ዛቻ የተነሣ ብዙዎች ይሸሻሉ።”'),
  ('92025ce3-8559-52eb-ac87-c5490b242960', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 10, 18, 'አምላካችን እግዚአብሔር ፈራጅ ነውና ስለዚህ እግዚአብሔር ይራራላችሁ ዘንድ ይታገሣል፤ ይምራችሁም ዘንድ ከፍ ከፍ ይላል፤ እርሱን በመተማመን የሚጠባበቁ ሁሉ ብፁዓን ናቸው።'),
  ('51768b94-e5d0-5508-a9ac-4d193bc711fd', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 11, 19, 'ቅዱስ ሕዝብ በኢየሩሳሌም ውስጥ በጽዮን ይኖራል፤ ልቅሶን አልቅሺ፤ ይቅር በለኝም በዪ፤ ልቅሶሽን ባየ ጊዜ ይቅር ይልሻል፤ ሰምቶሻልና።'),
  ('7f78b8b1-c038-5cb5-af95-1509dbfcc481', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 12, 20, 'እግዚአብሔርም የጭንቀትን እንጀራና የመከራን ውኃ ይሰጥሃል። የሚያሳስቱህም እንግዲህ ወደ አንተ አይቀርቡም፤ ዐይኖችህ ግን የሚያሳስቱህን ያያሉ፤'),
  ('ed451d1e-f15f-5af5-aa08-5148ccd20d3c', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 13, 21, 'ወደ ቀኝም ቢሆን ወደ ግራም ቢሆን በኋላህ በዚህ መንገድ እንሂድ የሚሉና የሚሳሳቱ ሰዎችን ድምፅ ጆሮዎችህ ይሰማሉ።'),
  ('55434066-837b-583d-af09-75e03648fac6', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 14, 22, 'በብርም ወደ ተለበጡ፥ በወርቅም ወደ አጌጡ ወደ ጣዖታቱ እንሂድ የሚሉ ናቸው፤ ያንጊዜ እንደ ትቢያ የደቀቁ ይሆናሉ፤ እንደ ውኃም ይደፈርሳሉ፤ በእነርሱም ጥራጊዎችን ይጥሉባቸዋል።'),
  ('c8c43e80-c880-54e7-a605-d7f37d9c9bb5', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 15, 23, 'በምድርም ለተዘራው ዘርህ ዝናም ይዘንማል፤ ከምድርም ፍሬ የሚወጣ እንጀራ ወፍራምና ብዙ ይሆናል። በዚያም ቀን ከብቶችህ በሰፊና በለመለመ መስክ ይሰማራሉ፤'),
  ('eb6f756a-4979-55fd-a3fb-bced450c7300', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 16, 24, 'መሬትንም የሚያርሱ በሬዎችና አህዮች በመንሽና በወንፊት የነጻውን ከገብስ ጋር የተቀላቀለውን ገፈራ ይበላሉ።'),
  ('1e80ab81-2b2b-51e8-aec8-b0e8c6f4f938', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 17, 25, 'በታላቅም እልቂት ቀን ግንቦች በወደቁ ጊዜ፥ በረዥሙ ተራራ ሁሉ ከፍ ባለውም ኮረብታ ሁሉ ላይ፥ ወንዞችና የውኃ ፈሳሾች ይሆናሉ።'),
  ('a5fc15ad-4a59-54a5-af92-e16f9cbb2804', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 18, 26, 'እግዚአብሔርም የሕዝቡን ስብራት በጠገነ ዕለት፥ በመቅሠፍቱ የቈሰለውንም በፈወሰ ዕለት፥ የጨረቃ ብርሃን እንደ ፀሐይ ብርሃን፥ የፀሐይም ብርሃን እንደ ሰባት ቀን ብርሃን ሰባት እጥፍ ይሆናል።'),
  ('d40d750b-f004-5c75-a3b5-4c262807e5c1', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 19, 27, 'እነሆ፥ የእግዚአብሔር ስም ከብዙ ጊዜ በኋላ ይመጣል፤ ቍጣውም ከከንፈሮቹ ቃል ክብር ጋር ይነድዳል፤ ቃሉም ቍጣን የተመላ ነው፤ የቍጣውም መቅሠፍት እንደምትበላ እሳት ናት፤'),
  ('15e46d18-adda-568c-a6fc-98733a273722', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 20, 28, 'እስትንፋሱም አሕዛብን ስለ ከንቱ ስሕተታቸው ሊከፋፍላቸው በሸለቆ እንደሚያጥለቀልቅ፥ እስከ አንገትም እንደሚደርስና እንደሚከፋፍል ውኃ ይጐርፋል፤ ስሕተታቸውም ይከተላቸዋል፤ ይወስዳቸዋልም።'),
  ('6a6775df-a282-59b4-a36c-7db27c1e0b1a', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 21, 29, 'በዐልን እንደሚያከብሩ፥ ሁልጊዜ ደስ ሊላችሁ፥ ወደ ተቀደሰው ቦታየም ልትሄዱ አይገባችሁምን? በእግዚአብሔር ተራራ ደስ እንደሚላቸው በእንቢልታ ወደ እስራኤል ቅዱስ ልትሄዱ ይገባችኋል።'),
  ('6918fe83-e34a-57bd-a0fc-424819981d6d', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 22, 30, 'እግዚአብሔርም የድምፁን ክብር ያሰማል፤ የክንዱንም መፈራት፥ በጽኑ ቍጣና በምትበላ እሳት፥ በወጀብም፥ በዐውሎ ነፋስም፥ በበረዶም ድንጋይ ይገልጣል።'),
  ('c378cd22-769d-55b2-af2c-63f2855e74fd', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 23, 31, 'አሦርም በመቅሠፍቱ ከመታው ከእግዚአብሔር ድምፅ የተነሣ ይደነግጣል።'),
  ('23284efa-8315-517e-abfd-46b45000c6be', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 24, 32, 'እግዚአብሔር በላዩ የሚያወርድበት የታዘዘበቱ የበትር ድብደባ ሁሉ በከበሮና በመሰንቆ ይሆናል፤ በጦርነትም ክንዱን አንሥቶ ይዋጋቸዋል።'),
  ('b50fb367-74a4-5884-ae70-7df3782f4ec3', '052bac2a-b9e5-5cd4-a131-3f2357162611', 'ccbb503d-25b5-5c87-a8e3-d6bd7186cef0', 25, 33, 'ከቀድሞም ጀምሮ የማቃጠያ ስፍራ ተዘጋጅታለች፤ ለንጉሥም ተበጅታለች፤ ጥልቅና ሰፊም አድርጎአታል፤ እሳትና ብዙ ማገዶ ተከምሮአል፤ የእግዚአብሔርም ቍጣ እንደ ዲን ፈሳሽ ያቃጥለዋል።'),
  ('4363c415-416e-56a4-af23-ad0e0f6a925e', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 1, 1, 'ርዳታ ለመፈለግ ወደ ግብፅ ለሚወርዱ፥ በፈረሶችና በሰረገሎችም ለሚታመኑ ወዮላቸው! ፈረሰኞቹ ብዙዎች ናቸውና፤ በእስራኤልም ቅዱስ አልታመኑምና፤ እግዚአብሔርንም አልፈለጉምና።'),
  ('9693f78e-87c6-5c22-abef-a7eebef80520', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 2, 2, 'እርሱ ግን ጠቢብ ነው፤ ክፉንም ነገር በላያቸው ያመጣል፤ ቃሉንም አይመልስም፤ በክፉዎችም ሰዎች ቤት ላይ በከንቱ ተስፋቸውም ላይ ይነሣል።'),
  ('c16da968-a82d-5cae-abbf-c5ac9dbdae7c', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 3, 3, 'ግብፃውያን ሰዎች እንጂ አምላክ አይደሉም፤ ፈረሶቻቸውም ሥጋ እንጂ መንፈስ አይደሉም፤ እግዚአብሔርም በእነርሱ ላይ እጁን በዘረጋ ጊዜ፥ ረጂው ይሰናከላል፤ ተረጂውም ይወድቃል፤ ሁሉም በአንድ ላይ ይጠፋሉ።'),
  ('cbe3ab47-4218-57ec-ae8e-71030cbc46a0', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 4, 4, 'እግዚአብሔር እንዲህ ይለኛልና፥ “አንበሳ ወይም የአንበሳ ደቦል በንጥቂያው ላይ እንደሚያገሣ፥ ድምፁም ተራሮችን እስኪሞላ በእርሱ ላይ እንደሚጮህ፥ እረኞችም ሁሉ ሲጮሁበት ከብዛታቸው የተነሣ እንደማይፈራ፥ ከድምፃቸውም የተነሣ እንደማይደነግጥ፥ እነርሱም ከቍጣው ብዛት የተነሣ ድል እንደሚሆኑና እንደሚደነግጡ፥ እንዲሁ የሠራዊት ጌታ እግዚአብሔር በጽዮን ተራራና በኮረብታዋ ላይ ይዋጋ ዘንድ ይወርዳል።'),
  ('0b899160-f194-51e7-acea-8b3e6bd8795d', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 5, 5, 'እንደሚበርር ወፍ እንዲሁ የሠራዊት ጌታ እግዚአብሔር ኢየሩሳሌምን ይጋርዳታል፤ ይከልላታልም፤ ይታደጋታል፤ አልፎም ያድናታል።'),
  ('53aa6c7c-1784-5a91-a23b-40129ab820bc', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 6, 6, 'ትበድሉ ዘንድ ጥልቅ ምክርን የምትመክሩ የእስራኤል ልጆች ሆይ፥ ተመለሱ።'),
  ('f8836ded-663a-579d-a0e0-f3bcce59f5b0', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 7, 7, 'በዚያም ቀን እያንዳንዳቸው እጆቻቸው የሠሩአቸውን የብሩንና የወርቁን ጣዖቶቻቸውን ይጥላሉ።'),
  ('3f6eb44b-a3cb-51ed-a8e7-8855a2c0df41', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 8, 8, 'አሦርም ይወድቃል፤ የሚወድቀውም በሰው ሰይፍ አይደለም፤ የምትበላቸውም የሰው ሰይፍ አይደለችም፤ የሚሸሹም ከሰይፍ ፊት አይደለም ጐልማሶቻቸው ግን ይሸነፋሉ።'),
  ('a22a4465-38f6-5cc7-a1ca-b26a924267a1', '74238940-a972-5816-a411-ae8c52271543', '8803db8d-cc20-5e04-a7fa-545b2000e77c', 9, 9, 'ዓለትም ትውጣቸዋለች ድልም ይሆናሉ የሸሸም ይያዛል። በጽዮን ዘርእ፥ በኢየሩሳሌምም ቤቶች ያሉት ብፁዕ ነው” ይላል እግዚአብሔር።'),
  ('bf9e42a5-4eca-57b7-a88c-5f0be13aa3e2', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 1, 1, 'እነሆ፥ ጻድቅ ንጉሥ ይነግሣል፤ መሳፍንትም በፍርድ ይገዛሉ።'),
  ('203e4424-6117-5597-ab38-719f361265a6', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 2, 2, 'ሰውም ቃሉን ይሰውራል፤ በውኃ እንደሚጠልቅም ይሰወራል፤ ክብሩም በደረቅ ምድር እንደሚፈስስ ውኃ በጽዮን ይገለጣል።'),
  ('901dcb25-cc71-5da0-a990-686bbb7927bc', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 3, 3, 'እንግዲህ በሰው አይታመኑም፤ በጆሮአቸው ያዳምጣሉ እንጂ።'),
  ('ca3db152-05a1-5454-af51-3ea3f33bf5e4', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 4, 4, 'የደካሞች ሰዎች ልብ ዕውቀትን ትሰማለች፤ የተብታቦችም ምላስ ፈጥና የሰላምን ነገር ትማራለች።'),
  ('638285bf-08bf-5824-aa05-1b390ef6e8fe', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 5, 5, 'ከእንግዲህ ወዲህ ሰነፍን አለቃ ይሆን ዘንድ ግድ አይሉትም፤ ከእንግዲህ ሎሌህ ዝም በል አይልህም።'),
  ('dc8ddff8-44a9-56d9-a6c2-a8609363c663', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 6, 6, 'ሰነፍ ግን ስንፍናን ይናገራል፤ ልቡም ዐመፅን ያደርግ ዘንድ፥ በእግዚአብሔር ላይ ስሕተትን ይናገር ዘንድ፥ የተራበችውንም ሰውነት ይበትን ዘንድ፥ የተጠማችንም ነፍስ ባዶ ያደርግ ዘንድ ከንቱን ያስባል።'),
  ('d2594a3f-8d3f-5e68-a230-9e230c743f52', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 7, 7, 'በዐመፃቸው ነገር ድሃውን ይገድሉት ዘንድ፥ የድሆችንም ፍርድ ይገለብጡ ዘንድ የክፉዎች ሕሊና ዐመፅን ትመክራለች።'),
  ('06c81b6f-119f-59f3-a634-166a5a555b4b', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 8, 8, 'ጻድቃን ግን ጥበብን ይመክራሉ፤ ምክራቸውም ትጸናለች።'),
  ('21cfdc52-9dc3-5754-a9e5-32b45ea2b7cc', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 9, 9, 'እናንተ ባለጸጎች ሴቶች ሆይ፥ ተነሡ፤ ድምፄንም ስሙ፤ እናንተ ተማምናችሁ የምትቀመጡ ሴቶች ልጆች ሆይ፥ ንግግሬን አድምጡ።'),
  ('7514fc76-c0da-56b1-a128-b3504814d7a9', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 10, 10, 'በየዓመቱ የኀዘን በዓል መታሰቢያ አድርጉ፤ ወይን መቍረጥ አልፎአል፤ ፍሬ ማከማችትም አልቆአል፤ ከእንግዲህም ወዲህ አይመጣም።'),
  ('27abdb92-c71c-5b61-a5ef-56b28883e8a7', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 11, 11, 'እናንተ ተማምናችሁ የምትቀመጡ ደንግጡ፤ ሴቶች ሆይ፥ እዘኑ፤ ልብሳችሁንም አውልቁ፤ ዕራቁታችሁንም ሁኑ፤ ወገባችሁንም በማቅ ታጠቁ።'),
  ('dede6eee-1ad1-5ef0-a6fd-e5dbed09c031', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 12, 12, 'ስለ ተወደደችዉ እርሻ ስለሚያፈራውም ወይን ደረታችሁን ድቁ።'),
  ('2f370abe-2a59-59bd-afdf-17c17c40d6b3', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 13, 13, 'በሕዝቤ ምድር ላይ በእርሻቸውም ላይ እሾህና አሜከላ ይበቅላሉ፤ ደስታም ከቤታቸው ሁሉ ይጠፋል።'),
  ('761a61ab-d749-5e72-aed0-b74a0f826059', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 14, 14, 'የበለጸገች ከተማና ቤቶችዋ ምድረ በዳ ይሆናሉ። የከተማውን ሀብትና ያማሩ ቤቶችን ይተዋሉ፤ አንባዎችም ለዘለዓለም ዋሻ፥ የምድረ በዳም አህያ ደስታ፥ የመንጎችም ማሰማሪያ ይሆናሉ።'),
  ('1b4afb68-d63f-530b-aa58-78fb82741767', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 15, 15, 'ይህም፥ መንፈስ ከላይ እስኪመጣላችሁ፥ ምድረ በዳውም ፍሬያማ እርሻ እስኪሆን፥ ፍሬያማውም እርሻ ዱር ተብሎ እስኪቈጠር ድረስ ይሆናል።'),
  ('e574ae07-3430-5152-a52f-b8932ebe9e2d', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 16, 16, 'ከዚያ በኋላ ፍርድ በምድረ በዳ ይኖራል፤ ጽድቅም በፍሬያማው እርሻ ያድራል።'),
  ('6709348e-b569-5a96-ac60-f70fca2bdb0f', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 17, 17, 'የጽድቅም ሥራ ሰላም ይሆናል፤ ጽድቅም የዕረፍት ቦታን ይይዛል፤ ለዘለዓለምም ይታመኑበታል።'),
  ('b0daf6d2-f5bc-5f68-a219-f35409cfb297', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 18, 18, 'ሕዝቤም በሰላም ከተማ ይኖራል። ተዘልሎም በውስጥዋ ያድራል፤ በብልጽግናም ያርፋል።'),
  ('58dddd64-2ece-585c-a60f-302f8570c47c', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 19, 19, 'በረዶ ቢወርድ አይደርስባችሁም፤ በዛፍ ሥር የሚኖሩ ሰዎች በበረሃ እንደሚኖሩ ሰዎች ታምነው ይኖራሉ።'),
  ('6a0fc7aa-4c7b-51e8-ac87-0f7039a30a29', '88dbebbd-b328-5d99-ae16-cdc317b7d1f5', '2dba2f63-e614-56ba-a75e-7f46594a110b', 20, 20, 'ውኃ ባለበት፥ በሬና አህያም በሚረግጠው ቦታ የሚዘሩ ብፁዓን ናቸው።'),
  ('eccef9f8-b7c9-5891-a12c-298c980fe206', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 1, 1, 'ለሚያዋርዱአችሁ ወዮላቸው! እናንተን ግን የሚያዋርዳችሁ የለም፤ የሚወነጅላችሁ እናንተን የሚወነጅል አይደለም፤ ወንጀለኞች ይጠመዳሉ፤ ይያዛሉም፤ ብል እንደበላው ልብስም ያልቃሉ።'),
  ('222a737d-9fa4-58ce-a354-d00180e4b321', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 2, 2, 'አቤቱ፥ ማረን፤ አንተን ተማምነናልና፤ የዐላውያን ዘራቸው ለጥፋት ነው፤ በመከራም ጊዜ መድኀኒታችን አንተ ነህ።'),
  ('611f22ef-08c0-5f02-a785-be569d443324', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 3, 3, 'ከቃልህ ግርማ የተነሣ አሕዛብ ፈርተው ሸሹ፤ አሕዛብም ተበተኑ።'),
  ('6ea845fd-2153-5ceb-aff0-abe53d692199', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 4, 4, 'አንበጣ እንደሚሰበሰብ ትንሹም ትልቁም ምርኮአችሁ እንዲሁ ይሰበሰብላችኋል።'),
  ('f402ea56-52ff-5397-aa1f-efebbe938c18', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 5, 5, 'በአርያም የሚኖር ቅዱስ እግዚአብሔር በመካከላችሁ ይኖራል፤ ጽዮንም ፍርድንና ጽድቅን ተሞላች።'),
  ('2ef66c97-71ee-54a7-a857-de0075b96c3e', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 6, 6, 'በድኅነታችን መዝገብ በሕግ ይሰበስቡአቸዋል፤ ጥበብና ምክር፥ ጽድቅም ከእግዚአብሔር ዘንድ ናቸው፤ እነዚህም የጽድቅ መዝገቦች ናቸው።'),
  ('4628a2d8-bb89-50cb-a60e-50febec7ceb2', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 7, 7, 'እነሆ እናንተ ቀድሞ ትፈሩአቸው የነበሩ በግርማችሁ ይፈሩአችኋል፤ ከእናንተም የተነሣ ይንቀጠቀጣሉ። መልእክተኞች መራራ ልቅሶን እያለቀሱ ይላካሉ፤ ሰላምንም ይለምናሉ።'),
  ('fb6767db-239c-5db3-abae-84f24d2ff8ea', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 8, 8, 'መንገዶች ባድማ ሆኑ፤ የአሕዛብም መፈራት ቀረ፤ ቃል ኪዳናቸውም ፈረሰ፤ እንደ ሰውም አልተመለከታቸውም።'),
  ('9bf3d5ef-3d71-55a3-a735-763feff72dc9', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 9, 9, 'ምድር አለቀሰች፤ ሊባኖስ አፈረ፤ ሳሮንም እንደ ምድረ በዳ ሆነ፤ ገሊላና ቀርሜሎስ ታወቁ።'),
  ('3e00a3e2-0673-56db-adbf-50547badf289', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 10, 10, 'እግዚአብሔር እንዲህ ይላል፥ “አሁን እነሣለሁ፤ አሁን እከብራለሁ፤ አሁን ከፍ ከፍ እላለሁ።'),
  ('aa195ac3-de86-521b-a3fa-320b8f829a1c', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 11, 11, 'ዛሬ ታያላችሁ፤ ዛሬ ታደንቃላችሁ፤ የመንፈሳችሁም ኀይል ከንቱ ይሆናል፤ እሳትም ትበላችኋለች።'),
  ('82d0780a-60de-509d-a99e-40dbfffff93b', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 12, 12, 'አሕዛብም በእርሻ ውስጥ ተቈርጦ እንደ ተጣለና በእሳት እንደ ተቃጠለ እሾህ የተቃጠሉ ይሆናሉ።”'),
  ('879b69fb-292e-55eb-aa89-0ce295d87114', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 13, 13, 'በሩቅ ያሉ የሠራሁትን ይሰማሉ፤ በቅርብም ያሉ ኀይሌን ያውቃሉ።'),
  ('1beeb24e-4c9e-5c77-a788-cff28804db71', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 14, 14, 'በጽዮን ያሉ ኀጢአተኞች ፈሩ፤ መንቀጥቀጥ ዝንጉዎችን ያዘ፤ እሳት እንደሚነድድ የሚነግራችሁ ማን ነው? የዘለዓለም ሀገርንስ የሚነግራችሁ ማን ነው?'),
  ('12c4a869-e27c-5b3c-abba-f80eb5cd60d0', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 15, 15, 'በጽድቅ የሚሄድ፥ ቅን ነገርንም የሚናገር፥ በደልንና ኀጢአትን የሚጠላ፥ መማለጃን ከመጨበጥ እጁን የሚያራግፍ፥ ደም ማፍሰስን ከመስማት ጆሮቹን የሚደፍን፥ ክፋትንም ከማየት ዐይኖቹን የሚጨፍን ነው።'),
  ('95bd05bc-fc5c-56bb-ad07-229801233d7d', '255346dc-b32c-54fe-ade5-a4585575a773', 'cbe6d907-f190-58a9-ad08-51ae0c87340d', 16, 16, 'እርሱ ከፍ ባለ በጽኑዕ ዓለት ዋሻ ይኖራል፤ እንጀራም ይሰጠዋል፤ ውኃውም የታመነች ትሆናለች።'),
  ('787279ba-b9cd-5ed7-a5f6-ecc957f1e77b', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 1, 17, 'ንጉሥን በክብሩ ታዩታላችሁ፤ ዐይኖቻችሁም በሩቅ ያለች ምድርን ያዩአታል።'),
  ('a5c91988-33e3-54e2-ae49-6d6449fb6234', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 2, 18, 'ልባችሁም፥ “ጸሓፊዎች ወዴት አሉ? መማክርትስ ወዴት አሉ? የትንሹና የትልቁ ዐማፅያን ብዛትስ ወዴት አለ?” ብሎ ፍርሀትን ያስባል።'),
  ('eb3bc4d9-2536-5c89-a689-aabf39c2b156', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 3, 19, 'የማታውቋቸውን አሕዛብ አመጣባችኋለሁ፤ እናንት ዐማፅያን ሕዝብ፥ ጥልቅ ነገርን ትሰማላችሁ። የሚሰማም ማስተዋል እንደሌለው ይሆናል።'),
  ('3e93c5ea-a389-5b78-a9fd-50f1d86177e6', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 4, 20, 'እነሆ፥ የመድኀኒታችንን ከተማ ጽዮንን ተመልከት፤ ዐይኖችህም ድንኳኖችዋ የማይናወጡ፥ ካስማዎችዋ ለዘለዓለም የማይነቀሉ፥ አውታሮችዋም ሁሉ የማይበጠሱ፥ የበለጸገች ከተማ ኢየሩሳሌምን ያያሉ።'),
  ('08d52e7a-a53b-5928-a471-48040cd0198b', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 5, 21, 'የእግዚአብሔር ስም ለእናንተ ታላቅ ነው፤ ሀገራችሁም የሰፉ ወንዞችና ታላቅ የመስኖ ስፍራ ይሆናል፤ በዚህች መንገድ አትሄድም፤ መርከቦችም አይሄዱም።'),
  ('f21d6433-df15-5b30-ab13-2a81778bbbbc', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 6, 22, 'አምላካችን እግዚአብሔር ታላቅ ነውና ቸል አይለንም፤ እግዚአብሔር ፈራጃችን ነው፤ እግዚአብሔር አምላካችን ነው። እግዚአብሔር ንጉሣችን ነው፤ እርሱ እግዚአብሔር ያድነናል።'),
  ('038b07d4-acdc-5ec6-a75a-8a833041b3a4', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 7, 23, 'ገመዶችሽ ተበጥሰዋል፤ ጥንካሬ የላቸውምና፤ ደቀልሽ ዘመመ፤ ሸራውንም መዘርጋት አልቻለም፤ እስከሚያዝም ድረስ አላማውን አልተሸከመም። በዚያን ጊዜ የብዙ ምርኮ ተከፈለ፤ ብዙ አንካሶች እንኳ ምርኮውን ማረኩ።'),
  ('d32ed164-b003-5e06-a9fc-81dfb74e093e', '255346dc-b32c-54fe-ade5-a4585575a773', '6aa3cf28-20cb-5156-a9b2-ac2de6c56ae0', 8, 24, 'በውስጣቸውም የሚቀመጥ ሕዝብ፦ ደክሜአለሁ አይልም፥ በደላቸው ይቅር ይባልላቸዋልና።'),
  ('2aed9566-46e4-55ff-a7d0-8b377c2cbfb7', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 1, 1, 'እናንተ አሕዛብ ሆይ፥ ቅረቡ፤ እናንተም አለቆች ሆይ፥ አድምጡ፤ ምድርና በውስጥዋም ያሉ፥ ዓለምና በውስጥዋም ያሉ ሕዝብ ሁሉ ይስሙ።'),
  ('5703c4a7-b27b-5a75-aa4b-d7644e0334ce', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 2, 2, 'የእግዚአብሔር ቍጣ በአሕዛብ ሁሉ ላይ ነውና፤ መቅሠፍቱም ያጠፋቸውና ለጦር ይሰጣቸው ዘንድ በቍጥራቸው ልክ ነው።'),
  ('fde3554a-a366-559f-a7ba-48a7159deddd', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 3, 3, 'ከእነርሱም የተገደሉት በድናቸው ይጣላል፤ የሬሳቸውም ግማት ይሸታል፤ ተራሮቹም ከደማቸው የተነሣ ይርሳሉ።'),
  ('f5628ad7-69f0-59f4-a861-82c6ba9113f9', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 4, 4, 'ሰማያት እንደ መጽሐፍ ጥቅልል ይጠቀለላሉ፤ ከወይንና ከበለስም ቅጠል እንደሚረግፍ ከዋክብት ሁሉ ይረግፋሉ።'),
  ('356dc8dd-bc09-5ddc-a675-cf0ab5627d51', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 5, 5, 'ሰይፌ በሰማይ ሆና ሰከረች፤ እነሆ፥ በኤዶምያስና በሚጠፉት ሕዝብ ላይ ለፍርድ ትወርዳለች።'),
  ('2334e011-6d8e-57ee-abe4-5d1606c01c4f', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 6, 6, 'እግዚአብሔር መሥዋዕት በባሶራ፥ ታላቅም እርድ በኤዶምያስ ምድር አለውና የእግዚአብሔር ሰይፍ በደም ተሞልታለች፤ በበግ ስብ፥ በፍየል ደምም፥ በአውራም በግ ስብ ወፍራለች።'),
  ('41eee337-302b-55b7-abf4-425f5f84aded', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 7, 7, 'ኀያላን ከእነርሱ ጋር፥ ወይፈኖችም ከኮርማዎች ጋር ይወድቃሉ፤ ምድራቸውም በደም ትሰክራለች፤ በስባቸውም ትወፍራለች።'),
  ('2f826388-1be6-5af1-afe2-e7078951571c', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 8, 8, 'የእግዚአብሔር የፍርዱ ቀን፥ ስለ ጽዮንም ፍርድ የብድራት ዓመት ነውና።'),
  ('f0038191-e531-5012-a213-f079149a241d', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 9, 9, 'ሸለቆዎችዋ ዝፍት ሆነው ይወጣሉ፤ አፈርዋም ዲን ይሆናል፤ መሬቷም በቀንና በሌሊት እንደ ዝፍት ይቃጠላል፤ ለዘለዓለምም አይጠፋም፤'),
  ('cd628f8f-c2a0-5a2f-a920-475652893e5d', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 10, 10, 'ጢሱም ወደላይ ይወጣል፤ ከትውልድ እስከ ትውልድም ድረስ ባድማ ሆና ትኖራለች፤ ለብዙ ዘመናትም ትጠፋለች።'),
  ('f28332ae-6d65-5408-ac3c-c91207a092be', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 11, 11, 'ጭልፊቶችና ጃርት፥ ጕጕትና ቍራም ይኖሩባታል፤ መሠረቷንም በመፍረስ ገመድ ይለካሉ። አጋንንትም ያድሩባታል፤'),
  ('20a961cf-0b1c-5fc0-ae9c-4acb711665f7', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 12, 12, 'አለቆችዋ ያልቃሉ፤ ነገሥታቷና መሳፍንቷ ይጠፋሉ።'),
  ('50a9169b-adea-5432-a91f-603eb7fe656c', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 13, 13, 'በከተማዎችዋም እሾህ፥ በቅጥሮችዋም አሜከላ ይበቅሉባታል፤ የአጋንንት ማደሪያና የሰጎን ስፍራ ትሆናለች።'),
  ('201ac501-92f9-5dc4-a617-2fd4e2520ac1', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 14, 14, 'በዚያም አጋንንትና ጂኖች ይገናኛሉ፤ እነርሱም እርስ በርሳቸው ይጠራራሉ፤ ጂኖችም በዚያ ይኖራሉ፤ ለራሳቸውም ማረፊያን ያገኛሉ።'),
  ('c2d5c805-d83b-5a49-a0fa-a7dc69a30022', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 15, 15, 'በዚያ ጃርቶች ይዋለዳሉ፤ ምድርም ልጆችዋን በኀይል ታድናለች፤ ዋሊያዎች በዚያ ይገናኛሉ፤ ፊት ለፊትም ይተያያሉ።'),
  ('6b33153f-f1a1-5c18-a3b6-e0ca8c0d29bf', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 16, 16, 'በየቍጥራቸው ያልፋሉ፤ ከእነርሱም አንዱ አይጠፋም፤ እርስ በርሳቸው አይተጣጡም፤ የሠራዊት ጌታ እግዚአብሔር አዝዞአቸዋልና መንፈሱም ሰብስቦአቸዋልና።'),
  ('c0774d07-965e-55d2-ab54-65965e78e564', 'ca6112b4-467c-5f28-af9d-374d408c3481', '6aa17b0f-278e-5306-ab71-233d2f916c94', 17, 17, 'እርሱም ዕጣ ጣለባቸው፤ እጁም ከፈለችላቸው፤ ለዘለዓለም ይሰማሩባታል፤ ከትውልድም እስከ ትውልድ ድረስ ይወርሱአታል፤ በውስጥዋም ያርፉባታል።'),
  ('3ecaabb3-7bca-58dc-a153-f9347361f7a8', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 1, 1, 'የተጠማው ምድረ በዳ ደስ ይለዋል፤ በረሃውም ሐሤት ያደርጋል፤ እንደ ጽጌረዳም ያብባል።'),
  ('eddf157c-8f69-5a77-a5ae-a518ca7672c7', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 2, 2, 'የዮርዳኖስም ምድረ በዳ ያብባል፤ ሐሤትንም ያደርጋል፤ የሊባኖስ ክብርና የቀርሜሎስ ክብር ይሰጠዋል፤ ሕዝቤም የጌታን ክብር፥ የአምላክንም ግርማ ያያሉ።'),
  ('1ff4cc0e-4aba-5093-ab97-6f013594846b', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 3, 3, 'ደካሞች እጆችና አንካሶች ጕልበቶች፥ ጽኑ።'),
  ('1ad44a14-c8a1-5fb7-a50d-82b22143f7b5', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 4, 4, 'እናንተ አእምሮ የሌላችሁ፥ ልቡናችሁን አረጋጉ፤ ጽኑ፤ አትፍሩ፤ እነሆ፥ አምላካችን ፍርድን ይመልሳል፤ ይበቀላልም፤ እርሱም መጥቶ ያድነናል።'),
  ('548bf8f9-52d4-5325-a3f4-e68deb4cdea0', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 5, 5, 'በዚያን ጊዜም የዕውሮች ዐይኖቻቸው ይገለጣሉ፤ የደንቆሮዎችም ጆሮዎች ይሰማሉ።'),
  ('820bef29-cb63-51d7-a580-d3b64be0b628', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 6, 6, 'በዚያን ጊዜ አንካሳዎች እንደ ሚዳቋ ይዘልላሉ፤ የዲዳዎችም ምላስ ርቱዕ ይሆናል፤ በምድረ በዳ ውኃ፥ በተጠማ መሬትም ፈሳሽ ይፈልቃልና።'),
  ('1c155bcb-43f7-55ce-af22-3b9acfbcb66f', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 7, 7, 'ደረቂቱ ምድር ኩሬ፥ የተጠማች ምድርም የውኃ ምንጭ ትሆናለች፤ የዎፎች መኖሪያም ሸንበቆና ደንገል ይሆንበታል።'),
  ('75366546-9f8c-5619-a7dc-8651dd160a0a', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 8, 8, 'በዚያም ንጹሕ መንገድ ይሆናል፤ እርሱም የተቀደሰ መንገድ ይባላል፤ በዚያም ንጹሓን ያልሆኑ አያልፉበትም፤ ርኩስ መንገድም በዚያ አይኖርም፤ የተበተኑትም በእርሱ ይሄዳሉ፤ አይሳሳቱምም።'),
  ('f0cc6f1c-7227-5824-a447-7a7966bced46', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 9, 9, 'አንበሳ አይኖርበትም፤ ክፉ አውሬም አይወጣበትም፤ በዚያም አይገኙም፤ የዳኑት ግን በዚያ ይሄዳሉ።'),
  ('991655a0-0318-5384-a5e0-5025a332c6f9', 'cd8a106c-41d8-5bc6-ad49-1d32cc72e5df', '8c25c87a-9c4e-59cf-adf9-795077ea0eca', 10, 10, 'በእግዚአብሔር የተሰበሰቡም ይመለሳሉ፤ በደስታም ተመልሰው ወደ ጽዮን ይመጣሉ፤ የዘለዓለም ደስታም በራሳቸው ላይ ይሆናል፤ ሐሤትንና ደስታንም ያገኛሉ፤ መከራ፥ ኀዘንና ትካዜም ይጠፋሉ።'),
  ('f8a0d9e4-b729-5670-a2ac-40624c5fdb49', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 1, 1, 'እንዲህም ሆነ፤ በንጉሡ በሕዝቅያስ በዐሥራ አራተኛው ዓመተ መንግሥት የአሦር ንጉሥ ሰናክሬም ወደ ይሁዳ ወደ ተመሸጉት ከተሞች ሁሉ ወጥቶ ወሰዳቸው።'),
  ('09283222-e5a4-5364-a75f-799939e6cf8c', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 2, 2, 'የአሦርም ንጉሥ ራፋስቂስን ከብዙ ሠራዊት ጋር ከለኪሶ ወደ ንጉሡ ወደ ሕዝቅያስ ወደ ኢየሩሳሌም ላከው፤ እርሱም በአጣቢው እርሻ መንገድ ባለችው በላይኛዪቱ ኵሬ መስኖ አጠገብ ቆመ።'),
  ('ca469b5c-2814-5872-a287-11f93987d40f', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 3, 3, 'የቤቱም አዛዥ የኬልቅያስ ልጅ ኤልያቄም፥ ጸሓፊውም ሳምናስ፥ ታሪክ ጸሓፊውም የአሳፍ ልጅ ዮአስ ወደ እርሱ ወጡ።'),
  ('8fc0d72e-b8cb-5849-acf4-b5a58831ae51', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 4, 4, 'ራፋስቂስም አላቸው፥ “ለሕዝቅያስ እንዲህ ብላችሁ ንገሩት፦ ታላቁ የአሦር ንጉሥ እንዲህ ይላል፦ በማን ትተማመናለህ?'),
  ('20e7799b-af80-53bf-ad6d-4398de407866', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 5, 5, 'በምክርና በከንፈር ንግግር ጦርነት ይሆናልን? አሁንም በእኔ ላይ ያመፅኸው በማን ተማምነህ ነው?'),
  ('b063a922-80b4-5cd5-a78e-35bbc0b92f3f', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 6, 6, 'እነሆ፥ በዚያ በተቀጠቀጠ በሸንበቆ በትር በግብፅ ትታመናለህ፤ ሰው ቢመረኰዘው ተሰብሮ በእጁ ይገባል፤ የግብፅ ንጉሥ ፈርዖን ለሚታመኑበት ሁሉ እንዲሁ ነው።'),
  ('7c3ecb88-588e-5310-a316-9b286f1ace99', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 7, 7, 'አንተም፦ በአምላካችን በእግዚአብሔር እንታመናለን ብትል፥ ሕዝቅያስ ይሁዳንና ኢየሩሳሌምን፦ በዚህ መሥዊያ ፊት ስገዱ ብሎ የኮረብታ መስገጃዎቹንና መሠዊያዎቹን ያስፈረሰ ይህ አይደለምን?'),
  ('f86cf22e-8696-5b69-ac4d-2d16ba64d3e5', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 8, 8, 'አሁን እንግዲህ ከጌታዬ ከአሦር ንጉሥ ጋር ተስማማ፤ የሚቀመጡባቸውንም ሰዎች ማግኘት ቢቻልህ እኔ ሁለት ሺህ ፈረሶችን እሰጥሃለሁ።'),
  ('f1df9e70-b2f6-5b69-ae44-de8a7889dcdc', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 9, 9, 'ከታናናሾቹ ከጌታዬ አገልጋዮች የሚያንሰውን የአንዱን ጭፍራ ፊት መመለስ እንዴት ትችላለህ? ስለ ሰረገሎችና ፈረሰኞች በግብፅ የሚታመኑ ለጌታዬ ባሮች ናቸው።'),
  ('e3a7a103-a60a-5106-a33f-d5d3afcc4fb4', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 10, 10, 'አሁንም በውኑ ያለ እግዚአብሔር ትእዛዝ እናጠፋችሁ ዘንድ ወደዚህ ሀገር ዘምተናልን? እግዚአብሔር፦ ወደ ሀገራቸው ዘምታችሁ አጥፉአቸው” አለን።'),
  ('81fc3b88-75e8-5e3c-a8c8-dbdfa0bc5a0a', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 11, 11, 'ኤልያቄምና ሳምናስ፥ ዮአስም ራፋስቂስን፥ “እኛ እንሰማለንና እባክህ፥ በሶርያ ቋንቋ ለባሪያዎችህ ተናገር፤ በቅጥርም ላይ ባለው ሕዝብ ጆሮ በዕብራይስጥ አትናገረን” አሉት።'),
  ('fbb0e8f6-bc9e-5218-a45f-abee40463d14', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 12, 12, 'ራፋስቂስ ግን፥ “ጌታዬ ይህን ቃል እናገር ዘንድ ወደ እናንተና ወደ ጌታችሁ ልኮኛልን? ከእናንተ ጋር ኵሳቸውን ይበሉ ዘንድ፥ ሽንታቸውንም ይጠጡ ዘንድ በቅጥር ላይ ለተቀመጡት ሰዎች እነግራቸው ዘንድ አይደለምን?” አላቸው።'),
  ('bda632cd-620f-587f-afb3-72d58ed8c7b1', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 13, 13, 'ራፋስቂስም ቆሞ በታላቅ ድምፅ በዕብራይስጥ እንዲህ ብሎ ጮኸ፥ “የታላቁን የአሦርን ንጉሥ ቃል ስሙ።'),
  ('1b2a3490-3d06-5ade-a00e-8be68ecc98a0', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 14, 14, 'ንጉሡ እንዲህ ይላል፦ ያድናችሁ ዘንድ በማይችል ቃል ሕዝቅያስ አያታልላችሁ።'),
  ('f717e8b2-ec01-5505-aae1-15f20e2743db', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 15, 15, 'ሕዝቅያስም፦ እግዚአብሔር በእርግጥ ያድናችኋል፤ ይህችም ከተማ በአሦር ንጉሥ እጅ አትሰጥም አይበላችሁ።'),
  ('a41349df-a5ca-53e9-a7b6-e846c07be1b3', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 16, 16, 'ሕዝቅያስንም አትስሙ፤ የአሦር ንጉሥ እንዲህ ይላል፦ በሕይወት ልትኖሩ ብትወድዱ ሁላችሁ ወደ እኔ ውጡ፤ እያንዳንዳችሁም ከወይናችሁና ከበለሳችሁ ትበላላችሁ፤ ከጕድጓዳችሁም ውኃ ትጠጣላችሁ፤'),
  ('f7ef9110-5335-5758-a65f-ab9716611de7', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 17, 17, 'ይህም መጥቼ ምድራችሁን ወደምትመስለው ምድር፥ እህልና የወይን ጠጅ፥ እንጀራና ወይን ወዳለባት ምድር እስካፈልሳችሁ ድረስ ነው።'),
  ('2935a3fa-a6ef-5f4b-a630-87beb57ef2ca', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 18, 18, 'ሕዝቅያስም፦ እግዚአብሔር ያድነናል ብሎ አያታልላችሁ። በውኑ የአሕዛብ አማልክት ሀገሮቻቸውን ከአሦር ንጉሥ እጅ አድነዋቸዋልን?'),
  ('1d59151c-8e66-5c95-afa2-bdf742fec666', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 19, 19, 'የሐማትና የአርፋድ አማልክት ወዴት አሉ? ሰማርያን ከእጄ አድነዋታልን?'),
  ('b32ee7ea-d982-5573-a3d1-33932ed14864', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 20, 20, 'እግዚአብሔር ኢየሩሳሌምን ከእጄ ያድን ዘንድ ከእነዚህ ሀገሮች አማልክት ሁሉ ሀገሩን ከእጄ ያዳነ አለን?”'),
  ('1bdffe8a-a04b-5923-a465-75625d0d4ea5', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 21, 21, 'እነርሱም ዝም አሉ፤ አንዳችም አልመለሱለትም፤ ንጉሡ እንዳይመልሱለት አዝዞ ነበርና።'),
  ('95bd867e-a303-5236-a984-06ea87bc3bdc', 'afed8152-1073-55e7-abdd-9d794e917d38', '4a667de3-2ea1-5104-ae43-9fddef1c78e5', 22, 22, 'የቤቱ አዛዥ የኬልቅያስ ልጅ ኤልያቄም፥ የሠራዊቱ ጸሓፊ ሳምናስ፥ ታሪክ ጸሓፊውም የአሳፍ ልጅ ዮአስ ልብሳቸውን ቀድደው ወደ ሕዝቅያስ መጡ፤ የራፋስቂስንም ቃል ነገሩት።'),
  ('6aba1095-5e9a-571b-a928-76e92a9ef523', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 1, 1, 'እንዲህም ሆነ፤ ንጉሡ ሕዝቅያስ ይህን በሰማ ጊዜ ልብሱን ቀደደ፤ ማቅም ለበሰ፤ ወደ እግዚአብሔርም ቤት ገባ።'),
  ('c31c0b79-90b0-5472-addc-81d7cfc885d2', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 2, 2, 'የቤቱንም አዛዥ ኤልያቄምን፥ ጸሓፊውንም ሳምናስን፥ የካህናቱንም ሽማግሌዎች ማቅ ለብሰው ወደ ነቢዩ ወደ አሞጽ ልጅ ወደ ኢሳይያስ ይሄዱ ዘንድ ላካቸው።'),
  ('9d999611-5432-5683-a83a-231e6a4c91f6', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 3, 3, 'እነርሱም፥ “ሕዝቅያስ እንዲህ ይላል፦ ይህ ቀን የመከራና የተግሣጽ፥ የዘለፋም ቀን ነው፤ ልጆች የሚወለዱበት ጊዜ ደርሶአል፤ ለመውለድም ኀይል የለም።'),
  ('55b0af9c-1b45-5c8f-a448-1d65d638ebb6', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 4, 4, 'ምናልባት በሕያው አምላክ ላይ ይገዳደር ዘንድ ጌታው የአሦር ንጉሥ የላከውን የራፋስቂስን ቃል አምላክህ እግዚአብሔር ይሰማ እንደ ሆነ፥ አምላክህ እግዚአብሔርም ስለ ሰማው ቃል ይገሥጸው እንደ ሆነ፥ ስለዚህ ለቀረው ቅሬታ ጸልይ” አሉት።'),
  ('84e51e75-bfd6-529f-a8b2-87d4456ff723', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 5, 5, 'እንዲሁ የንጉሡ የሕዝቅያስ ብላቴኖች ወደ ኢሳይያስ በመጡ ጊዜ፥'),
  ('74993263-cef5-541c-a020-ee857a1a2474', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 6, 6, 'ኢሳይያስ፥ “ለጌታችሁ፦ እግዚአብሔር እንዲህ ይላል፦ የአሦር ንጉሥ ባሪያዎች ስለ ሰደቡኝ፥ ስለ ሰማኸው ቃል አትፍራ።'),
  ('1fe697f5-c33b-5fdb-a2bc-33f0280760d1', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 7, 7, 'እነሆ፥ መንፈስን በላዩ እሰድዳለሁ፤ ወሬንም ይሰማል፤ ወደ ምድሩም ይመለሳል፤ በምድሩም በሰይፍ እንዲወድቅ አደርጋለሁ በሉት” አላቸው።'),
  ('bbaed255-8238-5b70-a806-0423999d796d', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 8, 8, 'የአሦርም ንጉሥ ከለኪሶ እንደ ራቀ ሰምቶ ነበርና ራፋስቂስ ተመልሶ በልብና ሲዋጋ አገኘው።'),
  ('aa83f82a-6747-583b-a879-87049938f4b6', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 9, 9, 'እርሱም፥ “የኢትዮጵያ ንጉሥ ቲርሐቅ ሊዋጋህ መጥቶአል” የሚል ወሬ ሰማ። በሰማም ጊዜ ወደ ሕዝቅያስ መልእክተኞችን ላከ፤ እንዲህ ሲል፦'),
  ('98b2da19-93ef-5c7a-a1df-c5618d34ce37', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 10, 10, '“ለይሁዳ ንጉሥ ለሕዝቅያስ እንዲህ ብላችሁ ንገሩት፦ ኢየሩሳሌም በአሦር ንጉሥ እጅ አትሰጥም ብሎ የምትታመንበት አምላክህ አያታልልህ።'),
  ('28cf04e0-074f-5aae-a83b-7b569d4a54ae', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 11, 11, 'እነሆ፥ የአሦር ነገሥታት በምድር ሁሉ ላይ ያደረጉትን እንዴትስ እንዳጠፉአቸው አልሰማህምን? አንተስ ትድናለህን?'),
  ('b82ee75c-4bc1-5511-aa78-3d20c1292a92', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 12, 12, 'አባቶች ያጠፉአቸውን በቴማን ያሉትን ጎዛንንና ካራንን፥ ራፌስንም የአሕዛብ አማልክት አዳኑአቸውን?'),
  ('500dc41a-d63d-5e54-a7a0-fd9b1f609156', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 13, 13, 'የሔማትና የአርፋድ፥ የሴፈርዋይ ከተማ፥ የሄናና የዒዋ ነገሥታት ወዴት አሉ?”'),
  ('e81f90d8-79ab-5d0d-aadd-279d063e49bc', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 14, 14, 'ሕዝቅያስም ደብዳቤውን ከመልእክተኞች እጅ ተቀብሎ አነበበው፤ ሕዝቅያስም ወደ እግዚአብሔር ቤት ወጥቶ በእግዚአብሔር ፊት ዘረጋው።'),
  ('461bd588-79c3-5240-a9ec-984f28333785', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 15, 15, 'ሕዝቅያስም ወደ እግዚአብሔር እንዲህ ብሎ ጸለየ፦'),
  ('c07788f8-c215-53ff-a736-75cc1046f386', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 16, 16, '“አቤቱ፥ በኪሩቤል ላይ የምትቀመጥ የእስራኤል አምላክ የሠራዊት ጌታ ሆይ፥ አንተ ብቻህን የምድር መንግሥታት ሁሉ አምላክ ነህ፤ ሰማይንና ምድርን ፈጥረሃል።'),
  ('3efe403f-2771-5fc5-a6d7-b555ab4a37c5', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 17, 17, 'አቤቱ፥ ጆሮህን አዘንብልና ስማ፤ አቤቱ፥ ዐይንህን ክፈትና በሕያው አምላክ ላይ ይገዳደር ዘንድ የላከውን የሰናክሬምን ቃል ተመልከት።'),
  ('f6fc55c4-8b28-5859-a3f4-cfc3e726204e', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 18, 18, 'አቤቱ፥ በእውነት የአሦር ነገሥታት ዓለሙን ሁሉ ሀገሮቻቸውንም አፍርሰዋል፤'),
  ('967c5dcc-4243-548b-aa4b-dc3d1dcb4735', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 19, 19, 'አማልክቶቻቸውንም በእሳት አቃጥለዋል፤ የእንጨትና የድንጋይ የሰው እጅ ሥራም ነበሩ እንጂ አማልክት አልነበሩምና ስለዚህ አጥፍተዋቸዋል።'),
  ('1ac10c32-03f8-51eb-adcd-5b3bdc4aab4b', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '8b6f998d-9936-55df-af07-b27f1b80a92f', 20, 20, 'እንግዲህ አምላካችን አቤቱ፥ የምድር ነገሥታት ሁሉ አንተ ብቻ እግዚአብሔር እንደ ሆንህ ያውቁ ዘንድ ከእጁ አድነን።”'),
  ('7d92f3e2-b652-5f62-af8e-c7a2a2baf43a', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 1, 21, 'የአሞጽ ልጅ ኢሳይያስም ወደ ሕዝቅያስ ተላከ፤ እንዲህም አለው፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ስለ አሦር ንጉሥ ስለ ሰናክሬም ወደ እኔ የጸለይኸውን ሰምቼሃለሁ።'),
  ('9c7f19e8-a394-5f5b-aa24-35d86bf0164a', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 2, 22, 'እግዚአብሔር ስለ እርሱ የተናገረው ቃል ይህ ነው፦ ድንግሊቱ የጽዮን ልጅ ቀላል አድርጋሃለች፤ በንቀትም ሥቃብሃለች፤ የኢየሩሳሌም ልጅ ራስዋን ነቅንቃብሃለች።'),
  ('0e5d2656-400a-538d-a96d-5e53f2250bc2', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 3, 23, 'የተገዳደርኸው፥ የሰደብኸውስ ማንን ነው? ቃልህንስ ከፍ ከፍ ያደረግህበት፥ ዐይንህንስ ወደ ላይ ያነሣህበት ማን ነው? በእስራኤል ቅዱስ ላይ አይደለምን?'),
  ('11697422-2b3b-5c55-a5d6-554ee0b52ad6', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 4, 24, 'አንተም በመልእክተኞችህ በኩል እንዲህ ብለህ እግዚአብሔርን ተገዳደርኸው፦ በሰረገላዬ ብዛት ወደ ተራሮች ከፍታ፥ ወደ ሊባኖስ ራስ ወጥቻለሁ፤ ረዣዥሞቹንም ዝግባዎች፥ የተመረጡትንም ጥዶች እቈርጣለሁ፤ ወደ ከፍታውም ዳርቻ ወደ ዱሩ እገባለሁ፤'),
  ('b47f61c4-7bf7-5310-a48e-795eb1c38eac', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 5, 25, 'ገድቤም ውኃውንና የውኃውን ኩሬ አደርቃለሁ።'),
  ('1df601e3-9c41-52fa-a71e-e8bb4d69b3af', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 6, 26, '“እኔ ጥንት የሠራሁትን አልሰማህምን? እኔ በቀድሞ ዘመን እንዳደረግሁት፥ አሁንም አሕዛብን በምሽጎቻቸው፥ በጽኑ ከተሞቻቸው የሚኖሩትንም ያጠፉ ዘንድ አዘዝሁ።'),
  ('e3036719-cd80-58c0-a63d-f3566da7bb4f', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 7, 27, 'እጃቸውንም አዝላለሁ፤ ይደርቃሉም፤ በሰገነት ላይ እንዳለ ደረቅ ሣርም ሳያሸት ዋግ እንደ መታው እህልም ይሆናሉ።'),
  ('76b07596-2f96-51c7-ae86-7239ae984140', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 8, 28, 'አሁን ግን እኔ መቀመጫህንና መውጫህን፥ መግቢያህንም ዐውቄአለሁ።'),
  ('3bd02e68-8779-5c70-a208-f35c0e360e7b', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 9, 29, 'የተቈጣኸው ቍጣና ትዕቢትህ ወደ ጆሮዬ ደርሶአልና ሰለዚህ ስናጋዬን በአፍንጫህ፥ ልጓሜንም በከንፈርህ አደርጋለሁ፤ በመጣህበትም መንገድ እመልስሃለሁ።'),
  ('92e2f12c-ed4b-5b4d-a967-0a1b69ff42b1', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 10, 30, '“ይህም ምልክት ይሆንሃል፤ በዚህ ዓመት የዘራኸውን፥ በሁለተኛውም ዓመት ከገቦው የበቀለውን ትበላላችሁ፤ በሦስተኛውም ዓመት ትዘራላቸሁ፤ ታጭዱማላችሁ፤ ወይንንም ትተክላላችሁ፤ ፍሬውንም ትበላላችሁ።'),
  ('d59a5876-2818-5437-a7a7-134078669062', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 11, 31, 'ያመለጠው የይሁዳ ቤት ቅሬታ ሥሩን ወደ ታች ይሰድዳል፤ ወደ ላይም ያፈራል።'),
  ('298dbd70-60db-5230-a72f-56c273ab4414', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 12, 32, 'ከኢየሩሳሌም ቅሬታ ከጽዮንም ተራራ ያመለጡት ይድናሉና፤ የሠራዊት ጌታ የእግዚአብሔር ቅንአት ይህን ያደርጋል።'),
  ('eb625c59-5e52-5aa2-a339-013dc2249b8c', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 13, 33, 'ስለዚህም እግዚአብሔር ስለ አሦር ንጉሥ እንዲህ ይላል፦ ወደዚች ከተማ አይመጣም፤ ፍላጻንም አይወረውርባትም፤ በጋሻም አይመጣባትም፥ አያጥራትምም።'),
  ('09e6c391-bafb-5f7d-a988-950c2254871f', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 14, 34, 'በመጣበትም መንገድ በዚያ ይመለሳል፤ ወደዚህም ከተማ አይመጣም ይላል እግዚአብሔር፤'),
  ('ded69d62-9020-58db-a76d-f188d5eec593', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 15, 35, 'ስለ እኔም፥ ስለ ባሪያዬም ስለ ዳዊት ይህችን ከተማ እረዳታለሁ አድናታለሁም።”'),
  ('91a0564c-cdd5-5722-a0b5-5cc1dad7c6e3', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 16, 36, 'የእግዚአብሔርም መልአክ ወጣ፤ ከአሦራውያንም ሰፈር መቶ ሰማንያ አምስት ሺህ ሰዎችን ገደለ፤ ማለዳም በተነሡ ጊዜ፥ እነሆ፥ ሁሉም በድኖች ሆነው አገኙአቸው።'),
  ('5ee8235e-ad57-5602-a406-7e9b228dc9f5', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 17, 37, 'የአሦርም ንጉሥ ሰናክሬም ተነሥቶ ሄደ፤ ተመልሶም በነነዌ ተቀመጠ።'),
  ('0a5c6ecd-3483-5b48-a412-e14cf86388b0', '4ba37fe0-30f2-5ef7-a2f6-d6e328fe5c3d', '6091d794-1c83-5ada-aaae-9531a192f80b', 18, 38, 'በአምላኩም በናሳራክ ቤት ሲሰግድ ልጆቹ አድራሜሌክና ሳራሳር በሰይፍ ገደሉት፤ ወደ አራራትም ሀገር ኰበለሉ። ልጁም አስራዶን በእርሱ ፋንታ ነገሠ።'),
  ('77807d1e-148c-5097-a6c6-dcfdfca00569', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 1, 1, 'በዚያም ወራት ሕዝቅያስ ለሞት እስኪደርስ ታመመ። ነቢዩም የአሞጽ ልጅ ኢሳይያስ ወደ እርሱ መጥቶ፥ “እግዚአብሔር እንዲህ ይላል፦ ትሞታለህ እንጂ በሕይወት አትኖርምና ቤትህን አስተካክል” አለው።'),
  ('ae9fa3d7-edf7-55d6-ae50-a814a59871c7', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 2, 2, 'ሕዝቅያስም ፊቱን ወደ ግድግዳው መልሶ እንዲህ ሲል ወደ እግዚአብሔር ጸለየ፦'),
  ('efdba786-cec4-5e9e-a3fe-0f66fc4c95b1', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 3, 3, '“አቤቱ፥ በፊትህ በእውነትና በቅን ልብ እንደ ሄድሁ፥ በፊትህም ደስ የሚያሰኝህን እንዳደረግሁ አስብ።” ሕዝቅያስም እጅግ ታላቅ ልቅሶን አለቀሰ።'),
  ('5b4ca631-dfc3-5d92-acb0-e2fde87d0a28', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 4, 4, 'የእግዚአብሔርም ቃል ወደ ኢሳይያስ እንዲህ ሲል መጣ፤'),
  ('5b4ca417-f13a-582e-a883-f9cb79b8216a', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 5, 5, '“ሂድ፤ ሕዝቅያስን እንዲህ በለው፦ የአባትህ የዳዊት አምላክ እግዚአብሔር እንዲህ ይላል፦ ጸሎትህን ሰምቻለሁ፤ እንባህንም አይቻለሁ፤ እነሆ፥ በዕድሜህ ላይ ዐሥራ አምስት ዓመት እጨምራለሁ፤'),
  ('d352f5cc-f1f6-5c99-a209-574066f266cb', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 6, 6, 'አንተንና ይህችንም ከተማ ከአሦር ንጉሥ እጅ አድናለሁ፤ ለዚችም ከተማ እቆምላታለሁ።'),
  ('7a51d895-36a7-5bb9-a01f-f65d9df8f38e', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 7, 7, 'እግዚአብሔርም የተናገረውን ነገር እንዲፈጽመው ከእግዚአብሔር ዘንድ ምልክቱ ይህ ይሆንልሃል።'),
  ('4293d171-c1da-5133-a8aa-b71fa2eb0630', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', 'e3f1b522-0c23-54e9-a18d-75b1daae0aa7', 8, 8, 'እነሆ፥ በአባትህ የጥላ ስፍረ ሰዓት ላይ ከፀሐይ ጋራ የወረደውን በደረጃዎች ያለውን ጥላ ዐሥር ደረጃ ወደ ኋላ እንዲመለስ አደርጋለሁ።” ፀሐይም በጥላ ስፍረ ሰዓት ላይ የወረደበት ዐሥር ደረጃ ወደ ኋላ ተመለሰ።'),
  ('3fae8a27-42f0-5b84-acbe-9da9b95b8913', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 1, 9, 'የይሁዳ ንጉሥ ሕዝቅያስ ታምሞ ከደዌው በተፈወሰ ጊዜ የጸለየው ጸሎት ይህ ነው፦'),
  ('4c016a80-3dfe-59c1-a4ff-747a3c77cfd9', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 2, 10, 'እኔ እንዲህ አልሁ፥ “በሕይወት ዘመኔ መካከል ወደ ሲኦል በሮች እገባለሁ፤'),
  ('6114a2ca-5419-5fbf-a7e4-3ccbbda311d0', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 3, 11, 'ደግሞም፦ በሕያዋን ምድር የእግዚአብሔርን ማዳን፤'),
  ('819a7eac-e0d9-534c-ab93-938af4770985', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 4, 12, 'የቀረውንም ኑሬዬን አጣሁ።'),
  ('b0a15214-af3c-5798-a8d3-4d122555a02b', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 5, 13, 'በዚያ ወራት እስኪነጋ ድረስ እንደ አንበሳ ታወክሁ፤'),
  ('11356b6b-a605-5f22-aa27-2ea43cadc31e', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 6, 14, 'እንደ ሸመላ እንዲሁ ጮህሁ፤'),
  ('f4e612fe-88e0-53ca-a5bc-b3e730027ce6', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 7, 15, 'ዐይኖች ደከሙ፤ ወደ ሰማይም ወደ እግዚአብሔር ማየት አልቻልሁም።'),
  ('20e16ef1-923a-500c-ab21-09e1b8808f41', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 8, 16, 'ጌታ ሆይ፥ ስለ እርስዋ እንዲህ አልሁህ፤ ነፍሴን አዳንሃት፤'),
  ('93d5a303-6c8e-5df0-ac8d-ebfbb4c0f740', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 9, 17, 'ሰውነቴንም እንዳትጠፋ ይቅር አልሃት፤'),
  ('6f1c2dec-edb9-5aaf-accf-a7bb32b0d745', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 10, 18, 'በመቃብር የሚኖሩ አያመሰግኑህምና፤'),
  ('4b27db39-68f4-5346-a7a3-ea73be0948c7', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 11, 19, 'እኔ ዛሬ እንደማደርግ ሕያዋን ብቻ ያመሰግኑሃል፤'),
  ('9195b86c-53fe-53a8-a284-755acd7cbc37', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 12, 20, 'ጌታዬ ሆይ አንተ መድኀኒቴ ነህ፤'),
  ('faf14aaf-0ec5-57e0-a330-470f5a8cfc5c', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 13, 21, 'ኢሳይያስም ሕዝቅያስን እንዲህ አለው፥ “የበለስ ጥፍጥፍ አምጥተህ በእባጩ ላይ ለብጠው፤ አንተም ትፈወሳለህ።”'),
  ('23d22e95-bd50-5c0e-a8b1-848ec4cd352e', 'b70196b0-69a1-5011-acd6-4f785ee1ec4f', '07ae12e3-4832-59cd-a35b-8cd3db9d0219', 14, 22, 'ሕዝቅያስም፥ “ወደ እግዚአብሔር ቤት እወጣ ዘንድ ምልክቱ ምንድን ነው?” ብሎ ነበር።'),
  ('0c9f64c5-95b9-56b6-a785-1c0b91b2e293', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 1, 1, 'በዚያም ወራት የባቢሎን ንጉሥ የባልዳን ልጅ መሮዳክ ባልዳን ሕዝቅያስ ታምሞ እንደ ተፈወሰ ሰምቶ ነበርና ደብዳቤና እጅ መንሻን፥ መልእክተኞችንም ላከለት።'),
  ('914ee97c-3b36-5d09-a80f-a93d7b1232d6', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 2, 2, 'ሕዝቅያስም ስለ እነርሱ እጅግ ደስ አለው፤ ግምጃ ቤቱንም፥ ወርቁንና ብሩን፥ ከርቤውንና ዕጣኑን፥ ዘይቱንም፥ መሣሪያም ያለበትን ቤት ሁሉ፥ ልብሱንና ዕንቍውን ሁሉ፥ በቤተ መዛግብቱም የተገኘውን ሁሉ አሳያቸው፤ በቤቱና በግዛቱ ሁሉ ካለው ሕዝቅያስ ያላሳያቸው የለም።'),
  ('61e729db-6839-5300-ad31-02436482b8ab', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 3, 3, 'ነቢዩም ኢሳይያስ ወደ ንጉሡ ወደ ሕዝቅያስ መጥቶ፥ “እነዚህ ሰዎች ምን አሉ? ከወዴትስ መጡ?” አለው። ሕዝቅያስም፥ “ከሩቅ ሀገር ከባቢሎን መጡ” አለው።'),
  ('ba5569af-9f1d-53d6-a882-268f9932b5b5', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 4, 4, 'ኢሳይያስም፥ “በቤትህ ያዩት ምንድን ነው?” አለው፤ ሕዝቅያስም፥ “በቤቴ ያለውን ሁሉ አይተዋል፤ በቤቴ፥ እንዲሁም በቤተ መዛግብቴ ካለው ያላሳየኋቸው የለም” አለው።'),
  ('d0528ad1-de25-5ab0-a533-2c046226e4be', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 5, 5, 'ኢሳይያስም ሕዝቅያስን፥ “የሠራዊት ጌታ የእግዚአብሔርን ቃል ስማ።'),
  ('d3506e8a-1fbb-56de-a764-b1bd844022ac', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 6, 6, 'እነሆ፥ በቤትህ ያለው ሁሉ፥ አባቶችህም እስከ ዛሬ ድረስ ያከማቹት ሁሉ ወደ ባቢሎን የሚፈልስበት ወራት ይመጣል፤ ምንም አያስቀሩልህም፤ ይላል እግዚአብሔር።'),
  ('84eb2bcf-fdac-55e5-aa0c-02f495c0f4fa', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 7, 7, 'ከአንተ ከሚወጡት ከምትወልዳቸው ልጆችህ ማርከው ይወስዳሉ፤ በባቢሎንም ንጉሥ ቤት ውስጥ ጃንደረቦችና የቤት አሽከሮች ይሆናሉ” አለው።'),
  ('94926ce9-37f7-5338-a503-697ac1d30090', '7ac1c6a8-5734-5092-aa78-ce3dfd131417', '848c514f-73c3-575f-ad77-4926a2080c38', 8, 8, 'ሕዝቅያስም ኢሳይያስን፥ “እርሱ የተናገረው የእግዚአብሔር ቃል መልካም ነው፤ ነገር ግን፦ በዘመኔ ሰላምና ጽድቅ ይሁን” አለው።'),
  ('8f3e404c-233b-5285-ac6f-91e1d249598e', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 1, 1, 'አጽናኑ፤ ሕዝቤን አጽናኑ፤ ይላል እግዚአብሔር፤'),
  ('b9ff5bf2-e8b3-5242-aa86-7f61f82a96a9', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 2, 2, 'ካህናት ሆይ፥ ለኢየሩሳሌም ወደ ልቧ የሚገባ ነገርን ተናገሩ፤ ውርደቷ እንደ ተፈጸመ፥ ኀጢአቷም እንደ ተሰረየ፥ ከእግዚአብሔርም እጅ ስለ ኀጢአቷ ሁሉ ሁለት እጥፍ እንደ ተቀበለች አጽናኑአት።'),
  ('3a2fac70-4b84-57c4-a72e-b69fb430b60f', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 3, 3, 'የዐዋጅ ነጋሪ ቃል በምድረ በዳ፥ “የእግዚአብሔርን መንገድ ጥረጉ፤ ለአምላካችንም ጎዳና በበረሃ አስተካክሉ።'),
  ('df5f05a6-16d9-5daf-ad11-67415d5968df', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 4, 4, 'ሸለቆው ሁሉ ይሙላ፤ ተራራውና ኮረብታውም ሁሉ ዝቅ ይበል፤ ጠማማውም ይቅና፤ ሰርጓጕጡም ሜዳ ይሁን፤'),
  ('6f17ab86-76c7-50cb-a2ec-90ac7df90570', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 5, 5, 'የእግዚአብሔርም ክብር ይገለጥ፤ ሥጋ ለባሹም ሁሉ የእግዚአብሔርን ትድግና ይይ፤ እግዚአብሔር ይህን ተናግሮአልና።”'),
  ('a08d16d3-4ec8-52db-aeea-a09173a9cd4a', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 6, 6, '“ጩኽ” የሚል ሰው ቃል፤ “ምን ብዬ ልጩኽ?” አልሁ። “ሥጋ ለባሽ ሁሉ ሣር ነው፤ የሰውም ክብሩ ሁሉ እንደ ሣር አበባ ነው።'),
  ('f0ebfbc4-443f-54fb-a2ba-41a568d99b92', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 7, 7, 'የእግዚአብሔር እስትንፋስ ይነፍስበታልና ሣሩ ይደርቃል፤ አበባውም ይረግፋል፤ በእውነት ሕዝቡ ሣር ነው።'),
  ('b284b080-4925-5c86-a618-c1eceeb5d57d', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 8, 8, 'ሣሩ ይደርቃል፤ አበባውም ይረግፋል፤ የአምላካችን ቃል ግን ለዘለዓለም ጸንቶ ይኖራል።”'),
  ('a375f0b3-aa87-5a09-aab5-e743a04033ca', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 9, 9, 'ለጽዮን የምሥራችን የምትነግር ሆይ፥ ከፍ ወዳለው ተራራ ውጣ፤ ለኢየሩሳሌም የምሥራችን የምትነግር ሆይ፥ ድምፅህን በኀይል አንሣ፤ አትፍራ፤ ለይሁዳም ከተሞች፦ እነሆ፥ አምላካችሁ! ብለህ ንገር።'),
  ('6c1bc0e6-2f38-5a18-a956-789f4eb856c3', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 10, 10, 'እነሆ፥ ጌታ እግዚአብሔር በኀይሉ ይመጣል፤ በክንዱም ይገዛል፤ እነሆ፥ ዋጋው ከእርሱ ጋር ሥራውም በፊቱ ነው።'),
  ('26bba553-c6b6-5aab-a6ed-58ee03d17a6e', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 11, 11, 'መንጋውን እንደ እረኛ ያሰማራል፤ ጠቦቶቹን በክንዱ ሰብስቦ በብብቱ ይሸከማል፤ የሚያጠቡትንም በቀስታ ይመራል።'),
  ('2ccc1eff-ee67-581f-a248-9e8bd4cd9503', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 12, 12, 'ውኆችን በእፍኙ የሰፈረ፥ ሰማይንም በስንዝሩ የለካ፥ ምድርንም ሁሉ ሰብስቦ በእጁ የያዘ፥ ተራሮችን በሚዛን፥ ኮረብቶችንም በሚዛኖች የመዘነ ማን ነው?'),
  ('f77b7cef-991d-5a6f-ad4a-982625b7e336', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 13, 13, 'የእግዚአብሔርን ሕሊና ያወቀ ወይስ አማካሪ ሆኖ ያማከረው ማን ነው?'),
  ('495d084b-9013-57ec-a25d-6fa6ebe3a1f1', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 14, 14, 'ወይስ ከማን ጋር ተመካከረ? ወይስ ማን መከረው? ፍርድንስ ማን አስተማረው? የጥበብንስ መንገድ ማን አሳየው?'),
  ('3703f7d2-fb06-585a-a98b-42d1d78f9f8f', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 15, 15, 'እነሆ፥ አሕዛብ በገንቦ እንዳለች ጠብታ ናቸው፤ እንደ ሚዛንም ውልብልቢት ተቈጥረዋል፤ እንደ ኢምንትም ናቸው።'),
  ('2b7865ce-bea2-5a17-ad91-34f3076ea6fc', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 16, 16, 'ሊባኖስ ለማንደጃ እንስሶችዋም ለሚቃጠል መሥዋዕት አይበቁም።'),
  ('bceb3816-5ad5-5734-a951-43fb2a14e132', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 17, 17, 'አሕዛብ ሁሉ በፊቱ እንዳልነበሩ ናቸው፤ እንደ ከንቱ ነገርም ይመስላሉ።'),
  ('8b145bf6-113f-57e8-afbb-2c82f79cf7d9', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 18, 18, 'እንግዲህ እግዚአብሔርን በማን ትመስሉታላችሁ? ወይስ በምን ምሳሌ ታስተያዩታላችሁ?'),
  ('e051e7e4-f062-5935-a452-c9fcb71f17bc', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 19, 19, 'እንጨት ጠራቢ በሠራው ምስል፥ ወይስ አንጥረኛ መትቶ በሠራው ወርቅ፥ በወርቅም ለብጦ በሠራው ምስል ትመስሉታላችሁን?'),
  ('c2faa5d5-aa19-5c54-a2cb-5b0faa097f98', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 20, 20, 'ጠራቢው የማይነቅዘውን እንጨት ይመርጣል፤ ምስሉም እንዳይናወጥ ያቆመው ዘንድ ብልህ ሠራተኛን ይፈልጋል።'),
  ('79cd4278-ebcf-5846-ad53-0dfb4cde562e', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 21, 21, 'አላወቃችሁምን? ወይስ አልሰማችሁምን? ከጥንትስ አልተወራላችሁምን? ወይስ ምድር ከተመሠረተች ጀምሮ አላስተዋላችሁምን?'),
  ('5666b81b-cd27-59fd-afa9-7e2b9dad6272', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 22, 22, 'እርሱ የምድርን ክበብ ያጸናል፤ በእርስዋም የሚኖሩት እንደ አንበጣ ናቸው፤ ሰማያትን እንደ መጋረጃ የሚዘረጋቸው፥ እንደ ድንኳንም ለመኖሪያ የሚዘረጋቸው፤'),
  ('83485358-f3cb-5d98-aa96-80f3c4e8500e', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 23, 23, 'አለቆችንም የሚገዛላቸው እንዳይኖር የሚያደርግ ምድርንም እንደ ኢምንት የሚያደርጋት እርሱ ነው።'),
  ('67fa0476-142a-545f-a374-9eb5a89cd6a9', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 24, 24, 'በእርሱም ላይ ዛፉንና ሣሩን፥ የማይቈጠር ሌላውንም ብዙ ፍጥረት የፈጠረ እርሱ ነው። ነፋስም በነፈሰባቸው ጊዜ ይደርቃሉ፤ ዐውሎ ነፋስም እንደ ገለባ ይጠርጋቸዋል።'),
  ('2c20b17b-b136-5420-a9bc-9ff0fadd60dd', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 25, 25, 'እንግዲህ እተካከለው ዘንድ በማን መሰላችሁኝ? ይላል ቅዱሱ እግዚአብሔር።'),
  ('0bffe67a-8155-5296-aada-96d456da933e', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 26, 26, 'ዐይናችሁን ወደ ሰማይ አንሥታችሁ ተመልከቱ፤ ይህን ሁሉ የፈጠረ ማን ነው? ከዋክብትንም በሙሉ የሚቈጥራቸው እርሱ ነው፤ በየጊዜያቸው ያመጣቸዋል፤ ሁሉንም በየስማቸው ይጠራቸዋል፤ በክብሩ ብዛትና በችሎቱ ብርታት አንድስ እንኳ አይታጣውም።'),
  ('a9ef4ab8-5fb3-5a47-a1ce-dfcbcd9a6041', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 27, 27, 'ያዕቆብ ሆይ፥ እስራኤልም ሆይ፥ መንገዴ ከእግዚአብሔር ተሰውራለች፤ አምላኬም ከእኔ ርቋል፤ ፍርዴንም ትትዋል፤ ለምን ትላለህ? ለምንስ እንዲህ ትናገራለህ?'),
  ('a98c25a7-2974-5fb0-a483-7e4a58877f59', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 28, 28, 'አሁንም አላወቅህምን? አልሰማህምን? እግዚአብሔር የዘለዓለም አምላክ፥ የምድርንም ዳርቻ የፈጠረ አምላክ ነው፤ አይራብም፤ አይጠማም፤ አይደክምም፤ ማስተዋሉም አይመረመርም።'),
  ('3f329d7a-1679-5348-a6ab-1c13c784593b', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 29, 29, 'ለደካሞች ኀይልን ይሰጣል፤ መከራ የሚቀበሉትንም አያሳዝናቸውም።'),
  ('f296a53f-7690-5812-a8d0-81bcf0fbba5e', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 30, 30, 'ብላቴኖች ይራባሉ፤ ጐልማሶች ይታክታሉ፤ ጐበዛዝቱም ፈጽሞ ይዝላሉ።'),
  ('36202c01-4a8a-5783-ac50-4264d38752ce', '769f4e10-d827-511f-ac29-6c3e6639b057', '0c19bd48-1420-53b6-a47f-3fa2ab2e3665', 31, 31, 'እግዚአብሔርን ተስፋ የሚያደርጉና የሚታገሡ ግን ኀይላቸውን ያድሳሉ፤ እንደ ንስር ክንፍ ያወጣሉ፤ ይሮጣሉ፤ አይታክቱምም፤ ይሄዳሉ፤ አይራቡምም።'),
  ('37e20782-d587-5da7-a95f-deed56768fad', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 1, 1, 'ደሴቶች ሆይ፥ ወደ እኔ ተመለሱ፤ አለቆች ኀይላቸውን ያድሳሉና በአንድነት ቀርበው ፍርድን ይናገሩ።'),
  ('899be959-58c6-5fe6-a2c8-e65191367e32', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 2, 2, 'ከምሥራቅ ጽድቅን ያስነሣ፥ ይከተለውም ዘንድ ወደ እግሩ የጠራው ማን ነው? በአሕዛብና በነገሥታት ፊት ድንጋጤን ያመጣል። ጦሮቻቸውን በምድር ያስጥላቸዋል፤ ቀስቶቻቸውም እንደ ገለባ ይረግፋሉ።'),
  ('b9627659-2d44-51f9-aebd-116b2b594434', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 3, 3, 'ያሳድዳቸዋልም፤ እግሮቹም በሰላም መንገድ ይሄዳሉ።'),
  ('5d8fca7c-216f-5442-af8f-cb0e0bcc696e', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 4, 4, 'ይህን የሠራና ያደረገ፥ ትውልድንም ከጥንት የጠራ ማን ነው? እኔ እግዚአብሔር ፊተኛውና ኋለኛው እኔ ነኝ።'),
  ('5bd7cd4b-d8d9-564d-a7ee-7359f11fe978', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 5, 5, 'አሕዛብ አይተው ፈሩ። የምድርም ዳርቾች ቀረቡ፤ በአንድነትም ቀረቡ፤ መጡም።'),
  ('27b556eb-c1cf-5997-ab42-b3e142da3085', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 6, 6, 'ሁሉም ባልንጀራውን ይከራከራል፤ ሁሉም እያንዳንዱ ወንድሙ ይረዳው ነበር፤ ወንድሙንም፦ አይዞህ ይለው ነበር።'),
  ('bca5ea1d-1cb9-5526-a20e-4cdd4475287d', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 7, 7, 'አናጢውም አንጥረኛውን፥ በመዶሻም የሚያሳሳውን መስፍ መችውን አጽናና፤ ስለ ማጣበቅ ሥራውም፥ “መልካም ነው” አለ፤ እንዳይንቀሳቀስም በችንካር አጋጠመው።'),
  ('5c81ab34-b9e9-5bb7-a4f7-99a180013434', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 8, 8, 'ባሪያዬ እስራኤል፥ የመረጥሁህ ያዕቆብ፥ የወዳጄ የአብርሃም ዘር ሆይ፥'),
  ('fd56bbb4-067c-583e-a52f-9045170dc4fa', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 9, 9, 'አንተ ከምድር ዳርቻ የያዝሁህ፥ ከማዕዘንዋም የጠራሁህ ነህና፦ አንተ ባሪያዬ ነህ፤ መርጬሃለሁ፤ አልጥልህም፤ ያልሁህ ሆይ፥'),
  ('c016143b-c891-595d-a3c8-34e585ae0d94', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 10, 10, 'እኔ ከአንተ ጋር ነኝና አትፍራ፤ እኔ አምላክህ ነኝና አትደንግጥ፤ አበረታሃለሁ፤ እረዳህማለሁ፤ በጽድቄም ቀኝ ደግፌ እይዝሃለሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('266ff183-0fa7-5554-a730-7ebada44f6e0', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 11, 11, 'እነሆ፥ የሚቃወሙህ ሁሉ ያፍራሉ፤ ይዋረዱማል፤ እንዳልነበሩም ይሆናሉ፤ ጠላቶችህም ይጠፋሉ።'),
  ('3ef67e62-c5e7-5ab3-a4a1-58f5e07896da', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 12, 12, 'የሚያሠቃዩህንም ሰዎች ትሻቸዋለህ፤ አታገኛቸውምም፤ እንዳልነበሩ ይሆናሉና፤ የሚዋጋህም የለም።'),
  ('386ab1e7-edd9-50ae-a54a-83bfb4602729', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 13, 13, 'ቀኝ እጅህን የያዝሁህ፥ እንዲህም የምልህ እኔ አምላክህ ነኝና።'),
  ('4d4b675c-e261-5168-ae85-34f28482b97a', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 14, 14, 'ያዕቆብ ሆይ፥ አትፍራ፤ በቍጥር ጥቂት የነበርህ እስራኤል ሆይ፥ እኔ እረዳሃለሁ፥ ይላል እግዚአብሔር፤ የሚቤዥህም የእስራኤል ቅዱስ ነው።'),
  ('df45d685-5378-5335-a4dc-541a828af45b', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 15, 15, 'እነሆ፥ እንደ ተሳለች እንደ አዲስ ባለ ጥርስ ማሄጃ አድርጌሃለሁ፤ ተራሮችንም ታሄዳለህ፤ ኮረብቶችንም ታደቅቃቸዋለህ እንደ ገለባም ታደርጋቸዋለህ።'),
  ('2ab21af4-e6dc-55a4-a0dd-5a907e60643a', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 16, 16, 'ታበጥራቸዋለህ፤ ነፋስም ይጠርጋቸዋል፤ ዐውሎ ነፋስም ይበትናቸዋል፤ አንተም በእስራኤል ቅዱስ ደስ ይልሃል።'),
  ('0ddeee3e-0f7f-5fc4-a126-ce2607c8081f', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 17, 17, 'ድሆችና ምስኪኖች ውኃ ይሻሉ፤ አያገኙምም፤ ምላሳቸውም በጥማት ደርቋል፤ እኔ ጌታ እግዚአብሔር እሰማቸዋለሁ፤ የእስራኤል አምላክ እኔ አልተዋቸውም።'),
  ('f8c3e7a5-19a7-583a-ac9d-b9ccfb3f5279', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 18, 18, 'በተራሮች ላይ ወንዞችን፥ በሸለቆችም መካከል ምንጮችን እከፍታለሁ፤ ምድረ በዳውን ለውኃ መቆሚያ፥ የተጠማችውንም ምድር ለውኃ መፍለቂያ አደርጋለሁ።'),
  ('ff19e848-8c23-5dbb-ac9f-ce34ee0fdc1d', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 19, 19, 'በምድረ በዳ ዝግባውንና ግራሩን፥ ባርሰነቱንና የዘይቱን ዛፍ አበቅላለሁ፤'),
  ('36876725-bfcc-526c-a8a7-7b3580fe71dd', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 20, 20, 'ይኸውም የእግዚአብሔር እጅ ይህን ሁሉ እንደ ሠራ፥ የእስራኤልም ቅዱስ ይህን እንደ አሳየ ያውቁ ዘንድ፥ ያስተውሉም ዘንድ፥ ይረዱም ዘንድ፥ ያምኑም ዘንድ ነው።'),
  ('57d1dc12-380f-5c6e-a8f1-1ccf17142415', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 21, 21, 'ፍርዳችሁ ቀረበች፥ ይላል እግዚአብሔር አምላክ፤ ምክራችሁም ቀረበ፥ ይላል የያዕቆብ ንጉሥ።'),
  ('fdec1050-68a8-5cb0-a543-eb6f28f0edbf', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 22, 22, 'ይምጡ፤ የሚደርስባችሁንም ይንገሩን፤ ልብም እናደርግ ዘንድ፤ ፍጻሜአቸውንም እናውቅ ዘንድ፥ የቀደሙት ነገሮች ምን እንደ ሆኑ ንገሩን፤ የሚመጡትንም አሳዩን።'),
  ('188a53a0-10a1-5dad-add8-7e076c583552', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 23, 23, 'አማልክትም መሆናችሁን እናውቅ ዘንድ በኋላ የሚመጡትን ተናገሩ፤ እናደንቃችሁም ዘንድ፥ በአንድነትም እናይ ዘንድ መልካሙን ወይም ክፉውን አድርጉ።'),
  ('0a56d408-e8b6-5e94-a927-8d7caee78fdd', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 24, 24, 'እናንተ ከየት ናችሁ? ከየትስ ሠሯችሁ? ከምድር የሚመርጧችሁም የረከሱ አይደሉምን?'),
  ('7c780049-e464-5527-a02d-e3161a9f5bff', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 25, 25, 'ከሰሜንና ከፀሐይ መውጫ የሚመጡትን አስነሣሁ፤ በስሜም ይጠራሉ፤ አለቆች ይምጡ፤ እንደ ሸክላ ሠሪ ጭቃና ጭቃን እንደሚረግጥ ሸክላ ሠሪ እንዲሁ ይረግጡአቸዋል።'),
  ('b63b7378-0275-597f-a128-8a21855fb7ec', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 26, 26, 'እናውቅ ዘንድ፥ ከጥንት የተነገረው፦ እውነት ነው እንልም ዘንድ ቀድሞ የተናገረው ማን ነው? ከመሆኑ በፊት የሚናገር የለም፤ የሚገልጥም የለም፤ ቃላችሁን የሚሰማ የለም።'),
  ('6699da2a-f3ef-5134-a73a-b294d1fee900', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 27, 27, 'በመጀመሪያ ለጽዮን፦ ግዛትን እሰጣታለሁ፤ ኢየሩሳሌምንም ወደ መንገድዋ እመልሳታለሁ።'),
  ('442e0576-4fa6-53d9-ac70-9e8c98ad602c', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 28, 28, 'ከአሕዛብና ከአማልክቶቻቸው የሚናገር የለምና፥ ከየትም እንደ ሆኑ ብጠይቃቸው አይመልሱልኝም።'),
  ('5557ab9d-03d3-59a9-ab62-5d8476480bcd', 'e697c970-862e-5da8-ac15-0faa1789aaf2', 'c4459ed1-7127-5041-a67a-574106807099', 29, 29, 'የሚሠሩአቸውም በከንቱ ይሠሩአቸዋል።'),
  ('14903ef9-8af5-57cb-afca-490043088a28', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 1, 1, 'እነሆ፥ ደግፌ የያዝሁት ባሪያዬ ያዕቆብ፤ ነፍሴ የተቀበለችው ምርጤ እስራኤልም፤ በእርሱ ላይ መንፈሴን አድርጌአለሁ፤ እርሱም ለአሕዛብ ፍርድን ያመጣል።'),
  ('d1b0486b-d3f4-5278-add9-1458d4782479', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 2, 2, 'አይጮኽም፤ ቃሉንም አያነሣም፤ ድምፁንም በሜዳ አያሰማም።'),
  ('f4072167-160f-5715-ab32-a5efac9eb30b', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 3, 3, 'የተቀጠቀጠ ሸንበቆን አይሰብርም፤ የሚጤስንም ክር አያጠፋም፤ ነገር ግን በእውነት ፍርድን ያመጣል።'),
  ('c4526584-d562-5638-ad1e-b7f41e301793', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 4, 4, 'በምድርም ፍርድን እስኪያደርግ ድረስ ያበራል እንጂ አይጠፋም፤ አሕዛብም በስሙ ይታመናሉ።'),
  ('95c8f562-6fc6-5d66-a5cd-caa7fbc847c1', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 5, 5, 'ሰማይን የፈጠረ፥ የዘረጋውም፥ ምድርንና በውስጥዋ ያለውን ሁሉ ያጸና፥ በእርስዋ ላይ ለሚኖሩ ሕዝብ እስትንፋስን፥ ለሚሄዱባትም መንፈስን የሚሰጥ አምላክ እግዚአብሔር እንዲህ ይላል፦'),
  ('88e6acbb-63e0-5e67-aed0-65ae41da0d55', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 6, 6, '“እኔ እግዚአብሔር አምላክ በጽድቅ ጠርቼሃለሁ፤ በእጄም እይዝሃለሁ፤ አበረታሃለሁም፤ ለልጅ ልጅ ቃል ኪዳን፥ ለአሕዛብም ብርሃን አድርጌ እሰጥሃለሁ።'),
  ('37808f0b-2b2b-5eda-a359-0997d790b435', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 7, 7, 'የዕውራንንም ዐይን ትከፍት ዘንድ፥ የተጋዙትንም ከግዞት ቤት፥ በጨለማም የተቀመጡትን ከወህኒ ቤት ታወጣ ዘንድ።'),
  ('f3f97748-de4a-5134-a2af-73a061f057cd', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 8, 8, 'እኔ እግዚአብሔር አምላክህ ነኝ፤ ስሜ ይህ ነው፤ ክብሬን ለሌላ፥ ምስጋናዬንም ለተቀረጹ ምስሎች አልሰጥም።'),
  ('882bf2f8-fb6d-53c8-a465-a60ca403c658', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 9, 9, 'እነሆ የቀድሞው ነገር ተፈጸመ፤ አዲስ ነገርንም እናገራለሁ፤ አስቀድሞም ሳይነገር እርሱን አስታውቃችኋለሁ።”'),
  ('c500e7bf-1655-537f-a7a6-afe6ab4768ec', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 10, 10, 'ወደ ባሕር የምትወርዱ፥ በእርስዋም ውስጥ የምትጓዙ ሁሉ፥ ደሴቶችና በእነርሱም ላይ የምትኖሩ ሆይ፥ ለእግዚአብሔር አዲስ መዝሙር ዘምሩ፤ ከምድርም ዳርቻ ስሙን አክብሩ።'),
  ('ff5ca044-f685-5c82-aef3-603a567d0585', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 11, 11, 'ምድረ በዳውና ከተሞችዋ፥ የቄዳርም ነዋሪዎችና መንደሮች ድምፃቸውን ያንሡ፤ በዋሻም የሚኖሩ እልል ይበሉ፤ በተራሮችም ራስ ላይ ሆነው ይጩኹ።'),
  ('17167873-4c3d-5c1c-ac3c-2f54c6542aca', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 12, 12, 'ለእግዚአብሔር ክብርን ይስጡ፤ ምስጋናውንም በደሴቶች ይናገሩ።'),
  ('bcc5025b-a1b4-50e1-aea9-1cdeb9a39bdd', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 13, 13, 'የሠራዊት ጌታ እግዚአብሔር ይወጣል፤ ኀይለኛውንም ያጠፋል፤ ቅንአትንም ያስነሣል፤ በጠላቶቹም ላይ በኀይል ይጮኻል።'),
  ('adf37652-1b04-5df1-a74d-c32ffab59295', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 14, 14, 'ከድሮ ዘመን ጀምሮ ዝም ብያለሁ፤ እንግዲህ ለዘለዓለም ዝም እላለሁን? አሁን ምጥ እንደ ያዛት ሴት እታገሣለሁ፤ አጠፋለሁ፤ በአንድነትም እጨርሳለሁ።'),
  ('3f0bcaaf-a512-530e-a287-19db7d83faf2', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 15, 15, 'ተራሮችንና ኮረብቶችን አፈርሳለሁ፤ ቡቃያዎቻቸውንም ሁሉ አደርቃለሁ፤ ወንዞችንም ደሴቶች አደርጋለሁ፤ ኩሬዎችንም አደርቃለሁ።'),
  ('fc84e39b-4d93-5108-a69d-40553629d3f3', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 16, 16, 'ዕውሮችንም በማያውቋት መንገድ አመጣቸዋለሁ፤ የማያውቋትንም ጎዳና እንዲረግጡ አደርጋቸዋለሁ፤ በፊታቸውም ጨለማውን ብርሃን አደርጋለሁ፤ ጠማማውንም አቀናለሁ። ይህንም አደርግላቸዋለሁ፤ አልተዋቸውምም።'),
  ('1164fcd5-4eed-5e33-a1fa-fdbc43dcecd7', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 17, 17, 'በተቀረጹትም ምስሎች የሚታመኑ፥ ቀልጠው የተሠሩትንም ምስሎች፥ “አምላኮቻችን ናችሁ” የሚሉ ወደ ኋላቸው ይመለሳሉ፤ ፈጽመውም ያፍራሉ።'),
  ('85b25f41-cfb0-5900-aabd-f1e2b2c5e81f', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 18, 18, 'እናንተ ደንቆሮች፥ ስሙ፤ እናንተም ዕውሮች እዩ፤ ተመልከቱም።'),
  ('6980f322-7485-5a63-a423-525f53d6933c', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 19, 19, 'ከባሪያዎች በቀር ዕውር ማን ነው? ከአለቆቻቸውስ በቀር ደንቆሮ የሆነ ማን ነው? የእግዚአብሔር ባሪያዎች ታወሩ።'),
  ('f56ec597-8014-585f-a8e5-400b146eb878', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 20, 20, 'ብዙ ነገርን ታያላችሁ፤ ነገር ግን አትጠባበቁትም፤ ጆሮዎቻችሁም ተከፍተዋል፤ ነገር ግን አትሰሙም።'),
  ('01c79348-4241-525d-a720-7616eac4d477', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 21, 21, 'እግዚአብሔር አምላክ ምስጋናውን ያጸድቅና ከፍ ያደርግ ዘንድ መከረ።'),
  ('d14a3476-6853-537c-ade0-292e9213015e', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 22, 22, 'እነሆ፥ ተመለከትሁ፤ ሕዝቡ የተበዘበዘና የተዘረፈ ነው፤ ወጥመድ በሁሉም ቦታ በዋሻዎችና እነርሱን በሸሸጉባቸው ቤቶች ተጠምዶአል፤ ብዝበዛ ሆነዋል፤ የሚያድንም የለም፤ ምርኮም ሆነዋል፤ የሚያስጥላቸውም የለም።'),
  ('7efe1eaf-e466-5528-ae8e-f131b6de701e', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 23, 23, 'ከመካከላችሁ ይህን የሚያደምጥ፥ ለሚመጣውም ጊዜ የሚሰማ ማን ነው?'),
  ('47e20ccc-c18a-5a10-a516-27b331a9e003', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 24, 24, 'ያዕቆብን እንዲማርኩት፥ እስራኤልንም እንዲበዘብዙት ያደረገ ማን ነው? እነርሱም የበደሉት፥ በመንገዱም ይሄዱ ዘንድ ያልወደዱት፥ ሕጉንም ያልሰሙት እግዚአብሔር እርሱ አይደለምን?'),
  ('02802e80-47ed-53b0-ab13-cb9a1a313e75', '3d103f05-799b-5466-a406-c9fabcde8285', 'bb73b8b2-4e4f-5c58-a1c5-d6af2085a953', 25, 25, 'ስለዚህ የቍጣውን መዓትና የሰልፉን ጽናት አመጣባቸው፤ በዙሪያቸው አቃጠላቸው፤ እነርሱ ግን አላወቁም፤ በልባቸውም አላስተዋሉም።'),
  ('196e170e-2ef5-519c-a580-9c8ee0b863d1', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 1, 1, 'አሁንም ያዕቆብ ሆይ፥ የፈጠረህ፥ እስራኤልም ሆይ፥ የሠራህ እግዝአብሔር እንዲህ ይላል፥ “ተቤዥችሃለሁና አትፍራ፤ በስምህም ጠርቼሃለሁ፤ አንተ የእኔ ነህ።'),
  ('f85e45aa-e8a8-5e9e-aa39-034241d77c5b', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 2, 2, 'በውኃ ውስጥ ባለፍህ ጊዜ ከአንተ ጋር እሆናለሁ፤ ወንዞችም አያሰጥሙህም፤ በእሳትም ውስጥ በሄድህ ጊዜ አትቃጠልም፤ ነበልባሉም አይፈጅህም።'),
  ('7daf31e1-0e0e-5e27-a6ea-ee19c3bca3ec', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 3, 3, 'እኔ የእስራኤል ቅዱስ አምላክህ እግዚአብሔር መድኀኒትህ ነኝ፤ ግብፅንና ኢትዮጵያን ለአንተ ቤዛ አድርጌ፥ ሴዎንንም ለአንተ ፋንታ ሰጥቻለሁ።'),
  ('862de65c-d6dc-59bb-aaff-ebdffde57ab8', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 4, 4, 'በፊቴ የከበርህና የተመሰገንህ ነህና፥ እኔም ወድጄሃለሁና ስለዚህ ብዙ ሰዎችን ለአንተ ቤዛ፥ አለቆችንም ለራስህ እሰጣለሁ።'),
  ('ab4669f0-6bf0-5860-acc6-acfd3181443b', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 5, 5, 'እኔ ከአንተ ጋር ነኝና አትፍራ፤ ዘርህንም ከምሥራቅ አመጣዋለሁ፤ ከምዕራብም እሰበስብሃለሁ።'),
  ('0a6393c7-f226-5508-a7c7-11fac6c9037b', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 6, 6, 'ሰሜንን፦ መልሰህ አምጣ፤ ደቡብምን፦ አትከልክል፤ ወንዶች ልጆችን ከሩቅ፥ ሴቶች ልጆችንም ከምድር ዳርቻ፥'),
  ('d0ea03e1-af17-5b01-ab75-00dbbcc4637c', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 7, 7, 'በስሜ የተጠራውን ለክብሬም የፈጠርሁትን፥ የሠራሁትንና ያደረግሁትን ሁሉ አምጣ” እለዋለሁ።'),
  ('ad801090-8132-5bb5-a24c-cf74f6d631e8', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 8, 8, 'ዐይኖች እያሉአቸው የማያዩ ዕውሮችን ሕዝብ፥ ጆሮችም እያሉአቸው የማይሰሙ ደንቆሮዎችን አወጣሁ።'),
  ('1b0a5a42-2f25-5b62-a879-9acfe6d2a4a7', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 9, 9, 'አሕዛብ ሁሉ በአንድነት ተሰበሰቡ፤ አለቆችም ተከማቹ፤ ይህን ማን ይናገራል? የቀድሞውንስ ማን ይነግራችኋል? ይጸድቁ ዘንድ ምስክሮቻቸውን ያምጡ፤ ሰምተውም፦ እውነትን ይናገሩ።'),
  ('e441cde9-5510-5edd-a79f-bbba17231a57', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 10, 10, 'ታውቁና ታምኑብኝ ዘንድ እኔም እንደ ሆንሁ ታስተውሉ ዘንድ፥ እናንተ፥ የመረጥሁትም ባሪያዬ ምስክሮች ሁኑ፤ እኔም ምስክር እሆናችኋለሁ ይላል እግዚአብሔር አምላክ፤ ከእኔ በፊት አምላክ አልነበረም፤ ከእኔም በኋላ አይኖርም።'),
  ('ace40b1b-4292-5047-ae74-a40a7a03b9c6', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 11, 11, 'እኔ፥ እግዚአብሔር ነኝ፤ ከእኔ ሌላ የሚያድን አምላክ የለም።'),
  ('d5d7f7ca-6fea-581f-afaf-916c2d4e6a5f', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 12, 12, 'ተናግሬአለሁ፤ አድኜማለሁ፤ መክሬማለሁ፤ በእናንተም ዘንድ ባዕድ አምልኮ አልነበረም፤ ስለዚህ እኔ እግዚአብሔር አምላክ እንደ ሆንሁ እናንተ ራሳችሁ ምስክሮች ናችሁ፤'),
  ('9ece2658-0743-564e-abe7-c46f6cbc66ad', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 13, 13, 'ከጥንት ጀምሮ እኔ እግዚአብሔር ነኝ፤ ከእጄም የሚያመልጥ የለም፤ እሠራለሁ፤ ወደ ኋላስ የሚመልስ ማን ነው?'),
  ('50de2777-a08c-535b-a279-203caa9287e6', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 14, 14, 'የእስራኤል ቅዱስ፥ የሚቤዣችሁ፥ እግዚአብሔር እንዲህ ይላል፥ “ስለ እናንተ ወደ ባቢሎን ሰድጃለሁ፤ ስደተኞችን አስነሣለሁ፤ ከለዳውያንም በመርከብ ውስጥ ይታሰራሉ።'),
  ('f039d1e0-745c-533c-a85d-4710e3888fe2', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 15, 15, 'ቅዱሳችሁ፥ የእስራኤል ፈጣሪ፥ ንጉሣችሁ፥ እግዚአብሔር አምላክ እኔ ነኝ።”'),
  ('1405d042-f167-50dd-ade3-3118569dbd95', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 16, 16, 'በባሕር ውስጥ መንገድን በኀይለኛም ውኃ ውስጥ መተላለፊያን ያደረገ እግዚአብሔር አምላክ እንዲህ ይላል፦'),
  ('0cbe0c6c-6ab8-58d2-aa92-0b24e1c3e20d', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 17, 17, 'እግዚአብሔር ሰረገላውንና ፈረሱን ሠራዊቱንና አርበኛውን ያወጣል፤ እነርሱ ግን በአንድነት ተኝተዋል፤ አይነሡም፤ ቀርተዋል፤ እንደ ጥዋፍ ኩስታሪም ጠፍተዋል፤'),
  ('e7951618-3fdb-55b8-ab91-d2ece3775d94', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 18, 18, 'የፊተኛውን ነገር አታስታውሱ፤ የጥንቱንም ነገር አታስቡ።'),
  ('56efd9e2-011d-5890-aa55-573b1802f27c', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 19, 19, 'እነሆ፥ አዲስ ነገርን አደርጋለሁ፤ እርሱም አሁን ይበቅላል፤ እናንተም አታውቁትም፤ በምድረ በዳም መንገድን፥ በበረሃም ወንዞችን አደርጋለሁ።'),
  ('982d1383-4bd6-5e66-a819-f30895650169', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 20, 20, 'የምድረ በዳ አራዊት፥ ቀበሮችና ሰጎኖች፥ ያከብሩኛል። የመረጥሁትን ሕዝቤን አጠጣ ዘንድ በምድረ በዳ ውኃን፥ በበረሃም ወንዞችን ሰጥቻለሁና፤'),
  ('656098d5-eff1-51d2-a377-93011c61af6d', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 21, 21, 'እነርሱም ምስጋናዬን እንዲናገሩ ለእኔ የፈጠርኋቸው ሕዝብ ናቸው፤'),
  ('d24f4ff9-cd87-55fc-a937-f937aa0eed94', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 22, 22, 'ያዕቆብ ሆይ፥ እነሆ፥ አልጠራሁህም፤ አንተም እስራኤል ሆይ፥ አልዘበዘብሁህም፤'),
  ('a351047f-effa-5609-a89a-4a47754b52dc', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 23, 23, 'ለሚቃጠል መሥዋዕት በጎችህን አላቀረብህልኝም፤ በሌላም በሚቃጠል መሥዋዕትህ አላከበርኸኝም፤ በእህልም ቍርባን አላስቸገርሁህም፤ በዕጣንም አላደከምሁህም።'),
  ('110e2539-d963-509a-a2d3-cf6eb895d1f2', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 24, 24, 'ዕጣንም በገንዘብ አልገዛህልኝም፤ የመሥዋዕትህንም ስብ አልተመኘሁም፤ ነገር ግን በኀጢአትህና በበደልህ በፊቴ ቁመሃል።'),
  ('093c843c-9ba8-5843-acb9-4ec392360905', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 25, 25, 'መተላለፍን፦ ስለ እኔ ስለ ራሴ ስል የምደመስስ እኔ ነኝ፤ ኀጢአትህንም አላስብም።'),
  ('52b1572e-5907-5306-abf9-2590009ff784', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 26, 26, 'አሳስበኝ፤ በአንድነትም ሆነን እንፋረድ፤ እንድትጸድቅ አስቀድመህ በደልህን ተናገር።'),
  ('a4cbd778-c965-56f8-a612-bf8dc27ddd46', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 27, 27, 'በመጀመሪያ አባቶችህ፥ ቀጥሎም አለቆችህ በድለውኛል።'),
  ('4c676835-7981-52ff-ab7d-ef867950c0ec', '4c727f8f-9706-5ba0-a8ed-bb7ff6bf0811', '066ad478-9788-520d-a4bf-17468ae8bf8a', 28, 28, 'አለቆች መቅደሴን አረከሱ፤ ስለዚህም ያዕቆብን ለጥፋት፥ እስራኤልንም ለውርደት ሰጠሁ።'),
  ('0a34fd6f-7ab6-5b09-a86d-34c1d917ae90', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 1, 1, 'አሁንም ባሪያዬ ያዕቆብ የመረጥሁህም እስራኤል ሆይ፥ ስማ።'),
  ('2b119c63-effe-55ac-afbd-81125d960d05', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 2, 2, 'የፈጠረህ ከማኅፀንም የሠራህ የሚረዳህም እግዚአብሔር አምላክ እንዲህ ይላል፥ “ባሪያዬ ያዕቆብ የመረጥሁህም ወዳጄ እስራኤል ሆይ፥ አትፍራ።'),
  ('dc4bc341-d1e5-5b72-aa8b-c86b4e6d0d26', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 3, 3, 'በደረቅ መሬት ላይ ለሚሄድና ለተጠማ ውኃን እሰጣለሁ፤ መንፈሴን በዘርህ ላይ፥ በረከቴንም በልጆችህ ላይ አኖራለሁ፤'),
  ('be79c1fb-1e53-56b2-a757-bd28dda6a52a', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 4, 4, 'በውኃ መካከል እንዳለ ቄጠማ በፈሳሾችም አጠገብ እንደሚበቅሉ እንደ አኻያ ዛፎች ይበቅላሉ።'),
  ('021062ef-c7e8-5dbe-a408-9e8807899105', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 5, 5, 'ይህ፦ እኔ የእግዚአብሔር ነኝ ይላል፤ ያም በያዕቆብ ስም ይጠራል፤ ይህም፦ እኔ የእግዚአብሔር ነኝ ብሎ በእጁ ይጽፋል፤ በእስራኤልም ስም ይጠራል።”'),
  ('cff4319a-0834-5170-aa4c-d9df81856a89', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 6, 6, 'የእስራኤል ንጉሥ እግዚአብሔር፥ የሚቤዥም የሠራዊት ጌታ እግዚአብሔር፥ እንዲህ ይላል፥ “እኔ ፊተኛ ነኝ፤ እኔም ኋለኛ ነኝ፤ ከእኔ ሌላም አምላክ የለም።'),
  ('5084918c-3afd-51c3-ab5c-a069eab1cb67', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 7, 7, 'እንደ እኔ ያለ አዳኝ ማን ነው? ይነሣና ይጥራ፤ ይናገርም፤ ሰውን ከፈጠርሁበት ጊዜ ጀምሮ እስከ ዘለዓለሙ የሚሆነውን ያዘጋጅልኝ፤ የሚመጣውም ነገር ሳይደርስ ይናገር።'),
  ('03a35401-91fa-5871-a6b7-d4c10eebf306', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '3ceffef9-877d-52d8-aa58-dcb018ab6d36', 8, 8, 'ራሳችሁን አትደብቁ፤ ከጥንት ጀምሮ አልሰማችሁምን? አልነገርኋችሁምን? ከእኔ ሌላ አምላክ እንደ ሌለ ምስክሮች ናችሁ።”'),
  ('7ad05c2b-1633-52b0-a9a9-8757e2908453', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 1, 9, 'ጣዖታትን የሚቀርጹ ያንጊዜ አይኖሩም፤ የተቀረጸውን ምስል የሚሠሩም ሁሉ ከንቱዎች ናቸው፤ የማይረባቸውን የራሳቸውን ፍላጎት የሚያደርጉ ሁሉ ያፍራሉ።'),
  ('80ec0f68-a2fe-5737-aba1-5afff64e7d2a', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 2, 10, 'ጣዖታትን የሚሠሩ፥ የማይጠቅማቸውን ምስል የሚቀርጹና በእነርሱም የተሠሩ ሁሉ ይደርቃሉ።'),
  ('8e1b15ca-bcc7-57de-a42a-57bae763f5d6', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 3, 11, 'ከሰዎች መካከል ደንቆሮዎች ሁሉ ይሰብሰቡ፤ በአንድነትም ይቁሙ፤ በአንድነትም ያፍራሉ፤ ይዋረዳሉም።'),
  ('90dc2d5b-8549-54a1-ad59-addfa2ed96db', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 4, 12, 'ብረት ሠሪ መጥረቢያውን ይስላል፤ ጣዖቱን በመጥረቢያ ይቀርጸዋል፤ በመዶሻም መትቶ ቅርጽ ይሰጠዋል፤ በክንዱም ኀይል ይሠራዋል፤ እርሱም ይራባል፤ ይደክምማል፤ ውኃም አይጠጣም።'),
  ('44fbefc0-936a-5833-a66b-79000895eb12', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 5, 13, 'ጠራቢውም እንጨት ቈርጦ በልኩ ያቆመዋል፤ በማጣበቂያም ያያይዘዋል፤ በሰው አምሳልና በሰው ውበት ያስመስለዋል፤ በቤትም ውስጥ ያቆመዋል።'),
  ('7814f616-894b-5605-ac98-a3a426ab19ae', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 6, 14, 'እግዚአብሔር ያበቀለውን፥ በዝናምም ያሳደገውን ዛፍ ከዱር ይቈርጣል።'),
  ('a44f74b9-3d44-588c-a6c7-3180a73031bb', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 7, 15, 'ለሰውም ማገዶ ይሆናል፤ ከእርሱም ወስዶ ይሞቃል፤ አንድዶም እንጀራ ይጋግርበታል፤ ከእርሱም የተረፈውን ጣዖታትን አበጅቶ ይሰግድላቸዋል።'),
  ('c9271ff6-c3d5-5d2e-a93f-d519e00976dd', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 8, 16, 'ግማሹን በእሳት ያቃጥላል፤ በዚያም በግማሹ ሥጋ ይጠብሳል፤ ጥብሱንም ይበላና ይጠግባል፤ ይሞቃልና፥ “እሰይ ሞቅሁ፥ እሳቱን አይቻለሁ” ይላል።'),
  ('d51819aa-8525-5e4d-a196-0c7c4450ced2', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 9, 17, 'የቀረውንም እንጨት ጣዖት አድርጎ ምስል ይቀርጽበታል፤ በፊቱም ተጐንብሶ ይሰግዳል፤ ወደ እርሱም እየጸለየ፥ “አምላኬ ነህና አድነኝ” ይላል።'),
  ('73c17920-c777-584f-a611-5f045f9abefc', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 10, 18, 'አያውቁም፤ አያስቡም፤ እንዳያዩ ዐይኖቻቸው፥ እንዳያስተውሉም ልቦቻቸው ተጋርደዋል።'),
  ('8bcfde20-3c7f-5757-af1e-21c6f572e8ff', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 11, 19, 'ማንም በልቡ አያስብም፥ “ግማሽዋን በእሳት አቃጥያለሁ፤ በፍምዋም ላይ እንጀራን ጋግሬአለሁ፤ ሥጋም ጠብሼ በልቻለሁ፤ የቀረውንም አስጸያፊ ነገር አደርጋለሁን? ለዛፍስ ግንድ እሰግዳለሁን? እንዲልም ዕውቀትና ማስተዋል የለውም።'),
  ('94978196-ff6e-5ea4-a271-949437e0a433', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '964a3e01-b512-5e01-a269-a43167a6d8d4', 12, 20, 'እንግዲህ ልባቸው አመድ እንደ ሆነና እንደ በደሉ፥ ከእነርሱም ነፍሱን ለማዳን የሚችል ማንም እንደሌለ ዕወቁ፤ በቀኝ እጄ ሐሰት አለ” የሚልም እንደሌለ ተመልከቱ።'),
  ('a49524ce-672e-59cd-a585-cf7fe5b66aba', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 1, 21, 'ያዕቆብ ሆይ፥ አንተም እስራኤል፥ አገልጋዬ ነህና ይህን ዐስብ፤ እኔ ፈጥሬሃለሁ፤ አንተም ባሪያዬ ነህ፤ እስራኤል ሆይ፥ አትርሳኝ።'),
  ('6a483394-f505-5ee2-af40-29f2f6b54863', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 2, 22, 'መተላለፍህን እንደ ደመና፥ ኀጢአትህንም እንደ ጭጋግ ደምስሼአለሁ፤ ተቤዥችሃለሁና ወደ እኔ ተመለስ።'),
  ('68d2a16f-62b6-5d2e-a722-acaa76006fba', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 3, 23, 'እግዚአብሔር በእስራኤል ላይ ምሕረትን አድርጎአልና ሰማያት ደስ ይበላቸው፤ እግዚአብሔር ያዕቆብን ተቤዥቶአልና፥ በእስራኤልም ዘንድ ይከበራልና የምድር መሠረቶች መለከትን ይንፉ፤ ተራሮችና ኮረብቶች በውስጣቸው ያሉ ዛፎች ሁሉ፥ እልል ይበሉ።'),
  ('a6e4c21c-c158-5d45-aba8-9e19fd63ba99', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 4, 24, 'ከማኅፀን የሠራህ፥ የሚቤዥህ እግዚአብሔር እንዲህ ይላል፥ “ሁሉን ለብቻዬ የፈጠርሁ፥ ሰማያትን የዘረጋሁ፥ ምድርንም ያጸናሁ እግዚአብሔር እኔ ነኝ፤'),
  ('672adf36-6674-53ce-ab0a-bd97c28071c6', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 5, 25, 'በሟርት ሙት እናስነሣለን የሚሉትን፥ ከልባቸውም አንቅተው ሐሰት የሚናገሩትን ሰዎች ምልክት የሚለውጥ ማን ነው? ጥበበኞቹንም ወደ ኋላ ይመልሳል፤ ምክራቸውንም ስንፍና ያደርጋል።'),
  ('082a7262-55d4-544e-a508-51c0978da032', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 6, 26, 'የባርያውን ቃል ያጸናል፤ የመልእክተኞቹንም ምክር ይፈጽማል። ኢየሩሳሌምን፦ የሰው መኖሪያ ትሆኛለሽ፤ የይሁዳንም ከተሞች ትታነጻላችሁ፤ ምድረ በዳዎችዋም ይለመልማሉ፤” ይላል፤'),
  ('2cc82ccc-0769-52f9-aa85-bad846129f68', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 7, 27, 'ቀላይዋንም፥ “ደረቅ ሁኚ ፈሳሾችሽም ይድረቁ” ይላል፤'),
  ('7eec6e5c-a9ed-557e-a9d4-5ee46c660d25', '4fab59a5-a931-5d0a-a4e2-052f54c96be3', '21656da4-40c6-53b8-a009-b8962103be3c', 8, 28, 'ቂሮስንም፥ “ብልህ ሁን፤ እርሱም ኢየሩሳሌምን፦ ትታነጺያለሽ ቤተ መቅደስንም እመሠርታለሁ ብሎ ፈቃዴን ሁሉ ይፈጽማል” ይላል።'),
  ('d37d597a-b9e8-5db5-a203-ec8155d290f0', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 1, 1, 'እግዚአብሔር አምላክ ለቀባሁት፥ አሕዛብንም በፊቱ አስገዛ ዘንድ የነገሥታትንም ኀይል እጥል ዘንድ፥ በሮቹም እንዳይዘጉ መዝጊያዎቹን በፊቱ እከፍት ዘንድ፥ ቀኝ እጁን ለያዝሁት ለቂሮስ እንዲህ ይላል፦'),
  ('e7b452a0-08be-56d8-a018-e92ab413d6ba', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 2, 2, '“በፊትህ እሄዳለሁ፤ ተራሮችንም ዝቅ አደርጋለሁ፤ የናሱንም ደጆች እሰብራለሁ፤ የብረቱንም መወርወሪያዎች እቈርጣለሁ፤'),
  ('c2a6293e-4dde-5344-af66-0e957611a3cc', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 3, 3, 'በስምህም የምጠራህ የእስራኤል አምላክ እግዚአብሔር እኔ እንደ ሆንሁ ታውቅ ዘንድ በጨለማ የነበሩትን መዛግብት እሰጥሃለሁ፤ የማይታየውንም የተደበቀውን ሀብት እገልጥልሃለሁ።'),
  ('990ab083-57d3-584d-a028-b58cef5ce014', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 4, 4, 'ስለ አገልጋዬ ስለ ያዕቆብ፥ ስለ መረጥሁትም ስለ እስራኤል ብዬ በስምህ ጠርቼሃለሁ፤ ተቀበልሁህም፤ አንተ ግን አላወቅኸኝም።'),
  ('acf8bbc8-00d2-5edd-a117-9fe8144ec25b', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 5, 5, 'እኔ እግዚአብሔር አምላክ ነኝ፤ ከእኔም በቀር ሌላ አምላክ የለም፤ አጸናሁህ፤ አንተ ግን አላወቅኸኝም።'),
  ('61008e52-e144-59c0-a8ea-283747ffc9f0', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 6, 6, 'በፀሐይ መውጫና በምዕራብ ያሉ ከእኔ በቀር ሌላ አምላክ እንደሌለ ያውቁ ዘንድ እኔ እግዚአብሔር አምላክ ነኝ፤ ከእኔም ሌላ አምላክ የለም።'),
  ('0561d06f-5284-5376-aa10-d60814c56157', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 7, 7, 'ብርሃንን ፈጠርሁ፤ ጨለማውንም ፈጠርሁ፤ ሰላምንም አደርጋለሁ፤ ክፋትንም አመጣለሁ፤ እነዚህን ሁሉ ያደረግሁ እግዚአብሔር እኔ ነኝ።'),
  ('46366589-1492-5300-a317-5dc5271ae949', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 8, 8, '“ሰማይ በላይ ደስ ይበለው፤ ደመናትም ጽድቅን ያዝንቡ፤ ምድርም መድኀኒትን ታብቅል፤ ጽድቅም በአንድነት ይብቀል፤ እኔ እግዚአብሔር አምላክ ፈጥሬሃለሁ።'),
  ('95a606c6-01fe-519a-a8ec-8a6df4faa503', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 9, 9, '“እንደ ሸክላ ሠሪ ሥራ ውብ አድርጌ ሠራሁህ፤ ምድርን የሚያርስ ሁልጊዜ ያርሳልን? ጭቃ ሠሪውን፦ ምን ትሠራለህ? እጅ የለህምና መሥራት አትችልም ይለዋልን? ጭቃ ሠሪውን ይከራከረዋልን?'),
  ('948eee6a-5545-5ad6-a66e-c25e8a90ffdc', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 10, 10, 'አባቱን፦ ለምን ወለድኸኝ? እናቱንም፦ ለምን አምጠሽ ወለድሽኝ? ለሚል ወዮ!'),
  ('c0f380e5-56f6-5b2b-a6c5-e9f481fc3739', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 11, 11, '“የእስራኤልም ቅዱስ የሚመጣውንም የፈጠረ እግዚአብሔር አምላክ እንዲህ ይላል፦ ስለ ወንዶችና ሴቶች ልጆች ጠይቁኝ፤ ስለ እጄም ሥራ እዘዙኝ።'),
  ('5860448e-5488-54db-a002-d43059750253', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 12, 12, 'እኔ ምድርን ሠርቻለሁ፤ ሰውንም በእርስዋ ላይ ፈጥሬአለሁ፤ እኔ በእጄ ሰማያትን አጽንቼአለሁ፤ ከዋክብቶቻቸውንም ሁሉ አዝዣለሁ።'),
  ('9d309aad-e949-5663-ae10-99bab6cac4b1', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 13, 13, 'እኔ ቂሮስን በጽድቅ አስነሥቼዋለሁ፤ መንገዱንም ሁሉ አቀናለሁ፤ እርሱ ከተማዬን ይሠራል፤ በዋጋም ወይም በጉቦ ሳይሆን ምርኮኞችን ያወጣል፥ ይላል የሠራዊት ጌታ እግዚአብሔር።”'),
  ('78754190-1d70-5d57-a879-5d98603f71a2', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 14, 14, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “ግብፅና የኢትዮጵያ ንግዶች ደከሙ፤ ቁመተ ረዥሞች የሳባ ሰዎች ወደ አንተ ያልፋሉ፤ ለአንተም ይገዙልሃል፤ እጆቻቸውን ታስረው በኋላህ ይከተሉሃል፤ በፊትህም ያልፋሉ፤ ለአንተም እየሰገዱ፦ በእውነት እግዚአብሔር ከአንተ ጋር ነው፤ ከእርሱም ሌላ አምላክ የለም ብለው ይለምኑሃል።'),
  ('0cfc77bd-dd91-5b66-aa84-8afdc2a5e83a', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 15, 15, 'አንተ እግዚአብሔር ነህ፤ የእስራኤልም መድኀኒት አምላክ እንደ ሆንህ አላወቅንህም።'),
  ('fc681925-8653-5b13-a6fe-380515a1d96b', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 16, 16, 'የሚቃወሙት ሁሉም ያፍራሉ፤ ይዋረዱማል፤ አፍረውም ይሄዳሉ።'),
  ('fdcab0ad-3004-5abd-a24b-19de52d3798f', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 17, 17, 'ደሴቶች ሆይ፥ ወደ እኔ ተመለሱ፤ እግዚአብሔር ግን እስራኤልን በዘለዓለማዊ መድኀኒት ያድነዋል፤ እናንተም ለዘለዓለም አታፍሩምና አቷረዱም።”'),
  ('8c092401-13f4-5c47-a5b5-1806a54aa489', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 18, 18, 'ሰማይን የፈጠረ እግዚአብሔር፥ እርሱም ምድርን የሠራና ያደረገ ያጸናትም፥ መኖሪያም ልትሆን እንጂ ለከንቱ እንድትሆን ያልፈጠራት አምላክ፥ እንዲህ ይላል፥ “እኔ እግዚአብሔር ነኝ፤ ከእኔም በቀር ሌላ የለም።'),
  ('56308d83-d7fd-5bfb-a8bd-d50c26d8d2c8', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 19, 19, 'በስውር ወይም በጨለማ ስፍራ አልተናገርሁም፤ ለያዕቆብ ዘር፦ በከንቱ ፈልጉኝ አላልሁም፤ ጽድቅን የምናገር፥ ቅን ነገርንም የምናገር እኔ እግዚአብሔር ነኝ።'),
  ('02fa727f-99e4-53f1-a901-1516909251e3', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 20, 20, 'እናንተ ከአሕዛብ ወገን ሆናችሁ ያመለጣችሁ፥ ተሰብስባችሁ ኑ፤ በአንድነትም ተማከሩ፤ የተቀረጸውን የምስላቸውን እንጨት የሚሸከሙና ያድን ዘንድ ወደማይችል አምላክ የሚጸልዩ ዕውቀት የላቸውም።'),
  ('d25be4f7-99d4-589f-a0dd-ac5910fc6dd5', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 21, 21, 'የሚናገሩ ከሆነ ከጥንት ጀምሮ ይህን ምስክርነት ያደረገ ማን እንደ ሆነ በአንድነት ያውቁ ዘንድ ይቅረቡ። ያሳየሁም የተናገርሁም እኔ እግዚአብሔር አይደለሁምን? ከእኔም በቀር ሌላ አምላክ የለም፤ እኔ ጻድቅ አምላክና መድኀኒት ነኝ፥ እንደ እኔም ያለ ማንም የለም።'),
  ('7d24227a-9bcf-59f7-a1d1-7372f1a68bfc', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 22, 22, 'እናንተ በምድር ዳርቻ ያላችሁ ሁሉ፥ እኔ አምላክ ነኝና፥ ከእኔም በቀር ሌላ የለምና ወደ እኔ ተመለሱ፤ ትድኑማላችሁ።'),
  ('2c1a8953-bc48-548a-a5a6-2d08323d3bc1', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 23, 23, 'ቃሌ ከአፌ በጽድቅ ወጥታለች፤ አትመለስምም፤ ጕልበት ሁሉ ለእኔ ይንበረከካል፤ ምላስም ሁሉ በእግዚአብሔር ይምላል ብዬ በራሴ ምያለሁ።”'),
  ('e8daa85e-72df-5b38-ac31-c85eb61998a5', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 24, 24, 'ክብርና ጽድቅ ወደ እርሱ ይመጣሉ፤ ከእግዚአብሔርም የሚርቁ ሁሉ ያፍራሉ።'),
  ('7969a3a5-d4e1-5c58-ae93-c256a43566a5', 'ce41fff4-9c6b-5cbf-a4a0-f4c4e8b45314', 'fa1ee5dd-f1bb-54dc-a25a-8b1aa359bcc3', 25, 25, 'የእስራኤልም ልጆች ዘር ሁሉ በእግዚአብሔር ይጸድቃሉ፤ ይከብራሉም ይባላል።'),
  ('557be09c-012f-5233-a523-e8afcba1ffaa', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 1, 1, 'ቤል ወደቀ፤ ዳጎን ተሰባበረ፤ ምስሎቻቸውም እንደ ትቢያ ሆኑ፤ አራዊትና እንስሳም ይረግጡአቸዋል፤ እንደ ፋንድያም ሸክም የሚያጸይፉ ናቸውና አያነሡአቸውም።'),
  ('e2c3e7d6-5f3d-596b-aa70-980e9d72e4d8', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 2, 2, 'ደካሞች ናቸው፤ ኀይልም የላቸውም፤ ከጦርነትም ራሳቸውን ለማዳን አልቻሉም፤ ራሳቸው ግን ተማረኩ።'),
  ('9bc23263-1e0d-5a0f-a775-895947c38c2a', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 3, 3, 'እናንተ የያዕቆብ ቤት ሆይ፥ የእስራኤልም ቤት ቅሬታ ሁሉ፥ ከማኅፀንም ጀምሮ የተሸከምኋችሁ፥ ከሕፃንነትም ጀምሮ ያስተማርኋችሁ፥ ስሙኝ።'),
  ('ce309ca0-b140-50cf-ab24-dab400a7a46d', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 4, 4, 'እስከ ሽምግልና ድረስ እኔ ነኝ፤ እስከ ሽበትም ድረስ እኔ ነኝ፤ እኔ እታገሣችኋለሁ፤ እኔ ሠርቻለሁ፤ እኔም ይቅር እላለሁ፤ እኔም እቀበላችኋለሁ፤ እኔም አድናችኋለሁ።'),
  ('4129690b-3adb-5e9d-adba-68abac6c961c', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 5, 5, 'እንግዲህ በማን ትመስሉኛላችሁ? የምትሳሳቱ እናንተ ሁላችሁ፥ እዩ፤ አስተውሉም።'),
  ('d4f5c896-7182-5e4d-a918-5eb6dc8bef3d', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 6, 6, 'ወርቁንና ብሩን ከኮሮጆ የሚያወጡና በሚዛን የሚመዝኑ እነርሱ አንጥረኛውን ይቀጥራሉ፤ እርሱም ጣዖት አድርጎ ይሠራዋል፤ ለዚያም ይጐነበሱለታል፤ ይሰግዱለትማል።'),
  ('b7413e86-5ddf-5625-a9b7-66e18a0d653d', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 7, 7, 'በጫንቃቸው ላይ ተሸክመውት ይሄዳሉ፤ በስፍራውም በአኖሩት ጊዜ በዚያ ይቆማል፤ ከስፍራውም ፈቀቅ አይልም፤ ሰውም ወደ እርሱ ቢጮህ አይሰማውም፤ ከክፉም አያድነውም።'),
  ('bb7feb2e-52e1-5b0a-af30-b84d46f967f1', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 8, 8, 'ይህን ዐስቡና አልቅሱ፤ የተሳሳታችሁ ሆይ፥ ንስሓ ግቡ፤ ልባችሁንም መልሱ።'),
  ('013fc0af-f1ac-5891-a987-4d7f78a0fc78', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 9, 9, 'እኔ አምላክ ነኝና፤ ያለ እኔም ሌላ የለምና የቀድሞውንና የጥንቱን ነገር ዐስቡ። እኔ እግዚአብሔር ነኝ፤ እንደ እኔም ያለ ማንም የለም።'),
  ('294a52f9-a06c-5749-a20c-c0c28bedc7a8', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 10, 10, 'በመጀመሪያ መጨረሻውን፥ ከጥንትም ያልተደረገውን እናገራለሁ፤ ምክሬ ትጸናለች፤ የመከርሁትንም ሁሉ አደርጋለሁ እላለሁ።'),
  ('ade09029-e41e-56e6-a986-fb0fdebb6355', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 11, 11, 'ከምሥራቅና ከሩቅ ሀገር ስለ መከርሁት ምክር ዎፍን እጠራለሁ፤ ተናገርሁ፤ አመጣሁም፤ ፈጠርሁ፤ አደረግሁም፤ አመጣሁት፤ መንገዱንም አቀናሁለት።'),
  ('c98702e4-8fb0-5dea-a0de-e976f10a0ff6', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 12, 12, 'እናንተ ከጽድቅ የራቃችሁ ልበ ጥፉዎች፥ ስሙኝ፤'),
  ('0b71ce2e-2301-5853-ae87-d38dcd6f26c9', '61693824-8282-52d1-a991-b5477be8b038', 'adcee7df-6930-5765-abc4-a6978f5a9ad4', 13, 13, 'ጽድቄን አመጣኋት፤ ከእኔ ዘንድ የምትገኝ መድኀኒትንም አላዘገይም፤ ከጽዮን ለክብር እንዲሆን መድኀኒትን ለእስራኤል ሰጥቻለሁ።'),
  ('a853747c-1d48-5a38-a789-bca0c2df7a07', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 1, 1, 'አንቺ ድንግል የባቢሎን ልጅ ሆይ፥ ውረጂ፤ በትቢያም ላይ ተቀመጪ፤ የከለዳውያን ሴት ልጅ ሆይ፥ ከዚህ በኋላ ለስላሳና ቅምጥል አትባዪምና ያለ ዙፋን በመሬት ላይ ተቀመጪ።'),
  ('e91a6ca0-f992-5929-a20a-671fdb64ae8a', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 2, 2, 'ወፍጮ ወስደሽ ዱቄትን ፍጪ፤ ክንብንብሽን ግለጪ፤ ሽበትሽ ይታይ፤ ባትሽን ግለጪ፤ ወንዙንም ተሻገሪ።'),
  ('cafd16fe-d16a-5a9e-a526-a18b2eee26fe', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 3, 3, 'ኀፍረትሽ ይገለጣል፤ ውርደትሽም ይታያል፤ ጽድቅ ከአንቺ ይወሰዳል፤ እንዲሁም በአንቺ ፋንታ ሰውን አሳልፌ አልሰጥም።'),
  ('54636a3a-7198-5592-a083-a0cbc06e723c', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 4, 4, 'ታዳጊሽ የሠራዊት ጌታ እግዚአብሔር፥ ስሙ የእስራኤል ቅዱስ ነው።'),
  ('62b23150-5630-5a78-a415-a670c5d63ac9', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 5, 5, 'የከለዳውያን ሴት ልጅ ሆይ፥ ከዚህ በኋላ፥ “የመንግሥታት እመቤት” አትባዪምና በድንጋጤ ዝም ብለሽ ተቀመጪ፤ ወደ ጨለማም ውስጥ ግቢ።'),
  ('6170d66c-ccf0-5267-a80e-bff149d160b5', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 6, 6, 'በሕዝቤ ላይ ተቈጥቼ ነበር፤ ርስቴንም አረከስሽ፤ በእጅሽም አሳልፌ ሰጠኋቸው፤ ለሽማግሌዎቻቸው አልራራሽም፤ ቀንበራቸውንም እጅግ አክብደሻል።'),
  ('5dbff2d5-ddfa-5dc0-aebe-6853b028e2eb', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 7, 7, 'አንቺም፥ “እኔ ለዘለዓለም እመቤት እሆናለሁ” ብለሻል፤ ይህንም በልብሽ አላሰብሽም፤ ፍጻሜውንም አላስታወስሽም።'),
  ('8290b7e3-3a40-5ec5-aa67-6e19d5fa532c', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 8, 8, 'አሁንም አንቺ ቅምጥል ተዘልለሽ የምትቀመጪ፥ በልብሽም፥ “እኔ ነኝ ከእኔም በቀር ሌላ የለም፤ መበለትም ሆኜ አልኖርም፤ የወላድ መካንነትንም አላውቅም” የምትዪ፥ ይህን ስሚ፤'),
  ('3b7ce91a-4411-5afb-ad76-74e8cbabb42a', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 9, 9, 'አሁን ግን በአንድ ቀን እነዚህ ሁለት ነገሮች በድንገት ይመጡብሻል፤ የወላድ መካንነትና መበለትነት ስለ መተቶችሽ ብዛትና ስለ አስማቶችሽ ጽናት ፈጽመው ይመጡብሻል።'),
  ('88fd1ca9-2e4f-5974-aeec-d664657de504', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 10, 10, 'በክፋትሽ ታምነሻል፤ አንቺ ግን፥ “እኔ ነኝ፤ ከእኔ በቀር ሌላ የለም” ብለሻል፤ በዝሙትሽ ኀፍረት ያሰብሽውንም ዕወቂ፤ በልብሽ፥ “እኔ ነኝ ከእኔም በቀር ሌላ የለም” ብለሻልና።'),
  ('df6d35d3-fab1-5ca8-a95c-b9f3dcb7e44c', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 11, 11, 'ስለዚህ ምክንያት ጥፋት ይመጣብሻል፤ ጥልቀቱን አታውቂም፤ በውስጡም ትወድቂያለሽ፤ ጕስቁልና ይመጣብሻል፤ ማምለጥም አይቻልሽም፤ ሞት ድንገት ይመጣብሻል፤ አታውቂምም።'),
  ('2eeacb94-c660-58b0-acc7-9ad7a3ac624c', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 12, 12, 'ምናልባትም ሊያድንሽ የሚችል እንደ አለ፥ ከአስማቶችሽና ከሕፃንነትሽ ጀምረሽ ከተማርሽው ከመተቶችሽ ብዛት ጋር ቁሚ።'),
  ('ba4cd96f-ae2f-5129-ae4e-c71fe4ed255f', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 13, 13, 'በክፉ ምክርሽ ደክመሻል፤ አሁንም የሰማይን ከዋክብት የሚቈጥሩ፥ ከዋክብትንም የሚመለከቱ ይነሡ፤ ያድኑሽም፤ ምን እንደሚመጣብሽም ይንገሩሽ፤'),
  ('3d51433f-8c93-58fd-a1aa-d045626c1e23', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 14, 14, 'እነሆ፥ ሁሉም እንደ እብቅ እሳት ይቃጠላሉ፤ ሰውነታቸውንም ከነበልባል ኀይል አያድኑም፤ እንደ እሳትም ፍም ይሆኑብሻል፤ በላያቸውም ትቀመጫለሽ።'),
  ('4a9d12cf-9d7d-546d-ae97-42de01a0f3ea', 'e6820093-f524-529c-a8d0-18958cb3ab5c', 'f688af38-6441-58f7-acb2-967b7e7440c5', 15, 15, 'እነርሱ ረዳቶችሽ ይሆናሉ፤ ከሕፃንነትሽ ጀምረሽ ደከምሽ፤ ሰው በራሱ ይሳሳታል፤ ለአንቺ ግን መድኀኒት የለሽም።'),
  ('2b4e75db-d5e4-5bdc-a0c9-0c48864c45db', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 1, 1, 'እናንተ በእስራኤል ስም የተጠራችሁ፥ ከይሁዳም የወጣችሁ፥ በእውነት ሳይሆን፥ በጽድቅም ሳይሆን እርሱን እየጠራችሁ በእስራኤል አምላክ በእግዚአብሔር ስም የምትምሉ የያዕቆብ ቤት ሆይ፥ ይህን ስሙ፤'),
  ('213ae06f-d60b-5c7b-a691-efbe8c9d54d6', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 2, 2, 'በቅድስት ከተማ ስም የተጠራችሁ፥ ስሙም የሠራዊት ጌታ እግዚአብሔር በሚባል በእስራኤል አምላክ የምትደገፉ፥ ይህን ስሙ።'),
  ('3b394161-4361-5b2b-ac13-2a7a5448cc70', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 3, 3, 'የቀድሞውን ነገር ከጥንት ተናግሬአለሁ፤ ከአፌም ወጥቶአል፤ ድንገትም ያደረግሁት ምስክር ሆኖአል፤ እርሱም ተፈጽሞአል።'),
  ('3a2137db-b685-5146-a377-7c2f3698a52b', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 4, 4, 'አንተ እልከኛ፥ አንገትህም የብረት ጅማት፥ ግንባርህም ናስ እንደ ሆነ ዐውቄአለሁ፤'),
  ('46ce4036-c271-5ffa-ac9f-c93c34128cb0', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 5, 5, 'ስለዚህ፥ አንተ፥ “ጣዖቴ ይህን አድርጎአል፤ የተቀረጸው ምስሌና ቀልጦ የተሠራው ምስሌም ይህን አዘዙኝ” እንዳትል፥ የሚሆነውን ከመሆኑ በፊት ነገርሁህ፤ አስረዳሁህም፤'),
  ('377c2c86-df37-5805-a863-b399a89ab894', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 6, 6, 'ሁሉን ሰምተሃሃል፤ አላወቅህም፤ ከዛሬ ጀምሮ የሚሆነውን አዲስ ነገር ገለጥሁልህ።'),
  ('b5647674-7f81-5291-a950-999fbedbaf12', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 7, 7, 'እነርሱም አሁን እንጂ ከጥንት አልተፈጠሩም፤ አንተም፥ “እነሆ፥ ዐውቄአቸዋለሁ” እንዳትል ከዛሬ በፊት አልሰማሃቸውም።'),
  ('6184a933-adfe-5ee0-aa4b-e15cb7a05397', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 8, 8, 'አላወቅህም፤ አላስተዋልህም፤ ጆሮህን ከጥንት አልከፈትሁልህም፤ አንተ ፈጽሞ ወንጀለኛ እንደ ሆንህ፥ ከማኅፀንም ጀምረህ ተላላፊ ተብለህ እንደ ተጠራህ ዐውቄአለሁና።'),
  ('01bb09e1-8494-5155-a500-12f9dbcd1840', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 9, 9, 'ስለ ስሜ ቍጣዬን አሳይሃለሁ፤ እንዳላጠፋህም ግርማዬን አመጣብሃለሁ።'),
  ('9b401c07-8551-5fe0-a6aa-6e7157afbe1a', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 10, 10, 'እነሆ፥ ለወጥሁህ፤ ነገር ግን በብር አይደለም፤ ከመከራም እቶን አውጥቼሃለሁ።'),
  ('c1b7fd9a-081e-5198-a33f-9fc1d94be3d1', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 11, 11, 'ስለ እኔ፥ ስለ ራሴ ይህን ለአንተ አደርገዋለሁ፤ ስሜ ተነቅፎአልና፤ ክብሬንም ለሌላ አልሰጥም።'),
  ('83783107-1dc9-5672-aed2-e8d20bd3ed1c', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 12, 12, 'ያዕቆብ ሆይ፥ የጠራሁህም እስራኤል ሆይ፥ ስማኝ፤ እኔ ፊተኛው ነኝ፤ እኔም ዘለዓለማዊ ነኝ።'),
  ('4491bc0f-d6f8-5954-a199-285522ff1e55', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 13, 13, 'እጄም ምድርን መሥርታለች፤ ቀኜም ሰማያትን አጽንታለች፤ እጠራቸዋለሁ፤ በአንድነትም መጥተው ይቆማሉ።'),
  ('820d42ec-c8bb-55ba-a698-48874a1a7a41', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 14, 14, 'ሁሉም በአንድነት ተሰብስበው ይሰማሉ፤ ይህን ማን ነገራቸው? አንተን በመውደድ የከለዳውያንን ዘር አስወግድ ዘንድ ፈቃድህን በባቢሎን ላይ አደረግሁ።'),
  ('5a1c0c7f-79df-5c5d-ad46-2649185803a0', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 15, 15, 'እኔ ራሴ ተናግሬአለሁ፤ እኔ ጠርቼዋለሁ፤ አምጥቼዋለሁ፤ መንገዱም ትከናወንለታለች።'),
  ('c720984c-9193-560c-ac9f-ee754f4d1142', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 16, 16, 'ወደ እኔ ቅረቡ፤ ይህንም ስሙ፤ እኔ ከጥንት ጀምሬ በስውር አልተናገርሁም፤ ከሆነበት ዘመን ጀምሮ እኔ በዚያ ነበርሁ፤ አሁንም ጌታ እግዚአብሔርና መንፈሱ ልከውኛል።'),
  ('7893e3b9-386a-586b-a4cc-4c078b843d42', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 17, 17, 'ታዳጊህ፥ የእስራኤል ቅዱስ፥ እንዲህ ይላል፥ “እኔ የሚረባህን ነገር የማስተምርህ የምትሄድባትንም መንገድ እንዴት እንደምታገኝ የምመራህ አምላክህ እግዚአብሔር ነኝ።'),
  ('3b1ea554-9e27-59d0-a0ea-210c7f3266c8', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 18, 18, 'ትእዛዜን ብትሰማ ኖሮ፥ ሰላምህ እንደ ወንዝ ጽድቅህም እንደ ባሕር ሞገድ በሆነ ነበር፤'),
  ('371c98c1-5479-56bf-a1bf-dc075b6cad3d', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 19, 19, 'ዘርህም እንደ አሸዋ የሆድህም ትውልድ እንደ ምድር ትቢያ በሆነ ነበር፤ አሁንም ስምህ ከፊቴ ባልጠፋና ባልፈረሰ ነበር።'),
  ('bba42fb3-f366-53cd-a32a-9ded9fdcb3f1', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 20, 20, 'ከባቢሎን ውጡ፤ ከከለዳውያንም ኰብልሉ፤ በእልልታ ድምፅ ተናገሩ፤ ይህም ይሰማ፤ እስከ ምድርም ዳርቻ ድረስ አውሩና፥ “እግዚአብሔር ባርያውን ያዕቆብን ታድጎታል” በሉ።'),
  ('31e02bb0-0cb9-580a-aaaa-02faf8faad70', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 21, 21, 'በምድረ በዳም በተጠሙ ጊዜ፥ ውኃን ከዓለቱ ውስጥ ያፈልቅላቸው ነበር፤ ዓለቱም ተሰነጠቀ፤ ውኃውም ይፈስስላቸው ነበር፤ ሕዝቤም ይጠጡ ነበር።'),
  ('c140655b-9ddc-5590-abac-00277237e53a', '0a6b0a3e-8ae0-5660-aacd-988d555ee26a', 'c0a63b4a-a77b-5629-abcb-a0ea216b612b', 22, 22, 'እንግዲህ ኃጥኣን ደስታ አያደርጉም፤ ይላል እግዚአብሔር።'),
  ('39dd3cd5-d1c0-5fb7-a0fb-cb8ff2f0b02c', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 1, 1, 'ደሴቶች ሆይ፥ ስሙኝ፤ እናንተም አሕዛብ፥ አድምጡ፤ ከረዥም ዘመን በኋላ እንዲህ ይሆናል ይላል እግዚአብሔር፤ ከእናቴም ሆድ ጀምሮ ስሜን ጠርቶአል፤'),
  ('f1e3ffa3-baf2-5f84-a9ed-960399974c49', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 2, 2, 'አፌንም እንደ ተሳለ ሰይፍ አድርጎአል፤ በእጁ ጥላ ሰውሮኛል፤ እንደ ተሳለ ፍላጻም አድርጎኛል፤ በሰገባው ውስጥም ሸሽጎኛል።'),
  ('90e3f64f-ec15-5a7c-a351-4f221db2bc91', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 3, 3, 'እርሱም፥ “እስራኤል ሆይ፥ አንተ ባርያዬ ነህ፤ በአንተም እከበራለሁ” አለኝ።'),
  ('e9573be6-46a2-5f50-a73e-682433583e8e', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 4, 4, 'እኔ ግን፥ “በከንቱ ደከምሁ፤ ምንም ጥቅም ለሌለውና ለከንቱ ጕልበቴን ፈጀሁ፤ ስለዚህም እግዚአብሔር ይፈርድልኛል፤ መከራዬም በአምላኬ ፊት ነው” አልሁ።'),
  ('fdf0c8e9-efe1-5b05-a348-c50cace0d81f', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 5, 5, 'አሁንም በእግዚአብሔር ፊት ከብሬአለሁና፥ አምላኬም ጕልበት ሆኖኛልና ያዕቆብን ወደ እርሱ እንድመልስ፥ እስራኤልንም ወደ እርሱ እንድሰበስብ ባርያ እሆነው ዘንድ ከማኅፀን ጀምሮ የፈጠረኝ እግዚአብሔር እንዲህ ይላል።'),
  ('f651b16f-658d-526c-a822-5769a6bb4b04', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 6, 6, 'እርሱም፥ “የያዕቆብን ነገዶች እንደገና እንድታስነሣ፥ ከእስራኤልም የተበተኑትን ወደ አባቶች ቃል ኪዳን እንድትመልስ ባርያዬ ትሆን ዘንድ ለአንተ እጅግ ታላቅ ነገር ነውና፥ እስከ ምድር ዳር ድረስ መድኀኒት ትሆን ዘንድ ለአሕዛብ ብርሃን አድርጌሃለሁ” ይላል።'),
  ('54f92c0c-b8d7-57f0-ad10-c7d2a9f342bc', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', '58940714-8118-532c-ad1f-1ebf7529e1fe', 7, 7, 'ታዳጊህ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “ሕይወቱን የሚያስጨንቃትን፥ በአሕዛብ የተጠላውን የአለቆችን ባርያ ቀድሱት፤ ነገሥታት ያዩታል፤ አለቆችም ስለ እግዚአብሔር ብለው ተነሥተው ይሰግዱለታል፤ የእስራኤል ቅዱስ ታማኝ ነውና፥ እኔም መርጨሃለሁና።”'),
  ('638dc487-3ba3-587f-a71b-e2566c6ec0aa', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 1, 8, 'እግዚአብሔር እንዲህ ይላል፥ “በተመረጠችው ዕለት ሰምቼሃለሁ፤ ድኅነት በሚደረግበትም ቀን ረድቼሃለሁ፤ ቃል ኪዳን አድርጌ ለሕዝቡ ሰጥቼሃለሁ፤ ምድርንም ታቀና ዘንድ፥ ውድማ የሆኑትን ርስቶች ትወርስ ዘንድ፤'),
  ('7ddce1af-7923-5988-a2e4-1351c078d40b', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 2, 9, 'የተጋዙትንም፦ ውጡ፤ በጨለማም የተቀመጡትን፦ ተገለጡ፤ ትል ዘንድ።” በመንገድም ሁሉ ላይ ይሰማራሉ፤ ማሰማሪያቸውም በጥርጊያ ጎዳና ሁሉ ላይ ይሆናል።'),
  ('06f39c85-691e-54ce-a56e-52a6f55d87be', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 3, 10, 'የሚራራላቸውም ያጽናናቸዋልና፥ በውኃ ምንጮችም በኩል ይመራቸዋልና አይራቡም፤ አይጠሙም፤ የፀሐይ ትኩሳትም አይጐዳቸውም።'),
  ('df8d88ae-45c9-5c14-a7ac-dbd79ba64022', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 4, 11, 'ተራሮችንም ሁሉ መንገድ አደርጋለሁ፤ ጎዳናዎችም ሁሉ መሰማርያ ይሆናሉ።'),
  ('f4762a2a-86b0-539b-a802-4f1030a3f07d', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 5, 12, 'እነሆ፥ እነዚህ ከሩቅ፥ እነሆም፥ እነዚህ ከሰሜንና ከምዕራብ፥ እነዚህም ከፋርስ ሀገር ይመጣሉ።'),
  ('1d17d20c-2330-529f-a54d-8bb99fed4d44', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 6, 13, 'እግዚአብሔር ሕዝቡን ይቅር ብሎአልና፥ ከሕዝቡም ችግረኞቹን አጽንቶአልና። ሰማያት ሆይ፥ ደስ ይበላችሁ፤ ምድርም ደስ ይበላት፤ ተራሮችም እልል ይበሉ።'),
  ('f22c0836-9328-5699-adfa-907674163bd1', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 7, 14, 'ጽዮን ግን፥ “እግዚአብሔር ትቶኛል፤ ጌታም ረስቶኛል” አለች።'),
  ('1b7b3bbf-7af8-5ab5-a052-601498f2704e', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 8, 15, '“በውኑ ሴት፥ ልጅዋን ትረሳለችን? ከማኅፀንዋ ለተወለደውስ አትራራምን? ሴት ይህን ብትረሳ፥ እኔ አንቺን አልረሳሽም።'),
  ('aad0c968-baed-543c-a208-fca3fc340017', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 9, 16, 'እነሆ፥ እኔ በእጄ ግንቦችሽን ሣልሁ፤ አንቺም ሁልጊዜ በፊቴ ነሽ።'),
  ('1597e5b6-c32c-5591-a215-1536cf659a24', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 10, 17, 'ከአፈረሱሽ በኋላ ፈጥነሽ ትታነጺያለሽ፤ ያፈረሱሽ ከአንቺ ይወጣሉ።'),
  ('f4e10f03-d552-502c-a373-be7aae3bd56f', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 11, 18, 'ዐይንሽን አንሥተሽ በዙሪያሽ ተመልከቺ፤ እነዚህ ሁሉ ተሰብስበው ወደ አንቺ ይመጣሉ። እኔ ሕያው ነኝና እነዚህን ሁሉ እንደ ጌጥ ትለብሻቸዋለሽ፤ እንደ ሙሽራም ትጐናጸፊአቸዋለሽ ይላል እግዚአብሔር።'),
  ('d3eaa362-8a80-54e9-a492-e6a00e0c665a', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 12, 19, 'ፈርሰሻልና፥ ፈጽመሽም ጠፍተሻልና በአንቺ ለሚኖሩ ሰዎች ዛሬ ጠባብ ትሆኚባቸዋለሽ፤ ያጠፉሽም ከአንቺ ይርቃሉ።'),
  ('42c06c81-0642-53f7-a2ea-c7dee11554de', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 13, 20, 'አጥተሻቸው የነበሩት ልጆችሽም በጆሮሽ፦ ስፍራ ጠብቦናልና የምንቀመጥበት ቦታ አስፊልን ይላሉ።'),
  ('3f960f48-d4a0-5eca-ac2c-caa35395c476', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 14, 21, 'አንቺም በልብሽ፦ የወላድ መካን ሆኛለሁና፥ እኔም መበለት ነኝና እነዚህን ማን ወለደልኝ? እነዚህንስ ማን አሳደጋቸው? እነሆ፥ ብቻዬን ቀርቼ ነበር፤ እነዚህስ ከወዴት መጡ?” ትያለሽ።'),
  ('30644da9-ad96-512a-a9fa-d4bc8a5ff7ee', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 15, 22, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “እነሆ፥ እጄን ወደ አሕዛብ አነሣለሁ፤ ዓርማዬንም ወደ ደሴቶች አቆማለሁ፤ ወንዶች ልጆችሽንም በብብታቸው ታቅፈው ያመጡአቸዋል፤ ሴቶች ልጆችሽንም በጫንቃቸው ላይ ይሸከሙአቸዋል።'),
  ('519784ac-bac8-5d39-a8e0-52ba9c4b4cfc', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 16, 23, 'ነገሥታትም አሳዳጊዎች አባቶችሽ ይሆናሉ፤ እቴጌዎቻቸውም ሞግዚቶችሽ ይሆናሉ፤ ግንባራቸውንም ወደ ምድር ዝቅ አድርገው ይሰግዱልሻል፤ የእግርሽንም ትቢያ ይልሳሉ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቂያለሽ፤ እኔንም በመተማመን የሚጠባበቁ አያፍሩም።”'),
  ('61d75d07-76c4-520c-a58d-1b9bdf8e2049', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 17, 24, 'በውኑ ምርኮን ከኀይለኛ እጅ መቀማት ይቻላልን? በግፍ የተማረከስ ይድናልን?'),
  ('a3baa368-6f54-559a-a765-badb23c305b2', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 18, 25, 'እግዚአብሔር ግን እንዲህ ይላል፥ “በኀያላን የተማረኩ ይወሰዳሉ፤ የጨካኞችም ብዝበዛ ያመልጣል፤ እኔም ፍርድሽን እፈርድልሻለሁ፤ ልጆችሽንም አድናለሁ።'),
  ('000161c9-16bb-5921-a1e7-7bd53626b213', 'd2327a34-3e65-52a5-a28e-40fb94479ac7', 'b8c09e88-2cae-5ddc-ab71-4b57d2353c88', 19, 26, 'የአስጨናቂዎችሽንም ሥጋቸውን ይበላሉ፤ እንደ ጣፋጭ ወይን ጠጅም ደማቸውን ጠጥተው ይሰክራሉ፤ ሥጋ ለባሹም ሁሉ እኔ እግዚአብሔር መድኀኒትሽና ታዳጊሽ፥ የያዕቆብን ኀይል የምደግፍ እንደ ሆንሁ ያውቃሉ።”'),
  ('c8c4bf5b-51ff-591a-a40a-2b77701aa1ad', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 1, 1, 'እግዚአብሔር እንዲህ ይላል፥ “እናታችሁን የፈታሁበት የፍችዋ ደብዳቤ የት አለ? ወይስ እናንተን የሸጥሁ ከአበዳሪዎች ለማን ነው? እነሆ፥ ስለ ኀጢአታችሁ ተሸጣችኋል፤ ስለ በደላችሁም እናታችሁ ተፈትታለች።'),
  ('97ac2aeb-0003-55f5-a39d-298c08c17378', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 2, 2, 'እነሆ፥ መጣሁ፤ ሰውም አልነበረም፤ ተጣራሁ፤ የሚመልስም አልነበረም፤ እጄ ለማዳን ጠንካራ አይደለምን? ወይስ ለማዳን አልችልምን? እነሆ፥ በገሠጽሁ ጊዜ ባሕርን አደርቃለሁ፤ ወንዞችንም ምድረ በዳ አደርጋቸዋለሁ፤ ውኃም በማጣት ዐሣዎቻቸው ይሞታሉ፤ በጥማትም ያልቃሉ።'),
  ('aec9781b-67e1-5a06-af8a-ad7c15ab3e36', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 3, 3, 'ሰማይን በጨለማ እሸፍነዋለሁ፤ መጋረጃውንም ማቅ አደርጋለሁ።”'),
  ('7b7161f1-c38e-5ca1-a7f6-445f25d2f269', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 4, 4, 'የምናገረውን ቃል አውቅ ዘንድ ጌታ እግዚአብሔር የጥበብ ምላስን ሰጥቶኛል፤ ማለዳ ማለዳ ያነቃኛል፤ ለመስማትም ጆሮን ሰጥቶኛል።'),
  ('fd92b5d0-6d62-57fa-ab3b-01d242a3248b', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 5, 5, 'የጌታ የእግዚአብሔር ተግሣጽም ጆሮዬን ከፍቶአል፤ እኔም ዐመፀኛ አልነበርሁም፤ አልተከራከርሁም።'),
  ('19bf35b8-568a-534d-adb7-5c87ae0fe212', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 6, 6, 'ጀርባዬን ለግርፋት፥ ጕንጬንም ለጽፍዐት ሰጠሁ፤ ፊቴንም ከምራቅ ኀፍረት አልመለስሁም።'),
  ('edd4ac1b-50ef-5f8a-ae69-37b5e8d9104f', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 7, 7, 'ጌታ እግዚአብሔር ረዳኝ፤ ስለዚህም አላፈርሁም፤ ፊቴንም እንደ ባልጩት ድንጋይ አድርጌዋለሁ፤ እንዳላፍርም አውቃለሁ።'),
  ('d762470a-b7b9-52e7-a12a-cfa532ad6bc3', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 8, 8, 'የሚያጸድቀኝ ቅርብ ነው፤ ከእኔስ ጋር የሚከራከር ማን ነው? እስቲ በእኔ ላይ ይነሣ፤ የሚከራከረኝስ ማን ነው? ወደ እኔ ይቅረብ።'),
  ('dc3fbbd0-e61c-557d-aa36-fe7f84e1ebb7', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 9, 9, 'እነሆ፥ ጌታ እግዚአብሔር ይረዳኛል፤ ማን ይጎዳኛል? እነሆ፥ ሁላችሁ እንደ ልብስ ታረጃላችሁ፤ ብልም ይበላችኋል።'),
  ('fcf0aa0c-32a4-564b-a7a3-72cdf91de538', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 10, 10, 'ከእናንተ እግዚአብሔርን የሚፈራ፥ ማን ነው? የባሪያውንም ቃል ይስማ፤ በጨለማም የምትሄዱ፥ ብርሃንም የሌላችሁ በእግዚአብሔር ስም ታመኑ፤ በእግዚአብሔርም ተደገፉ፤'),
  ('ea247a9f-6f2a-52ac-abd8-a3f0e26bbd23', '4bdd0eb8-5eae-588f-a530-ad3b14079a0a', '50fa7bdc-25ae-5917-aa33-772c30bf1112', 11, 11, 'እነሆ፥ እሳት የምታነድዱ፥ የእሳትንም ነበልባል ከፍ ያደረጋችሁ ሁላችሁ፥ በእሳታችሁ ብርሃንና ባነደዳችሁት ነበልባል ሂዱ፤ ስለ እኔ ይህ ይሆንባችኋል፤ በኀዘንም ትተኛላችሁ።'),
  ('5f05e640-514d-57ed-ade6-bfa8004cd805', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 1, 1, 'እናንተ ጽድቅን የምትከተሉ እግዚአብሔርንም የምትሹ፥ ስሙኝ፤ የተቈረጣችሁበትን ጽኑዕ ዓለት የተቈፈራችሁባትንም ጥልቅ ጕድጓድ ተመልከቱ።'),
  ('25dfed13-2afe-57dc-a0ac-abc74ed72e4f', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 2, 2, 'ወደ አባታችሁ ወደ አብርሃም፥ ወደ ወለደቻችሁም ወደ ሳራ ተመልከቱ፤ አንድ ብቻውን በሆነ ጊዜ ጠራሁት፤ ባረክሁትም፤ ወደድሁትም፤ አበዛሁትም።'),
  ('e9b53b32-a0ab-5203-a11f-3c9e3ab9d1fa', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 3, 3, 'ኢየሩሳሌም ሆይ፥ ደስ አሰኝሻለሁ፤ ባድማሽንም ሁሉ ደስ አሰኛለሁ፤ ምድረ በዳሽንም እንደ ዔድን፥ በረሃዎችሽንም እንደ እግዚአብሔር ገነት አደርጋለሁ። ደስታና ተድላ እምነትና የዝማሬ ድምፅ በውስጧ ይገኝባታል።'),
  ('7a95d7ce-2412-50c0-ac83-0ee1b55f8954', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 4, 4, 'ሕዝቤ ሆይ፥ ስሙኝ፤ ስሙኝ፤ እናንተም ነገሥታት ተግሣጼን አድምጡኝ፤ ሕግ ከእኔ ይወጣልና፥ ፍርዴም ለአሕዛብ ብርሃን ይሆናልና።'),
  ('965b3d3e-b7b8-5f14-aa23-64136d73385f', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 5, 5, 'ጽድቄ ፈጥና ትመጣለች፤ ማዳኔም እንደ ብርሃን ትደርሳለች፤ አሕዛብ በክንዴ ይታመናሉ፤ ደሴቶች እኔን ተስፋ ያደርጋሉ፤ በክንዴም ይታመናሉ።'),
  ('0965bc85-49db-53de-a1ae-e3037c1bcc5f', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 6, 6, 'ዐይኖቻችሁን ወደ ሰማይ አንሡ፤ ወደ ታችም ወደ ምድር ተመልከቱ፤ ሰማያት እንደ ጢስ በንነው ይጠፋሉ፤ ምድርም እንደ ልብስ ታረጃለች፤ የሚኖሩባትም እንዲሁ ይሞታሉ፤ ማዳኔም ለዘለዓለም ናት፤ ጽድቄም አታልቅም።'),
  ('9595df6c-4814-53ac-a214-60e38ad0dc93', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 7, 7, 'ፍርድን የምታውቁ፥ ሕጌም በልባችሁ ያለ ሕዝብ ሆይ፥ ስሙኝ፤ የሰዎችን ስድብና ማስፈራራት አትፍሩ፤ አትሸነፉም።'),
  ('068060c0-ee8b-5861-a182-0dd5bcf092f6', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 8, 8, 'እንደ ልብስ ፈጥነው ያረጃሉና አይቈዩም፤ ብል እንደ በላውም ይሆናሉ፤ ጽድቄ ግን ለዘለዓለም፥ ማዳኔም ለልጅ ልጅ ይሆናል።'),
  ('39fe1acc-e378-5857-a95e-e46ed06c999c', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 9, 9, 'ኢየሩሳሌም ሆይ፤ ተነሺ፤ ተነሺ፤ የክንድሽንም ኀይል ልበሺ፤ እንደ ቀድሞውም ዘመን እንደ ጥንቱ ትውልድ ተነሺ።'),
  ('ca55fabd-52c4-536c-a196-c474269a616f', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 10, 10, 'ባሕሩን ያደረቅሽ፥ ጥልቁንም ውኃ ያደረቅሽው፥ የዳኑትም ይሻገሩ ዘንድ ጥልቁን ባሕር ጥርጊያ ጎዳና ያደረግሽ አይደለሽምን?'),
  ('c2f9e03d-a83a-50fa-a2ce-5c0d5532a039', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 11, 11, 'እግዚአብሔርም የተቤዣቸው ይመለሳሉ፤ ወደ ጽዮንም በደስታና በሐሤት ይመጣሉ፤ የዘለዓለምም ክብር በራሳቸው ላይ ይሆናል፤ ደስታንና ተድላን ያገኛሉ፤ ኀዘንና ልቅሶም ይወገዳሉ።'),
  ('743a44d4-dec6-5bde-a259-f378f0b3acb1', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 12, 12, 'እኔ ነኝ፤ የማጽናናሽ እኔ ነኝ፤ አንቺ እንግዲህ ዕወቂ፤ ማንን ፈራሽ? የሚሞተውን ሰው እንደ ሣርም የሚጠወልገውን የሰው ልጅ ነውን?'),
  ('88f2318d-1c03-516a-ad73-a26b7c882bd7', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 13, 13, 'አንቺ ግን ሰማያትን የፈጠረውን፥ ምድርንም የመሠረታትን ፈጣሪሽን እግዚአብሔርን ረስተሻል፤ ያጠፋሽ ዘንድ ባዘጋጀ ጊዜ ከአስጨናቂው ቍጣ የተነሣ ሁልጊዜ ቀኑን ሁሉ ፈርተሻል፤ ይቈጣሽ ዘንድ መክሮአልና፤ አሁን የሚያስጨንቅሽ ቍጣው የት አለ?'),
  ('9db3cbe0-a096-53ac-a8aa-18ae7809abcb', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 14, 14, 'ከዳንሽ በኋላ እንግዲህ አይኖርምና፥ አይዘገይምምና።'),
  ('2dd82128-c5a1-5ff3-a8e4-e28e13ddc492', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 15, 15, 'ባሕርን የማናውጥ፥ ሞገዱም እንዲተምም የማደርግ አማላክሽ እግዚአብሔር እኔ ነኝና፥ ስሜም የሠራዊት ጌታ እግዚአብሔር ነው።'),
  ('ef40d5f5-394b-57f6-a8dc-8d13d10b9c5f', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 16, 16, 'ቃሌን በአፍሽ አደርጋለሁ፤ ሰማይን በዘረጋሁበትና ምድርን በመሠረትሁበት በእጄ ጥላ እጋርድሻለሁ፤ ጽዮንንም አንቺ ሕዝቤ ነሽ እላታለሁ።'),
  ('18187eac-14f8-581d-a4d9-8f24ed45ac5b', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 17, 17, 'ከእግዚአብሔር እጅ የቍጣውን ጽዋ የጠጣሽ ኢየሩሳሌም ሆይ፥ ተነሺ፤ ተነሺ፤ ቁሚ፤ የሚያንገደግድሽን የቍጣውን ጽዋ ጠጥተሻልና፥ ጨልጠሽውማልና።'),
  ('bfc273e2-0a9b-58c3-a6e1-74c546f91c12', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 18, 18, 'ከወለድሻቸው ልጆችሽ ሁሉ የሚያረጋጋሽ አጣሽ፤ ከአሳደግሻቸውም ልጆችሽ ሁሉ እጁን ሰጥቶ የሚያነሣሽ የለም።'),
  ('77462eb1-bc05-5191-a480-e10027522dac', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 19, 19, 'አሁንም እነዚህ ሁለቱ ይጠብቁሻል፤ ማን ያስተዛዝንሻል? እነርሱም ጥፋትና ውድቀት ራብና ሰይፍ ናቸው፤ እንግዲህ የሚያጽናናሽ ማን ነው?'),
  ('97ed8140-f97d-5bd5-a9b1-ab40e0d0a106', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 20, 20, 'ልጆችሽ ዝለዋል፤ እንደ ጠወለገ ቅጠልም በየመንገዱ ዳር ወድቀዋል፤ በአምላክሽ በእግዚአብሔር ቍጣና ተግሣጽ ተሞልተዋል።'),
  ('363fe5cf-b361-575e-a096-bd60712c9ae0', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 21, 21, 'ስለዚህም ያለ ወይን ጠጅ የሰከርሽ አንቺ የተዋረድሽ፥ ይህን ስሚ፤'),
  ('79f30fe9-05c8-54cd-aadb-b1d79384c4ab', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 22, 22, 'ለወገኑ የሚፈርድ አምላክሽ ጌታ እግዚአብሔር እንዲህ ይላል፥ “እነሆ፥ የሚያንገደግድሽን ጽዋ የቍጣዬንም ጽዋ ከእጅሽ ወስጃለሁ፤ ደግመሽም ከእንግዲህ ወዲህ አትጠጪውም።'),
  ('fd156e03-a423-52ae-a3a5-ead01b3e5593', '410aa488-bf7c-5fe6-a578-461d91b64926', 'fdaae51b-6ba8-540a-a0db-7c3b6d0a963a', 23, 23, 'ወደ በደሉሽና ወደ አጐሰቈሉሽ ሰዎች እጅ፥ ሰውነትሽንም ዝቅ በዪ፥ ድልድይ አድርገን እንሻገርብሽ ወደሚሏት ሰዎች እጅ እመልሰዋለሁ።” በምድርም ላይ በሆድሽ አስተኙሽ፤ መንገደኞችም ሁሉ ረገጡሽ።'),
  ('ec6aabaf-a412-5294-a26e-83c40d4363ef', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 1, 1, 'ጽዮን ሆይ፥ ተነሺ፥ ተነሺ፤ ጽዮን ሆይ፥ ኀይልሽን ልበሺ፤ አንቺም ቅድስቲቱ ከተማ ኢየሩሳሌም ሆይ፥ ያልተገረዘና ርኩስ ከእንግዲህ ወዲህ ወደ አንቺ አያልፍምና ክብርሽን ልበሺ።'),
  ('97cfcf01-63a1-55d9-ad91-a4ed1548b7c3', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 2, 2, 'ኢየሩሳሌም ሆይ፥ ትቢያን አራግፊ፤ ተነሺ፥ ተቀመጪ፤ ምርኮኛዪቱ የጽዮን ልጅ ሆይ፥ የአንገትሽን እስራት ፍቺ።'),
  ('02a47e7b-3497-5273-a5d4-8cbd85130157', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 3, 3, 'እግዚአብሔር እንዲህ ይላል፥ “በከንቱ ተሸጣችሁ ነበር፤ ያለ ወርቅም እቤዣችኋለሁ።”'),
  ('28448429-29c9-5130-a37f-8396a4fc6bb8', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 4, 4, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ሕዝቤ አስቀድሞ ወደ ግብፅ ወረዱ፤ በዚያም በስደት ኖሩ፤ ከዚያም ወደ አሦር በግድ ተወሰዱ።'),
  ('2781fbe8-1f94-5c26-aa44-0809292c73b5', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 5, 5, 'ሕዝቤ በከንቱ ተወስዶአልና አሁን ከዚህ ምን አቆማችሁ?” ይላል እግዚአብሔር፤ “ታደንቃላችሁ፤ ትጮሃላችሁም፥ ይላል እግዚአብሔር፤ ስሜም በእናንተ ምክንያት በአሕዛብ ዘንድ ሁልጊዜ ይሰደባል።'),
  ('253ab7ef-0cfe-55d6-af1d-3d4b6641a49e', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 6, 6, 'ስለዚህ ሕዝቤ ስሜን ያውቃል፤ የምናገርና ያለሁ እኔ እንደ ሆንሁ በዚያ ቀን ያውቃሉ።”'),
  ('789bfba3-ba40-52f3-a65c-9166056442c2', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 7, 7, 'ሰላምን የሚያወራ፥ መልካም የምሥራችንም የሚናገር፥ መድኀኒትንም የሚያወራ፥ ጽዮንንም፥ “አምላክሽ ነግሦአል” የሚል ሰው እግሩ በተራሮች ላይ እጅግ ያማረ ነው።'),
  ('48e250f7-c011-546f-a196-8c4769361b26', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 8, 8, 'እነሆ፥ የሚጠብቁሽ ሰዎች ድምፅ ከፍ ከፍ ይላልና፥ እግዚአብሔርም ጽዮንን ይቅር ባላት ጊዜ ዐይን በዐይን ይተያያሉና በአንድነት በቃላቸው ደስ ይላቸዋል።'),
  ('c27de0a6-5590-5524-a735-d074de7b127b', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 9, 9, 'የኢየሩሳሌም ፍርስራሾች ደስ ይበላቸው፤ እግዚአብሔር ይቅር ብሎ ኢየሩሳሌምን አድኖአታልና።'),
  ('956c26ea-bf77-5343-a9ef-bb1888151c91', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 10, 10, 'እግዚአብሔር የተቀደሰውን ክንዱን በአሕዛብ ሁሉ ፊት ገልጦአል፤ በምድር ዳርቻ የሚኖሩትም ሁሉ የአምላካችንን ማዳን ያያሉ።'),
  ('26ed4dd0-a259-51d3-ad7c-f04e808f9752', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 11, 11, 'እናንተ የእግዚአብሔርን ዕቃ የምትሸከሙ ሆይ፥ እልፍ በሉ፤ እልፍ በሉ፤ ከዚያ ውጡ፤ ርኩስን ነገር አትንኩ፤ ከመካከልዋ ውጡ፤ ራሳችሁን ለዩ።'),
  ('8ca2a2fd-5ab3-582f-ac6a-9ec58bcc34f6', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '8aaad50a-ddc9-5cad-a4ef-4bbc0dcb0ca8', 12, 12, 'እግዚአብሔር በፊታችሁ ይሄዳልና፥ የእስራኤልም አምላክ ይሰበስባችኋልና በችኮላ አትወጡም፤ በመኮብለልም አትሄዱም።'),
  ('77681025-9310-523b-a8bc-10161a77f55a', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '0a5dc19d-9379-5cff-af37-63fe08ce852e', 1, 13, 'እነሆ፥ አገልጋዬ ያስተውላል፤ ከፍ ከፍ ይላል፥ ይከብራልም፤ እጅግም ደስ ይለዋል።'),
  ('15d4f836-8cc6-5a4c-a118-dbdb38624c49', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '0a5dc19d-9379-5cff-af37-63fe08ce852e', 2, 14, 'ፊቱ ከሰዎች ሁሉ ይልቅ፥ መልኩም ከሰዎች ልጆች ይልቅ ያለ ክብር ነውና ብዙ ሰዎች ስለ እርሱ ያደንቃሉ፤'),
  ('b1e8dd81-5642-5d0f-a7c9-221c3fc7e05c', 'cf3a9334-a106-54e4-a9bc-62339ba1df77', '0a5dc19d-9379-5cff-af37-63fe08ce852e', 3, 15, 'ብዙዎች አሕዛብ እርሱን ያደንቃሉ፤ ነገሥታትም አፋቸውን ይዘጋሉ፤ ስለ እርሱ ያልተወራላቸው ያውቁታልና፥ ያልሰሙትም ያስተውሉታልና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('05789ac3-e275-5609-a6f7-6cd487422824', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 1, 1, 'ጌታ ሆይ፥ ነገራችንን ማን ያምነናል? የእግዚአብሔርስ ክንድ ለማን ተገልጦአል?'),
  ('1cb97fd2-f4af-5772-a2eb-8ee8e9717ecf', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 2, 2, 'ነገራችን በፊቱ እንደ ሕፃን፥ በደረቅ መሬትም እንዳለ ሥር ሆነ፤ መልክና ውበት የለውም፤ እነሆ፥ አየነው፤ ደም ግባት የለውም፤ ውበትም የለውም።'),
  ('c25918dd-553a-54b8-a80d-7e89725d78a5', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 3, 3, 'መልኩም የተናቀ፥ ከሰውም ልጆች ሁሉ የተዋረደ፥ የተገረፈ ሰው፥ መከራንም የተቀበለ ነው፤ ፊቱንም መልሶአልና አቃለሉት፥ አላከበሩትምም።'),
  ('dec0d227-1870-5519-aa4a-5db9ea5c8da6', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 4, 4, 'እርሱ ግን በእውነት ደዌያችንን ተቀበለ፤ ሕመማችንንም ተሸከመ፤ ስለ እኛም ታመመ፤ እኛም እንደ ታመመ፥ እንደ ተገረፈም ቈጠርነው።'),
  ('fcea274c-2fd8-5148-a6b6-15f746fb00ad', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 5, 5, 'እርሱ ግን ስለ ኀጢአታችን ቈሰለ፤ ስለ በደላችንም ታመመ፤ የሰላማችንም ተግሣጽ በእርሱ ላይ ነበረ፤ በእርሱም ቍስል እኛ ተፈወስን።'),
  ('47f46be2-283a-5569-a1c6-aef1d6e1c566', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 6, 6, 'እኛ ሁላችን እንደ በጎች ተቅበዝብዘን ጠፋን፤ ከእኛ እያንዳንዱ ወደ ገዛ መንገዱ አዘነበለ፤ እግዚአብሔርም ስለ ኀጢአታችን ለሞት አሳልፎ ሰጠው።'),
  ('4be71a09-7955-514c-a91c-6cd0834e8cf3', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 7, 7, 'እርሱ ግን በመከራው ጊዜ አፉን አልከፈተም፤ እንደ በግ ወደ መታረድ ተነዳ፤ የበግ ጠቦትም በሸላቾቹ ፊት ዝም እንደሚል፥ እንዲሁ አፉን አልከፈተም።'),
  ('7258ec60-4a1c-55f8-a2c8-8438fc937e42', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 8, 8, 'በውርደቱ ፍርዱ ተወገደ፤ ሕይወቱ ከምድር ተወግዷልና ልደቱን ማን ይናገራል? ስለ ሕዝቤ ኀጢአት ለሞት ደረሰ።'),
  ('dccc9c0a-70c5-5278-a9d9-f5ab1ce85ae9', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 9, 9, 'ክፉዎችንም ስለ መቃብሩ፥ ባለጸጎችንም ስለ ሞቱ እሰጣለሁ፤ ኀጢአትን አላደረገምና፥ ከአፉም ሐሰት አልተገኘበትምና።'),
  ('d964fdc8-e953-59b6-a0b7-5ce9ad961485', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 10, 10, 'እግዚአብሔር ከግርፋቱ ያነጻው ዘንድ ፈቀደ፤ ስለ ኀጢአት መሥዋዕትን ብታቀርቡ ሰውነታችሁ ረዥም ዕድሜ ያለውን ዘር ታያለች።'),
  ('ccb92ec7-900d-5d80-ae45-63d88d62746d', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 11, 11, 'እግዚአብሔርም ከሰውነቱ ሕማምን ያርቅ ዘንድ ይወዳል፤ ብርሃንንም ያሳየዋል፤ በጥበቡም ይለየዋል፤ ለጽድቅና ለበጎ ነገር የሚገዛውን ጻድቁን ያጸድቀዋል። የብዙዎችንም ኀጢአታቸውን እርሱ ይደመስሳል።'),
  ('66b7ba59-1bb5-5fb8-abc4-94e9a2a48730', '0a315205-5305-5477-a2e8-d4e655ff1b3c', '0b7a5f48-aee6-5062-ab79-be45be4a1209', 12, 12, 'ስለዚህም እርሱ ብዙዎችን ይወርሳል፤ ከኀያላንም ጋር ምርኮን ይከፋፈላል፤ ነፍሱን ለሞት አሳልፎ ሰጥቶአልና፥ ከዐመፀኞችም ጋር ተቈጥሮአልና፤ እርሱ ግን የብዙ ሰዎችን ኀጢአት ተሸከመ፤ ስለ ኀጢአታቸውም ተሰጠ።'),
  ('d3c02821-0020-52f8-a3c6-16c35c88fcbc', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 1, 1, 'አንቺ ያልወለድሽ መካን ሆይ፥ ደስ ይበልሽ፤ አንቺ ያላማጥሽ ሆይ፥ እልል በዪ፤ ጩኺም፤ ባል ካላት ይልቅ ፈት የሆነቺቱ ልጆች በዝተዋልና፥ ይላል እግዚአብሔር።'),
  ('84971b08-6b21-5fb6-ac22-f4e8a58661af', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 2, 2, 'የድንኳንሽን ስፍራ አስፊ፤ መጋረጃዎችሽንም ዘርጊ፤ አትቈጥቢ፤ አውታሮችሽን አስረዝሚ፤ ካስሞችሽንም ትከዪ።'),
  ('d40f3568-2368-51c6-a151-568c68d27767', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 3, 3, 'እንደ ገናምበቀኝና በግራ ተስፋፊ፤ ዘርሽ አሕዛብን ይወርሳሉና፥ የፈረሱትንም ከተሞች መኖሪያ ታደርጊያለሽና።'),
  ('f3a5be40-903b-5094-af05-2d521d0d1ff5', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 4, 4, 'አታፍሪምና አትፍሪ፤ አቷረጂምና አትደንግጪ፤ የዘለዓለም እፍረትሽንም ትረሺዋለሽ፤ የመበለትነትሽንም ስድብ ከእንግዲህ ወዲህ አታስቢም።'),
  ('d6d0efa5-5722-5b68-a32d-53e6ee4b64cb', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 5, 5, 'ፈጣሪሽ እግዚአብሔር ነው፤ ስሙም የሠራዊት ጌታ እግዚአብሔር ነው፤ የእስራኤልም አምላክ ታዳጊሽ ነው፤ እርሱም በምድር ሁሉ እንደዚሁ ይጠራል።'),
  ('b583b06c-2ff7-5180-abb0-4583a0793b07', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 6, 6, 'እግዚአብሔር እንደ ተተወችና እንደ ተበሳጨች፥ በልጅነቷም እንደ ተጠላች ሴት የጠራሽ አይደለም፥ ይላል አምላክሽ።'),
  ('5a17e239-7168-5317-a393-8102ebb0c2d2', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 7, 7, 'ጥቂት ጊዜ ተውሁሽ፤ በታላቅ ምሕረትም ይቅር እልሻለሁ።'),
  ('c48a3b2e-772f-5d72-a78f-59a7eb5d3e4d', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 8, 8, 'በጥቂት ቍጣ ፊቴን ከአንቺ ሰወርሁ፤ በዘለዓለም ቸርነት ይቅር እልሻለሁ፥ ይላል ታዳጊሽ እግዚአብሔር።'),
  ('8747339f-f907-565b-a265-47af2e17f4ba', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 9, 9, 'ከኖኅ ዘመን ውኃ ጀምሮ ይህ ለእኔ ምስክር ነው፤ ቀድሞ ከእንግዲህ ወዲህ ምድርን እንዳልቈጣት እንደ ማልሁ፥'),
  ('c80adc13-2af6-51c5-a2b7-6b851c16f214', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 10, 10, 'ተራሮችን እንዳልቀሥፋቸው እንዳላፈልሳቸውም፥ ኮረብቶችም እንዳይነዋወጡ እንደ ማልሁ እንዲሁ ከእኔ ዘንድ ያለሽ ይቅርታ አያልቅም፤ የሰላምሽ ቃል ኪዳንም አይጠፋም፤ መሓሪሽ እግዚአብሔር ይህን ተናግሮአልና።'),
  ('46bf5b84-5936-5a26-a1de-d1f72c1b8c6c', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 11, 11, 'አንቺ የተቸገርሽ የተናወጥሽ ያልተጽናናሽም፥ እነሆ፥ ድንጋዮችሽን የሚያበሩ አደርጋለሁ፤ መሠረትሽንም የሰንፔር አደርገዋለሁ።'),
  ('7209aa51-c7de-5ab4-a4e3-3151609a8184', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 12, 12, 'ግንብሽንም በቀይ ዕንቍ፥ በሮችሽንም ቢረሌ በተባለ ዕንቍ፥ ዳርቻዎችሽንም በከበረ ዕንቍ እሠራለሁ።'),
  ('7ea7e806-1664-53d9-a085-61ee3e26a31d', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 13, 13, 'ልጆችሽም ሁሉ ከእግዚአብሔር የተማሩ ይሆናሉ፤ ልጆችሽም በብዙ ሰላም ይኖራሉ።'),
  ('982dd789-40b4-5fea-af0a-9113d3330acc', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 14, 14, 'እነሆ፥ በጽድቅ ትታነጺያለሽ፤ ከግፍ ራቂ፤ አትፈሪም፤ ድንጋጤም ወደ አንቺ አይቀርብም።'),
  ('e056014d-3991-506b-a8e8-54fb1d12d8b4', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 15, 15, 'እነሆ፥ መጻተኞች በእኔ ወደ አንቺ ይመጣሉ፤ በአንቺም ይማጸናሉ።'),
  ('f40863a1-e84c-555a-a97a-26725d62740e', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 16, 16, 'እነሆ፥ ፍሙን በወናፍ እንደሚያናፋ፥ ለሥራውም መሣሪያ እንደሚያወጣ ብረት ሠሪ የፈጠርሁሽ አይደለም፤ እኔ ግን ለመልካም ፈጠርሁሽ እንጂ ለጥፋት አይደለም።'),
  ('fbd7b1c7-e30d-5d1d-a4a4-bd9fdc45c04a', 'e001bf33-f934-59d6-af54-59abacdf5974', '0d018221-02d4-5823-a472-2ffeae216bf5', 17, 17, 'በአንቺ ላይ የተሠራ መሣሪያ ሁሉ እንዲከናወን አላደርግም፤ በአንቺ ላይ ለፍርድ የሚነሣውን ድምፅ ሁሉ ታጠፊያለሽ፤ ጠላቶችሽም ሁሉ ይፈረድባቸዋል፤ እግዚአብሔርንም ለሚያገለግሉ ርስት አላቸው፤ ጻድቃኔም ትሆኑኛላችሁ ይላል እግዚአብሔር።'),
  ('25ef7a15-064f-51b0-af0a-d86e8243528e', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 1, 1, 'እናንተ የተጠማችሁ ሁሉ፥ ወደ ውኃ ሂዱ፤ ገንዘብም የሌላችሁ ሂዱና ግዙ፤ ብሉ፤ ያለ ገንዘብም ያለ ዋጋም የወይን ጠጅና ወተት ጠጡ።'),
  ('0ef23007-b9f1-5db6-a727-19cf5a5cf248', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 2, 2, 'ገንዘብን እንጀራ ላይደለ፥ የድካማችሁንም ዋጋ ለማያጠግብ ነገር ለምን ትመዝናላችሁ? አድምጡኝ፤ በረከትንም ብሉ፤ ሰውነታችሁም በበረከት ደስ ይበለው።'),
  ('c563aa3f-7589-5fdf-a367-517e0e58efc7', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 3, 3, 'ስሙኝ፤ ጎዳናዬን ተከተሉ፤ አድምጡኝም፤ ሰውነታችሁም በበረከት ትኖራለች፤ የታመነችዪቱን የዳዊትን ምሕረት፥ የዘለዓለምን ቃል ኪዳን ከእናንተ ጋር አደርጋለሁ።'),
  ('8c65340c-4dea-585e-a15b-d33a317f0c14', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 4, 4, 'እነሆ፥ ለአሕዛብ ምስክር፥ ለወገኖችም አለቃና አዛዥ እንዲሆን አደረግሁት።'),
  ('219be74b-2512-5c52-ac91-6b9c4eaabed3', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 5, 5, 'እነሆ፥ የማያውቁህ ሕዝብ ይጠሩሃል፤ የእስራኤል ቅዱስ አክብሮሃልና ስለ አምላክህ ስለ እግዚአብሔር የማያውቁህ ሕዝብ በአንተ ይማጠናሉ።'),
  ('f1733afa-33d7-5cf0-a052-31ce2e49d0ae', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 6, 6, 'እግዚአብሔር በሚገኝበት ጊዜ ፈልጉት፤ ቀርቦም ሳለ ጥሩት፤'),
  ('c13e5d60-8cb4-5101-ab9a-f07324fe83db', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 7, 7, 'ክፉ ሰው መንገዱን፥ በደለኛም ዐሳቡን ይተው፤ ወደ እግዚአብሔርም ይመለስ፤ እርሱም ይምረዋል፤ እርሱ ብዙ በደላችሁን ይተውላችኋልና።'),
  ('db2d6771-cb80-5095-a18b-42ba901c644e', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 8, 8, 'ዐሳቤ እንደ ዐሳባችሁ፥ መንገዴም እንደ መንገዳችሁ አይደለምና፥ ይላል እግዚአብሔር።'),
  ('8e1005b6-a236-5b27-a278-bc934fd342cb', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 9, 9, 'ሰማይ ከምድር እንደሚርቅ፥ እንዲሁ መንገዴ ከመንገዳችሁ፥ ዐሳቤም ከዐሳባችሁ የራቀ ነው።'),
  ('d623eb7f-1b59-5467-a601-5b62df3a9a65', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 10, 10, 'ብዙ ዝናምና በረዶ ከሰማይ እንደሚወርድ፥ ምድርን እንደሚያረካት፥ ታበቅልና ታፈራም ዘንድ እንደሚያደርጋት፥ ዘርን ለሚዘራ፥ እህልንም ለምግብ እንደሚሰጥ እንጂ ወደ ሰማይ እንደማይመለስ፥'),
  ('cb5b81f0-d9f4-581b-aef2-92916a4d3e79', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 11, 11, 'ከአፌ የሚወጣ ቃሌ እንዲሁ ነው፤ የምሻውን እስኪያደርግ ድረስ ወደ እኔ በከንቱ አይመለስም፤ መንገዴንና ትእዛዜን አከናውናለሁ።'),
  ('a6b870d1-acc9-5b02-a57d-c4478dc08913', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 12, 12, 'እናንተም በደስታ ትወጣላችሁ፤ በሐሤትም ትማራላችሁ፤ ተራሮችና ኮረብቶች በደስታ ሊቀበሏችሁ ይዘላሉ፤ የሜዳም ዛፎች ሁሉ በቅርንጫፎቻቸው ያጨበጭባሉ።'),
  ('20ec638c-5830-52bf-a641-1168da8f9a7c', 'e0326975-c3a5-54f4-ad3b-8575fd162004', '18467327-613d-5d8c-af40-6220292385f8', 13, 13, 'በእሾህም ፋንታ ጥድ፥ በኵርንችትም ፋንታ ባርሰነት ይበቅላል፤ የእግዚአብሔርም ስም ለዘለዓለም በማይጠፋ ምልክት ይመሰገናል።'),
  ('f76850c0-30cd-5c52-a9d3-23173f3f9f02', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 1, 1, 'እግዚአብሔር እንዲህ ይላል፥ “ማዳኔ ሊመጣ ምሕረቴም ሊገለጥ ቀርቦአልና ፍርድን ጠብቁ፤ ጽድቅንም አድርጉ።'),
  ('c9c18afe-8660-5286-a341-6ffb56a5f954', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 2, 2, 'ይህን የሚያደርግ በእርሱም ጸንቶ የሚኖር፥ ሰንበታትንም የሚጠብቅና የማያረክስ፥ እጁንም ክፋት ከማድረግ የሚጠብቅ ሰው ብፁዕ ነው።”'),
  ('07bc8582-e64a-550b-a78d-d55eea296666', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 3, 3, 'ወደ እግዚአብሔርም የተጠጋ መጻተኛ፥ “በእውነት እግዚአብሔር ከሕዝቡ ይለየኛል” አይበል፤ ጃንደረባም፥ “እነሆ፥ እኔ እንደ ደረቀ ዛፍ ነኝ” አይበል።'),
  ('032fd622-ffef-5b7c-a4e3-d4a8823a84e8', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 4, 4, 'እግዚአብሔር ለጃንደረቦች እንዲህ ይላል፥ “ሰንበቴን ቢጠብቁ ደስ የሚያሰኘኝንም ነገር ቢመርጡ፥ በቃል ኪዳኔም ጸንተው ቢኖሩ፥'),
  ('3a4aa27d-a955-5aba-a052-3f1447986ff5', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 5, 5, 'በቤቴና በቅጥሬ ውስጥ ከወንዶችና ከሴቶች ልጆች ይልቅ የሚበልጥ ስም የሚያስጠራ ቦታን እሰጣቸዋለሁ፤ የማይጠፋ የዘለዓለም ስምንም እሰጣቸዋለሁ።”'),
  ('2ee1d1fc-d006-5714-ad6f-9d780a67ae83', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 6, 6, 'ከሌላም ሕዝብ ወደ እግዚአብሔር የተመለሱትን ለእርሱም ባሪያዎች የሆኑትን፥ የእግዚአብሔርንም ስም የወደዱትን፥ ወንዶችና ሴቶች ባሪያዎቹ የሆኑትን፥ “ሰንበታቴን የሚጠብቁትንና የማያረክሱትን፥ በቃል ኪዳኔም ጸንተው የሚኖሩትን ሁሉ፥'),
  ('f35dae1f-2d28-5ba7-af0d-8a4e21ad8b3c', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 7, 7, 'ወደ ተቀደሰ ተራራዬ አመጣቸዋለሁ፤ በጸሎቴም ቤት ደስ አሰኛቸዋለሁ፤ ቤቴ ለአሕዛብ ሁሉ የሚሆን የጸሎት ቤት ይባላልና፥ የሚቃጠለው መሥዋዕታቸውና ቍርባናቸውም በመሠዊያዬ ላይ የተመረጠ ይሆናል።'),
  ('6c7c7789-b452-5657-abff-6c6ace67fc48', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 8, 8, 'ከእስራኤል የተበተኑትን የሚሰበስብ ጌታ እግዚአብሔር፦ ወደ ተሰበሰቡት ሌሎችን እሰበስብለታለሁ” ይላል።'),
  ('9ddc72b5-f30a-5d04-a824-403a9d06bbeb', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 9, 9, 'እናንተ የምድረ በዳ አራዊት ሁሉ ኑ፤ እናንተ የዱር አራዊት ሁሉ ብሉ።'),
  ('797cba2f-f003-533f-a8bd-4fc06231b435', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 10, 10, 'ሁሉም ዕውራን እንደ ሆኑ ኑና እዩ፤ ሁሉ ያለ ዕውቀት ናቸው፤ ሁሉም ዲዳ የሆኑ ውሾች ናቸው፤ ይጮኹም ዘንድ አይችሉም፤ በመኝታቸውም ሕልምን ያልማሉ፤ ማንቀላፋትንም ይወድዳሉ።'),
  ('3e8319e7-80b1-58b2-a0b8-96b5dbfedfa5', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 11, 11, 'ሁሉም ከቶ የማይጠግቡ የረከሱ ውሾች ናቸው፤ እነርሱም ያስተውሉ ዘንድ የማይችሉ ክፉዎች ናቸው፤ ሁሉም እያንዳንዳቸው እንደ ፈቃዳቸው መንገዳቸውን ተከትለዋል።'),
  ('91cdff1b-ef86-52b4-a028-759a8a36db6a', '6b584f0e-b5f9-5380-ad8a-bea527b1ba12', 'd2037533-34fa-5ba7-a52e-ba2edea0438d', 12, 12, 'ኑ፤ የወይን ጠጅ እንውሰድ፤ በሚያሰክርም መጠጥ እንርካ፤ ዛሬም እንደ ሆነ እንዲሁ ነገ ይሆናል፤ ከዛሬም ይልቅ እጅግ ይበልጣል ይላሉ።'),
  ('3b7493d6-6ce2-5825-a9ab-b2e83132df42', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 1, 1, 'ጻድቅ ሰው እንደጠፋ አያችሁ፤ ይህንም በልባችሁ አላሰባችሁም፤ ጻድቃን ሰዎች ይወገዳሉ፤ ጻድቅም ከክፋት ፊት እንደ ተወገደ ማንም አያስተውልም።'),
  ('2662cd44-4ce5-5e63-abe3-333bb754e6ae', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 2, 2, 'መቃብሩ በሰላም ይሆናል፤ ከመካከልም ይወሰዳል።'),
  ('f07d950f-84b5-5859-afce-0fde7282544a', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 3, 3, 'እናንተ የኃጥኣን ልጆች፥ የዘማውያንና የጋለሞታዪቱ ዘር፥ ወደዚህ ቅረቡ።'),
  ('93ef6bde-f56d-59fc-a3cd-b8ba0efd232d', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 4, 4, 'በማን ታላግጣላችሁ? በማንስ ላይ አፋችሁን ታላቅቃላችሁ? ምላሳችሁንስ በማን ላይ ታስረዝማላችሁ?'),
  ('dec02f47-1209-53ed-a6af-d282153bc00b', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 5, 5, 'እናንተ በለመለመ ዛፍ ሁሉ በታች በጣዖት ደስ የምትሰኙ፥ እናንተም በሸለቆች ውስጥ በዓለትም ስንጣቂዎች በታች ልጆቻችሁን የምትሠዉ፥ እናንተ የጥፋት ልጆችና የዐመፀኞች ዘሮች አይደላችሁምን?'),
  ('a3e582ad-5a86-57c7-a01b-e831f89b4428', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 6, 6, 'በሸለቆ ውስጥ ያሉ የለዘቡ ድንጋዮች ዕድል ፋንታሽ ናቸው፤ እነርሱም ዕጣሽ ናቸው፤ ለእነርሱም የመጠጥ ቍርባን አፍስሰሻል፤ የእህልንም ቍርባን አቅርበሻል። እንግዲህ በዚህ ነገር አልቈጣምን?'),
  ('ca6641d8-61af-56af-aa48-09c3a249fe60', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 7, 7, 'ከፍ ባለውና በረዘመውም ተራራ ላይ መኝታሽን አደረግሽ፤ በዚያም መሥዋዕትሽን ሠዋሽ።'),
  ('088a7b9f-32f7-5120-ae59-db2ae3934031', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 8, 8, 'ከመዝጊያው በኋላ መታሰቢያሽን አደረግሽ፤ እኔን ብትተዪ የሚጠቅምሽ መሰለሽን? ከእኔም ይልቅ ከአንቺ ጋራ የሚተኙትን መረጥሽ።'),
  ('d3dd563b-5667-5bd4-a549-beb9c84e465a', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 9, 9, 'ዝሙትሽን ከእነርሱ ጋር አበዛሽ፤ ከአንቺ የራቁ ብዙዎችንም ተጐዳኘሽ። መልእክተኞችሽንም ወደ ሩቅ ላክሽ፤ ከእነርሱም ጋር ተወገድሽ፤ እስከ ሲኦልም ድረስ ተዋረድሽ።'),
  ('cafc48cb-aa81-52a6-a367-aa1d2ad6d608', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 10, 10, 'በመንገድሽም ብዛት ደከምሽ፤ ዳግመኛም ጕልበት እያለኝ ከእንግዲህ ወዲህ ይህን መንገድ አልተውም አላልሽም፤ ይህንም ስላደረግሽ አላፈርሽም።'),
  ('9dbe1a45-b168-571f-a587-f9eb7e72836a', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 11, 11, 'ሐሰት የተናገርሽው፥ እኔንም ያላሰብሽው፥ በልብሽም ነገሩን ያላኖርሽው ማንን ሰግተሽ ነው? ማንንስ ፈርተሽ ነው? እኔም ዝም አልሁሽ፤ አንቺም አልፈራሽኝም።'),
  ('171aeb6e-60a1-5d29-a098-fae92835f691', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 12, 12, 'እንግዲህ እኔ ጽድቄንና የማይረባሽን የአንቺን በደል እናገራለሁ።'),
  ('59644a13-a816-5988-ae06-8dd0fcd47d7a', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 13, 13, 'በችግርሽ ቀን በጮኽሽ ጊዜ እስኪ ይታደጉሽ፤ እነሆ፥ ዐውሎ ይወስዳቸዋል፤ ነፋስም ሁሉን ያስወግዳቸዋል። ወደ እኔ የሚጠጉ ግን ምድሪቱን ይገዛሉ፤ የተቀደሰውን ተራራዬንም ይወርሳሉ።'),
  ('e35f53aa-c90f-5f73-a734-84f5117c7ba9', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 14, 14, 'እርሱም፥ “በፊቱ፥ መንገድን ጥረጉ፤ ከሕዝቤም መንገድ ዕንቅፋትን አስወግዱ” ይላል።'),
  ('26359205-190f-5a11-a913-9352a62840b2', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 15, 15, 'ለዘለዓለም በአርያም የሚኖር ስሙም ቅዱሰ ቅዱሳን የሆነ፥ በቅዱሳን አድሮ የሚኖር፥ ለተዋረዱት ትዕግሥትን የሚሰጥ፥ ልባቸውም ለተቀጠቀጠ ሕይወትን የሚሰጥ ልዑል እግዚአብሔር እንዲህ ይላል፦'),
  ('2a384141-4e21-5d64-a53a-0da3a9fcc68c', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 16, 16, '“መንፈስ ከእኔ ይወጣልና፥ የሁሉንም ነፍስ ፈጥሬአለሁና ለዘለዓለም አልቀስፋችሁም፤ ሁልጊዜም አልቈጣችሁም።'),
  ('9e241224-9741-5fdd-ab8b-4a952656ba60', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 17, 17, 'ስለ ኀጢአቱ ጥቂት ጊዜ መከራ አመጣሁበት፤ ቀሠፍሁትም፤ ፊቴንም ከእርሱ መለስሁ፤ እርሱም አዘነ። እያዘነም ሄደ።'),
  ('470e0f97-33c9-5bad-a0b6-d930abc45dc2', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 18, 18, 'ከዚህም በኋላ መንገዱን አይቻለሁ፤ ፈወስሁትም፤ አጽናናሁት፤ እውነተኛ ደስታንም ሰጠሁት።'),
  ('55aeaec6-80af-502b-a685-5e1309ed4587', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 19, 19, 'በሩቅም በቅርብም ላሉ በሰላም ላይ ሰላም ይሁን፤ እፈውሳቸውማለሁ፥ ይላል እግዚአብሔር።'),
  ('b5412db7-3fb8-5292-a765-b89a1350577f', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 20, 20, '“ኃጥኣን ግን እንዲህ ይገለበጣሉ፤ ዕረፍትንም አያገኙም።'),
  ('b07d7362-ca00-5146-af98-281802a4c9c4', 'dfb031b3-2b82-52d7-a1ad-46740205950b', 'bd6c8070-5b3a-5d43-a3b9-9b4d4d688e35', 21, 21, 'ለኃጥአን ደስታ የላቸውም” ይላል እግዚአብሔር።'),
  ('815eeed2-7a3d-57c7-a545-3e6bd93ff1ba', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 1, 1, 'በኀይልህ ጩኽ፤ አትቈጥብ፤ ድምፅህን እንደ መለከት አንሣ፤ ለሕዝቤ ኀጢአታቸውን፥ ለያዕቆብ ቤትም በደላቸውን ንገር።'),
  ('3edf5c94-fc4b-56a6-a194-d90d918fa487', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 2, 2, 'ነገር ግን ጽድቅን እንደሚያደርግ የአምላኩንም ፍርድ እንደማይተው ሕዝብ ዕለት ዕለት ይሹኛል፤ መንገዴንም ያውቁ ዘንድ ይወድዳሉ። አሁንም እውነተኛውን ፍርድ ይለምኑኛል፤ ወደ እግዚአብሔርም ለመቅረብ ይወድዳሉ።'),
  ('a94cbe89-9690-5e07-a525-ea31551c3db1', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 3, 3, '“ስለ ምን ጾምን፥ አንተም አልተመለከትኸንም? ሰውነታችንንስ ስለ ምን አዋረድን፥ አንተም አላወቅኸንም?” ይላሉ። እነሆ፥ በጾማችሁ ቀን ፈቃዳችሁን ታደርጋላችሁ፥ ሠራተኞቻችሁንም ሁሉ ታስጨንቃላችሁ።'),
  ('a52e557f-1517-56b2-a61d-ef957649cb00', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 4, 4, 'እነሆ፥ ለጠብና ለክርክር ትጾማላችሁ፤ ድሃውንም በጡጫ ትማታላችሁ፤ በምትጮኹበት ጊዜ ድምፃችሁ እንዲሰማ ለእኔ ትጾማላችሁን? ድምፃችሁንም ወደ ላይ ታሰሙ ዘንድ ዛሬ እንደምትጾሙት አትጾሙም።'),
  ('06697c3b-28c9-5bad-a7fc-b0cd752b59c8', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 5, 5, 'እኔ ይህን ጾም የመረጥሁ አይደለሁም፤ እንደዚችም ባለች ቀን ሰው ራሱን ቢያሳዝን፥ አንገቱንም እንደ ቀለበት ቢያቀጥን፥ ማቅ ለብሶ በአመድ ላይ ቢተኛም፥ ይህ ጾም በእግዚአብሔር ዘንድ የተመረጠ አይደለም።'),
  ('385b8264-9555-58d7-a9ed-cbec35964416', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 6, 6, 'ይህን ጾም የመረጥሁ አይደለም ይላል እግዚአብሔር፤ ነገር ግን የበደልን እስራት ፍታ፤ ጠማማውን ሁሉ አቅና፤ የተጨነቀውንም ሁሉ አድን፤ የዐመፃ ደብዳቤንም ተው።'),
  ('e5feb5bb-82cd-5888-ab75-c92f1dd03df0', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 7, 7, 'ለተራበውም እንጀራህን አጥግበው፤ ድሆችን ወደ ቤትህ አስገብተህ አሳድራቸው፤ የተራቈተውንም ብታይ አልብሰው፤ ከሥጋ ዘመድህ አትሸሽግ።'),
  ('ace72489-df36-5d5a-aeb8-7809fb714c29', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 8, 8, 'ያን ጊዜ ብርሃንህ እንደ ንጋት ይበራል፤ ፈውስህም ፈጥኖ ይወጣል፤ ጽድቅህም በፊትህ ይሄዳል፤ የእግዚአብሔርም ክብር ይጋርድሃል።'),
  ('afe35ad2-502e-57b9-a7bd-373c4c36eda8', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 9, 9, 'ያን ጊዜ ትጠራለህ እግዚአብሔርም ይሰማሃል፤ ትጮኻለህ፤ እርሱም፦ እነሆኝ፥ ይልሃል። የዐመፅ እስራትን ከመካከልህ ብታርቅ፥ ጣትህንም መጥቀስ ማንጐራጐርንም ብትተው፥'),
  ('f93c1d6f-e940-5297-abf4-e8f33f791c16', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 10, 10, 'ከምግብህም ለተራበ ብታካፍል፥ የተራበች ሰውነትንም ብታጠግብ፥ ያንጊዜ ብርሃንህ በጨለማ ይወጣል፤ ጨለማህም እንደ ቀትር ይሆናል።'),
  ('ae8d5bfb-819b-5b12-af7c-515def34807e', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 11, 11, 'እግዚአብሔርም ሁልጊዜ ከአንተ ጋር ይኖራል፤ እንደ ነፍስህም ፍላጎት ያጠግብሃል፤ አጥንትህንም ያለመልማል፤ አንተም እንደሚጠጣ ገነት፥ ውኃውም እንደማያቋርጥ ምንጭ ትሆናለህ።'),
  ('a0ba8027-8a9e-5846-ab76-0c06b1c8b8d5', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 12, 12, 'ከድሮ ዘመን የፈረሱት ስፍራዎችህ ይሠራሉ፤ መሠረትህም ለልጅ ልጅ ዘመን ይሆናል፤ አንተም፦ ሰባራውን ጠጋኝ፥ የመኖሪያ መንገድንም አዳሽ ትባላለህ።'),
  ('cff6afd0-7b61-5c78-a3a3-8729eba70e30', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 13, 13, 'ፈቃድህን በተቀደሰው ቀኔ ከማድረግ እግርህን ከሰንበት ብትመልስ፥ ሰንበትንም ደስታ፥ ለእግዚአብሔርም የተቀደሰ ብታደርገው፥ ክፉ ሥራን ለመሥራት እግርህን ባታነሣ፥ በአፍህም ክፉ ነገርን ባትናገር፥'),
  ('088d3aae-e458-56fb-abb0-b8b1ced7e343', 'e40e4353-2b3d-58fd-ae73-80a7bfd24920', 'ac1919de-e749-5b52-a6f4-60eec02a5913', 14, 14, 'በዚያን ጊዜ በእግዚአብሔር ትታመናለህ፤ በምድርም በረከት ላይ ያወጣሃል፤ የአባትህ የያዕቆብንም ርስት ይመግብሃል፤ የእግዚአብሔር አፍ እንደዚህ ተናግሮአልና።'),
  ('d39dfe27-1857-5fbd-abed-2bb9dc65a4dc', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 1, 1, 'በውኑ፥ የእግዚአብሔር እጅ ማዳን አትችልምን? ጆሮውስ አይሰማምን?'),
  ('c4d777d7-e09c-53b2-a6eb-9c0f9638b426', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 2, 2, 'ነገር ግን በደላችሁ በእናንተና በእግዚአብሔር መካከል ለይታለች፤ ይቅርም እንዳይላችሁ ኀጢአታችሁ ፊቱን ከእናንተ ሰውሮታል።'),
  ('920af38f-cfc9-56e5-ac65-6f7b9c80b99c', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 3, 3, 'እጃችሁ በደም ጣታችሁም በኀጢአት ተሞልትዋል፤ ከንፈራችሁም ዐመፅን ተናግሮአል፤ ምላሳችሁም ኀጢአትን አሰምቶአል።'),
  ('4e12ab04-9f63-52a9-a30e-804fd009cdfe', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 4, 4, 'ጽድቅን የሚናገር በእውነትም የሚፈርድ የለም፤ በከንቱ ነገር ታምነዋል፤ የማይጠቅማቸውንም ተናግረዋል፤ ኀጢአትን ፀንሰዋል፤ በደልንም ወልደዋል።'),
  ('5f6fc0bc-5ecc-5a59-aee5-a6a965de6942', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 5, 5, 'የእባብን ዕንቍላል ቀፈቀፉ፤ የሸረሪትንም ድር አደሩ፤ እንቁላላቸውንም የሚበላ ሰው ፈጥኖ ይሞታል፤ እንቍላሉም ሲሰበር እባብ ይወጣል።'),
  ('165af48d-4d86-504d-a761-32871fc5a9e2', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 6, 6, 'የሸረሪቶች ድር ልብስ አይሆንም፤ በሥራቸውም ራሳቸውን አያለብሱም፤ ሥራቸው የግፍ ሥራ ነውና።'),
  ('613f4408-f921-5c49-a38e-e7018bdce651', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 7, 7, 'እግሮቻቸውም ለተንኮል ይሮጣሉ፤ ደምን ለማፍሰስም ይፈጥናሉ፤ ሰውን ለመግደል ይመክራሉ፤ ጕስቍልናና ቅጥቃጤ በመንገዳቸው አለ።'),
  ('4c2ad41e-2f6c-5afd-a415-368b7ecd11ef', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 8, 8, 'የሰላምን መንገድ አያውቁም፤ በመንገዳቸውም ፍርድ የለም፤ የሚሄዱበትም መንገድ ጠማማ ነው፤ ሰላምንም አያውቁም።'),
  ('b6ce9326-9abf-50ae-a5cf-7fa493669ae2', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 9, 9, 'ስለዚህ ፍርድ ከእነርሱ ዘንድ ርቆአል፤ ጽድቅም አላገኛቸውም፤ ብርሃንን ሲጠባበቁ ብርሃናቸው ጨለማ ሆነባቸው፤ ብርሃንንም ሲጠባበቁ በጨለማ ሄዱ፤'),
  ('f37b9179-8f6e-5c47-aa67-e4d9297600f1', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 10, 10, 'እንደ ዕውሮች ወደ ቅጥሩ ተርመሰመሱ፤ ዐይንም እንደሌላቸው ተርመሰመሱ፤ በቀትርም ጊዜ በመንፈቀ ሌሊት እንዳለ ሰው ተሰናከሉ፤ እንደ ሙታንም ይጨነቃሉ።'),
  ('4b8b0291-21eb-58a9-af04-8a8fe065d8be', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 11, 11, 'እንደ ድብና እንደ ርግብ በአንድነት ይሄዳሉ፤ ፍርድን እንጠባበቅ ነበር፤ መዳንም የለም፤ ከእኛም ርቆአል።'),
  ('95da6541-3b76-56a1-a3df-7faaaaed2c2c', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 12, 12, 'ዐመፃችን በአንተ ፊት በዝቶአልና፥ ኀጢአታችንም መስክሮብናልና፥ ዐመፃችን ከእኛ ጋር ነውና፥ ጽድቅንም አላወቅንምና።'),
  ('a93fe906-dff6-53ed-aa87-3547c80d9bad', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 13, 13, 'በድለናል፤ ዋሽተናልም፤ አምላካችንንም መከተል ትተናል፤ ዐመፃን ተናግረናል፤ ከድተንሃልም፤ የኀጢአትንም ቃል ፀንሰን፤ ከልብ አውጥተናል።'),
  ('2130cad2-6708-572d-aeda-0d65991a29b7', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 14, 14, 'ፍርድን ከመከተል ወደ ኋላ ርቀናል፤ ጽድቅም በሩቅ ቆሞአል፤ እውነትም ከመንገዳቸው ታጥቶአል፤ በቀና መንገድም መሄድ አልቻሉም።'),
  ('817aff83-96d4-5d33-a100-5f09ef8f2fe6', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 15, 15, 'ከእውነት ተወግደዋል፤ እንዳያስተውሉም ልባቸውን መልሰዋል። እግዚአብሔርም አየ፤ ፍርድም ስለሌለ ደስ አላለውም።'),
  ('df8d1af0-6970-5023-ac3d-2b1ab5d7a424', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 16, 16, 'ሰውም እንደሌለ አየ፤ የሚረዳም ሰው እንደሌለ ተረዳ፤ ሰለዚህ በክንዱ ደገፋቸው፤ በይቅርታውም አጸናቸው።'),
  ('6fb13f46-8edf-565d-aed2-a18d86e7dc7d', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 17, 17, 'ጽድቅንም እንደ ጥሩር ለበሰ፤ በራሱም ላይ የማዳንን ራስ ቍር አደረገ፤ የበቀልንም ልብስ ለበሰ።'),
  ('076a98d7-306d-5598-a488-c4e8fe03db3d', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 18, 18, 'ጠላቶቹንም ያዋርዳቸው ዘንድ የበቀልና የፍዳን መጐናጸፊያ ተጐናጸፈ።'),
  ('80f15021-f5d9-5dce-a475-06487a3e42c6', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 19, 19, 'በምዕራብ ያሉት የእግዚአብሔርን ስም፥ በፀሐይ መውጫም ያሉት ክብሩን ይፈራሉ። መቅሠፍትም ከእግዚአብሔር ዘንድ እንደ ኀይለኛ ፈሳሽ በቍጣ ይመጣል።'),
  ('3892cea1-78ab-5503-ae93-fa6da85774d8', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 20, 20, 'ከጽዮን ታዳጊ ይመጣል፤ ከያዕቆብም ኀጢአትን ያርቃል።'),
  ('1cc5ea9f-9772-533c-a96b-1bda0605abb5', 'b3dc0af4-3019-5d35-a082-eda35a98c74d', '99ae234c-2a4d-517d-a998-a99accc60ad5', 21, 21, '“ከእነርሱ ጋር ያለው ቃል ኪዳኔ ይህ ነው” ይላል እግዚአብሔር፤ “በአንተ ላይ ያለው መንፈሴ በአፍህም ውስጥ ያደረግሁት ቃሌ ከዛሬ ጀምሮ እስከ ዘለዓለም ድረስ ከአፍህ፥ ከዘርህም አፍ፥ ከዘር ዘርህም አፍ አይጠፋም፥” ይላል እግዚአብሔር።'),
  ('cb4a28e3-5d44-5f8b-a83a-183f13efd4c9', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 1, 1, 'ኢየሩሳሌም ሆይ፥ ብርሃንሽ መጥቶአልና፥ የእግዚአብሔርም ብርሃን በአንቺ ላይ ወጥቶአልና አብሪ፤ አብሪ።'),
  ('0fef8ba3-c598-5ae3-a268-cc19a90bcc0d', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 2, 2, 'እነሆ፥ ጨለማ ምድርን፥ ድቅድቅ ጨለማም አሕዛብን ይሸፍናል፤ ነገር ግን በአንቺ ላይ እግዚአብሔር ይገለጣል፤ ክብሩም በአንቺ ላይ ይታያል፤'),
  ('876764ef-d418-5372-a834-cd97865767ac', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 3, 3, 'ነገሥታት በብርሃንሽ፥ አሕዛብም በፀዳልሽ ይሄዳሉ።'),
  ('7d0f79ef-25d2-5dde-a6f5-b22711f3909d', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 4, 4, 'ዐይኖችሽን አንሥተሽ በዙሪያሽ ተመልከቺ፤ ልጆችሽም እንደ ተሰበሰቡ እነሆ፥ እዪ፤ ወንዶች ልጆችሽ ከሩቅ ይመጣሉ፤ ሴቶች ልጆችሽንም በጫንቃ ላይ ይሸከሙአቸዋል።'),
  ('9739e25f-ab4b-55e1-a845-bd9651e192bd', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 5, 5, 'በዚያ ጊዜ አይተሽ ትፈሪያለሽ፤ የአሕዛብና የሀገሮች ብልጽግና ወደ አንቺ ይመለሳልና፥ ልብሽ ይደነግጣል።'),
  ('b6d0fee9-77fa-5e8d-ae37-e49d683cb1ac', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 6, 6, 'የግመሎች መንጋ ወደ አንቺ ይመጣሉ፤ የምድያምና የኤፋ ግመሎች ይሸፍኑሻል፤ ሁሉ ከሳባ ወርቅንና ዕጣንን ይዘው ይመጣሉ፤ የእግዚአብሔርንም ማዳን ያበሥራሉ።'),
  ('f6801ae7-f1b3-516b-a612-485d0d6dd206', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 7, 7, 'የቄዳር በጎች ሁሉ ወደ አንቺ ይሰበሰባሉ፤ የነባዮትም አውራ በጎች ወደ አንቺ ይመጣሉ፤ በመሠዊያዬ ላይም የተመረጠው መሥዋዕት ይቀርባል፤ የጸሎቴ ቤትም ይከብራል።'),
  ('335e6d00-e88c-5b87-a71a-569e7914ad9a', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 8, 8, 'እንደ ደመና፥ ከጫጩቶችዋ ጋር ወደ መስኮቷ እንደምትገባ ርግብም የሚበርሩ እነዚህ እነማን ናቸው?'),
  ('e078115b-81d1-5174-a835-3660e1dff059', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 9, 9, 'ደሴቶች እኔን ተስፋ ያደርጋሉ፤ የተርሴስም መርከቦች አስቀድመው ይመጣሉ፤ ልጆችሽ ስለ ከበረው ስለ እስራኤል ቅዱስ ስለ እግዚአብሔር ስም ወርቅና ብር ይዘው ከሩቅ ሀገር ይመጣሉ።'),
  ('b4338f09-6139-563e-a71a-85394fe2721f', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 10, 10, 'በቍጣዬ ቀሥፌ በይቅርታዬ አቅርቤሻለሁና መጻተኞች ቅጥርሽን ይሠራሉ፤ ነገሥታቶቻቸውም በፊትሽ ይቆማሉ።'),
  ('e673622d-bffd-5dc4-ab55-d7dcba90b0db', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 11, 11, 'በሮችሽም ሁልጊዜ ይከፈታሉ፤ ሰዎች የአሕዛብን ብልጽግና፥ የተማረኩትንም ነገሥታቶቻቸውን ወደ አንቺ ያመጡ ዘንድ ሌሊትና ቀን አይዘጉም።'),
  ('b923a775-1177-5cb1-a4b8-ad8d9c4de4f0', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 12, 12, 'ለአንቺም የማይገዙ ነገሥታት ይሞታሉ፤ እነዚያም አሕዛብ ፈጽመው ይጠፋሉ።'),
  ('34819f6c-fe83-56d7-ac8d-2b110d529e52', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 13, 13, 'የመቅደሴንም ስፍራ ያከብሩ ዘንድ የሊባኖስ ክብር፥ ጥዱና አስታው፥ ባርሰነቱም ወደ አንቺ ይመጣሉ፥'),
  ('890d6eda-4ed4-5022-afc6-25292c82a004', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 14, 14, 'የአስጨናቂዎችሽም ልጆች እየተንቀጠቀጡ ወደ አንቺ ይመጣሉ፤ የናቁሽም ሁሉ ወደ እግርሽ ጫማ ይሰግዳሉ፤ የእስራኤል ቅዱስ የእግዚአብሔር ከተማ፥ ጽዮን ተብለሽም ትጠሪያለሽ።'),
  ('3fabd41e-21b0-505b-ae45-44d10aa0bfa6', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 15, 15, 'የተተውሽና የተጠላሽ ሆነሻልና የሚረዳሽ አጣሽ፤ ነገር ግን የዘለዓለም ደስታን ለልጅ ልጅ እሰጥሻለሁ።'),
  ('6d7e0d69-cfff-5722-a8c4-a68eaa8e8faf', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 16, 16, 'የአሕዛብንም ወተት ትጠጫለሽ፤ የነገሥታትንም ብልጽግና ትበያለሽ፤ እኔም እግዚአብሔር የእስራኤል ቅዱስ፥ መድኀኒትሽና ታዳጊሽ እንደ ሆንሁ ታውቂያለሽ።'),
  ('e48f54eb-c9f9-5200-ab90-c0abcf9cd373', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 17, 17, 'በናስ ፋንታ ወርቅን፥ በብረትም ፋንታ ብርን፥ በእንጨትም ፋንታ ናስን፥ በድንጋይም ፋንታ ብረትን እሰጥሻለሁ። ለአለቆችሽም ሰላምን፥ ለመኳንንትሽም ፍርድን አደርጋለሁ፤'),
  ('c07620f1-74d4-53e3-a003-5639ee811601', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 18, 18, 'እንግዲህ በምድርሽ ውስጥ ግፍ፥ በዳርቻሽም ውስጥ ጕስቍልናና ቅጥቃጤ አይሰማም፤ ቅጥሮችሽ ድኅነት ይባላሉ፤ በሮችሽም በጥርብ ድንጋይ ይሠራሉ።'),
  ('9be01b8d-90ab-5c5c-aef8-de6b0cb090fd', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 19, 19, 'ፀሐይ በቀን የሚያበራልሽ አይደለም፤ በሌሊትም ጨረቃ የሚወጣልሽ አይደለም፤ ለአንቺስ እግዚአብሔር የዘለዓለም ብርሃንሽ፥ አምላክሽም ክብርሽ ይሆናል።'),
  ('f095da3a-0314-5edb-a8e1-69b6bcbbca40', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 20, 20, 'እግዚአብሔር የዘለዓለም ብርሃንሽ ይሆናልና፥ የልቅሶሽም ወራት ያልፋልና፤ ፀሐይሽ ከዚህ በኋላ አትጠልቅም፤ ጨረቃሽም አይቋረጥም።'),
  ('a6530e18-a9b5-5efe-a2df-2eaa77526891', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 21, 21, 'ሕዝብሽ ሁሉ ጻድቃን ይሆናሉ፤ ምድርንም ለዘለዓለም ይወርሳሉ፤ እርሱንም ለማመስገን የእጆቹን ሥራ ይጠብቃሉ።'),
  ('63f65410-a6a2-5cc6-a209-295a2f131966', '9993f86b-c544-54c3-ab88-8fb6fe44e69e', 'a51e7df5-39e1-59b5-aa87-ab7f503caf35', 22, 22, 'ታናሹ ሺህ፥ የሁሉም ታናሽ ታላቅ ሕዝብ ይሆናል፤ እኔ እግዚአብሔር በዘመናቸው ሁሉ እሰበስባቸዋለሁ።'),
  ('c51fa013-9a50-52c6-a207-ab7cfc2fefd3', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 1, 1, 'የጌታ የእግዚአብሔር መንፈስ በእኔ ላይ ነው፤ ለድሆች የምሥራችን እሰብክ ዘንድ እግዚአብሔር ቀብቶኛልና፤ ልባቸው የተሰበረውን እጠግን ዘንድ፥ ለተማረኩትም ነጻነትን፥ ለታሰሩትም መፈታትን፥ ለዕውራንም ማየትን እናገር ዘንድ ልኮኛል።'),
  ('5b73dcfe-0c2f-54c7-a4ce-ebc96101e56c', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 2, 2, 'የተወደደችውን የእግዚአብሔርንም ዓመት የተመረጠች ብዬ እጠራት ዘንድ፥ አምላካችንም የሚበቀልበትን ቀን እናገር ዘንድ፥ የሚያለቅሱትንም ሁሉ አጽናና ዘንድ፥'),
  ('73421019-bfc8-5330-ac10-9d6f7f8f9248', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 3, 3, 'እግዚአብሔር ለክብሩ የተከላቸው የጽድቅ ዛፎች እንዲባሉ ለጽዮን አልቃሾች አደርግላቸው ዘንድ፥ በአመድም ፋንታ አክሊልን፥ በልቅሶም ፋንታ የደስታን ዘይት፥ በኀዘንም መንፈስ ፋንታ የምስጋናን መጐናጸፊያ እሰጣቸው ዘንድ ልኮኛል።'),
  ('d98534d8-55b5-5510-af71-fb5e41e91cdb', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 4, 4, 'ከጥንት ጀምሮ የፈረሱትን ይሠራሉ፤ ከቀድሞ ጀምሮ የፈረሱትንም ያቆማሉ፤ ባድማ የነበሩትንና ከብዙ ትውልድ በፊት የፈረሱትን ከተሞች እንደ ገና ያድሳሉ።'),
  ('63e5de7e-778c-5c8c-a838-907d6e663317', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 5, 5, 'መጻተኞችም መጥተው በጎቻችሁን ይጠብቃሉ፥ ሌሎች ወገኖችም አራሾችና ወይን ጠባቂዎች ይሆኑላችኋል።'),
  ('c99824a4-82b1-5725-aadd-5ff8f9ea4d7e', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 6, 6, 'እናንተ ግን የእግዚአብሔር ካህናት ትባላላችሁ፤ የአምላካችንም አገልጋዮች ተብላችሁ ትጠራላችሁ፤ የአሕዛብን ሀብት ትበላላችሁ፤ በሀብታቸውም ትመካላችሁ።'),
  ('acb3f3db-c25a-5b43-a4c8-d29db7a6a889', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 7, 7, 'ሌላ ምድርን ይወርሳሉ፤ በራሳቸውም ዘለዓለማዊ ደስታ አላቸው።'),
  ('3d02783a-fcce-5ebb-a9cc-4158e60d0e33', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 8, 8, 'እኔ እግዚአብሔር ጽድቅን የምወድድ፥ ስርቆትንና ቅሚያን የምጠላ ነኝ፤ እንደ ሥራቸውም ለጻድቃን እከፍላቸዋለሁ፤ ከእነርሱም ጋር የዘለዓለምን ቃል ኪዳን አደርጋለሁ።'),
  ('5736f76d-8076-5553-a380-68462e3dad59', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 9, 9, 'ዘራቸው በአሕዛብ መካከል፥ ልጆቻቸውም በወገኖች መካከል የታወቁ ይሆናሉ፤ ያያቸው ሁሉ እግዚአብሔር የባረካቸው ዘር እንደ ሆኑ ያውቃል፤'),
  ('6d2ddf70-6f5c-5a76-ae70-230258a078b6', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 10, 10, 'በእግዚአብሔርም እጅግ ደስ ይላቸዋል። ነፍሴም በእግዚአብሔር ሐሤት ታደርጋለች። ሽልማትን እንደ ለበሰ ሙሽራ፥ በጌጥ ሽልማቷም እንዳጌጠች ሙሽራ፥ የማዳንን ልብስ አልብሶኛልና፥ የደስታንም መጐናጸፊያ ደርቦልኛልና።'),
  ('e5b91d42-827d-5e8f-ae1a-b23f2039f478', '2451a909-5475-5945-add4-766ce509d5f5', 'd5a28ccd-90fc-570b-a665-001fbfb0fa4a', 11, 11, 'ምድርም ቡቃያውን እንደምታወጣ፥ ገነትም ዘሩን እንደሚያበቅል፥ እንዲሁ ጌታ እግዚአብሔር ጽድቅንና ደስታን በአሕዛብ ሁሉ ፊት ያበቅላል።'),
  ('637e328e-35c4-5ff5-af62-8fc9ed1fb441', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 1, 1, 'ጽድቄ እንደ ብርሃን፥ ማዳኔም እንደሚበራ ፋና እስኪወጣ ድረስ ስለ ጽዮን ዝም አልልም፤ ስለ ኢየሩሳሌምም ጸጥ አልልም።'),
  ('8d6a2ea2-9a95-5fd9-aefb-e9166558f5b0', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 2, 2, 'አሕዛብ ጽድቅሽን፥ ነገሥታትም ሁሉ ክብርሽን ያያሉ፤ የእግዚአብሔርም አፍ በሚጠራበት በአዲሱ ስም ትጠሪያለሽ።'),
  ('fced4ba1-051b-5e1a-a9b6-c0bb3a644611', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 3, 3, 'በእግዚአብሔር እጅ ያማረ አክሊል፥ በአምላክሽም እጅ የመንግሥት ዘውድ ትሆኛለሽ።'),
  ('cb27ba32-7b32-5111-a850-1105a4092510', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 4, 4, 'ከእንግዲህ ወዲህ፥ “የተተወች” አትባዪም፤ ምድርሽም ከእንግዲህ ወዲህ፥ “ውድማ” አትባልም፤ ነገር ግን እግዚአብሔር በአንቺ ደስ ብሎታልና፥ ምድርሽም ባል ታገባለችና አንቺ፥ “ደስታዬ የሚኖርባት” ትባያለሽ፤ ምድርሽም፥ “ባል ያገባች” ትባላለች።'),
  ('dbd2a4b7-6e58-57e3-a358-133ea31a1f9c', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 5, 5, 'ጐልማሳም ከድንግሊቱ ጋር እንደሚኖር፥ እንዲሁ ልጆችሽ ከአንቺ ጋር ይኖራሉ፤ ሙሽራም በሙሽራዪቱ ደስ እንደሚለው፥ እንዲሁ አምላክሽ በአንቺ ደስ ይለዋል።'),
  ('bb9db300-ec1b-58ee-a101-2579f2fc6c54', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 6, 6, 'ኢየሩሳሌም ሆይ፥ ጠባቂዎችሽን በቅጥርሽ ላይ ቀንና ሌሊት አቁሜአለሁ፤ እግዚአብሔርን የሚያስቡ ከቶ ዝም አይሉም፤'),
  ('c55a2ee1-8491-57c7-a8d8-592a96cb9419', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 7, 7, 'ኢየሩሳሌምን እስኪያጸና፥ በምድርም ላይ ምስጋና እስኪያደርጋት ድረስ ዝም አትበሉ።'),
  ('56fd2c28-c2ab-5565-a2fe-63e253239330', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 8, 8, 'እግዚአብሔር፥ “ከእንግዲህ ወዲህ በእርግጥ ለጠላቶችሽ መብል ይሆን ዘንድ እህልሽን አልሰጥም፥ መጻተኞችም የደከምሽበትን ወይንሽን አይጠጡም፤” ብሎ በጌትነቱና በክንዱ ኀይል ምሎአል።'),
  ('0020e0d1-5be0-5830-ac62-aba6984401c5', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 9, 9, 'ነገር ግን የሰበሰቡት ይበሉታል፤ እግዚአብሔርንም ያመሰግናሉ፤ ያከማቹትንም ወይን በመቅደሴ አደባባይ ላይ ይጠጡታል።'),
  ('c7bf7b66-6f1e-5e1f-a9d1-53d5f3c72d2f', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 10, 10, 'ሂዱና በበሬ ውስጥ ግቡ፤ ለሕዝቤም መንገድን ጥረጉ፤ ድንጋዮቹንም ከጎዳናው አስወግዱ፤ ለአሕዛብም አላማ ያዙ።'),
  ('ead0e42b-4c3d-54f1-a035-029b9f8be3b1', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 11, 11, 'እነሆ፥ እግዚአብሔር እስከ ምድር ዳርቻ አዋጅ እንዲህ ብሎ ነግሮአል፥ “ለጽዮን ልጅ፦ እነሆ፥ መድኀኒትሽ ይመጣል፤ እነሆ፥ ዋጋው ከእርሱ ጋር ሥራውም በፊቱ አለ በሉአት።”'),
  ('b3bc9b69-325e-5e0d-a13d-38d2cb188692', '69d4fbca-927f-557c-a4a0-a300fff961bd', 'da33281c-de72-51ea-a4be-02e754495e72', 12, 12, 'እግዚአብሔር፥ “የተቤዣቸው፥ የተቀደሰ ሕዝብ” ብለው ይጠሩአቸዋል፤ አንቺም፥ “የተተወች ያይደለች የተወደደች ቅድስት ከተማ” ትባያለሽ።'),
  ('9835e6ea-27b0-5009-a7fd-d89580b0f667', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '99f20f82-7049-5d6c-a41b-52e61aaaf81d', 1, 1, 'ከኤዶምያስ፥ ከባሶራ የሚመጣ፥ ልብሱም የቀላ፥ የሚመካ ኀይለኛ፥ አለባበሱም ያማረ፥ ይህ ማን ነው? ስለ ጽድቅ የምከራከር፥ ስለ ማዳንም የምፈርድ እኔ ነኝ።'),
  ('17f97d88-4c23-51b8-a95d-170c75eed604', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '99f20f82-7049-5d6c-a41b-52e61aaaf81d', 2, 2, 'ቀሚስህ ስለ ምን ቀላ? ልብስህስ በወይን መጭመቂያ እንደሚረግጥ ሰው ልብስ ስለ ምን መሰለ?'),
  ('630393e6-1020-5447-a1c3-af7537c44ae9', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '99f20f82-7049-5d6c-a41b-52e61aaaf81d', 3, 3, 'መጭመቂያውን ብቻዬን ረግጫለሁ፤ ከአሕዛብም አንድ ሰው ከእኔ ጋር አልነበረም፤ በቍጣዬም ረገጥኋቸው፤ በመዓቴም ወደ መሬት ጣልጥህዋቸው፤ ደማቸውንም በምድር ላይ አፈሰስሁ፤ ልብሴም ሁሉ በደም ታለለ።'),
  ('6eee57a7-0774-5d85-a6b6-bc6ddd347f47', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '99f20f82-7049-5d6c-a41b-52e61aaaf81d', 4, 4, 'የምበቀልበት ቀን ደርሶባቸዋልና፥ የምቤዥበትም ዐመት ደርሶአልና።'),
  ('3a5446a3-1a36-5c42-a4a6-d9a66ef6bafb', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '99f20f82-7049-5d6c-a41b-52e61aaaf81d', 5, 5, 'የሚረዳም እንደሌለ አየሁ፤ የሚያግዝም እንደሌለ ዐወቅሁ፤ ስለዚህ በገዛ ክንዴ አድናቸዋለሁ፤ ቍጣዬም ወደቀችባቸው።'),
  ('1fe49010-8d59-54b6-a693-1b0db2140401', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '99f20f82-7049-5d6c-a41b-52e61aaaf81d', 6, 6, 'በመቅሠፍቴ ረገጥኋቸው፤ ደማቸውንም ወደ ምድር አፈሰስሁት።'),
  ('6187f7d4-9fdc-5be1-a247-54581d1b158f', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 1, 7, 'በስጦታው ሁሉ የእግዚአብሔርን ቸርነትና የእግዚአብሔርን ምስጋና ዐሰብሁ፤ እግዚአብሔር ለእስራኤል ወገኖች እውነተኛ ፈራጅ ነው፤ እንደ ቸርነቱና እንደ ጽድቁ ብዛትም ይቅርታውን ያመጣልናል።'),
  ('e03216e8-d55b-5338-ab41-abe3754e2df0', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 2, 8, 'እርሱም፥ “ሕዝቤ ልጆች አይደሉምን? ካልከዱኝስ ከመከራቸው ሁሉ አድናቸዋለሁ” አለ።'),
  ('85e4fe61-70d9-5ed6-a3f9-e1b2fbbc4bfb', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 3, 9, 'በመልእክተኛም አይደለም፤ በመልአክም አይደለም፤ እርሱ ራሱ ያድናቸዋል እንጂ። እርሱ ይወዳቸዋልና፥ ይራራላቸዋልምና እርሱ ተቤዣቸው፤ ተቀበላቸውም፤ በዘመናቸውም ሁሉ ለዘለዓለም አከበራቸው።'),
  ('c815090c-05d4-544d-a7ed-fc5bb95462be', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 4, 10, 'እነርሱ ግን ዐመፁበት፤ ቅዱስ መንፈሱንም አስመረሩ፤ ስለዚህ ተመልሶ ጠላት ሆናቸው፤ እርሱም ተዋጋቸው።'),
  ('a86ee812-a7b1-5b05-a2f7-e21217fbdddd', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 5, 11, 'እርሱም እንዲህ ብሎ የቀደመውን ዘመን ዐሰበ፥ “በበጎቹ እረኛ እጅ ከግብፅ በወጡ ጊዜ መልአኬን በፊታቸው ላክሁ።'),
  ('bcb24e04-3754-51e3-ae41-20ceac5b909f', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 6, 12, 'በሙሴም ቀኝ እጅ ውኃውን ከፈልሁ፤” ውኃውም ተከፍሎ በፊቱ ጸና፤ የዘለዓለም ስምንም አደረገለት።'),
  ('b22beddb-fa18-597e-ac23-fd7c5316b83b', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 7, 13, 'ፈረስ በምድረ በዳ እንደሚያልፍ፥ በቀላይ ውስጥ አሳለፋቸው፥ እነርሱም አልደከሙም።'),
  ('933317dd-c754-53e1-aa7c-b015d92d57c3', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '1511396f-55c4-548a-ae3c-d80bd6e43203', 8, 14, 'ወደ ሸለቆ እንደሚወርዱ ከብቶች፥ እንዲሁ የእግዚአብሔር መንፈስ ወደ ዕረፍት አመጣቸው፤ እንዲሁም ለራስህ የከበረ ስምን ታደርግ ዘንድ ሕዝብህን መራህ።'),
  ('34d426d6-5dc4-5c10-a885-e5cefe5e1c7b', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '8b67a05a-33a1-5115-a489-a53ec9314f4c', 1, 15, 'ከሰማይ ተመለስ፤ ከቅድስናህና ከክብርህ ማደሪያም ተመልከት፤ ቅንአትህና ኀይልህስ ወዴት ነው? የቸርነትህና የይቅርታህ ብዛት ወዴት ነው? ቸል ብለሃልና።'),
  ('a633344f-83f6-56c8-ae5d-3fe9da651752', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '8b67a05a-33a1-5115-a489-a53ec9314f4c', 2, 16, 'አንተ አባታችን ነህ፤ አብርሃም ግን አላወቀንም፤ እስራኤልም አልተገነዘበንም፤ ነገር ግን አንተ አባታችን አድነን፤ ስምህም ለዘለዓለም በእኛ ላይ ነው።'),
  ('bcf5a0f5-f84d-53ee-a3ce-002f139e7769', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '8b67a05a-33a1-5115-a489-a53ec9314f4c', 3, 17, 'አቤቱ፥ ከመንገድህ ለምን አሳትኸን? እንዳንፈራህም ልባችንን ለምን አጸናህብን? ስለ ባሪያዎችህ ስለ ርስትህ ነገዶች ተመለስ፤'),
  ('54143164-76f7-524d-a11a-0d42e515b11f', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '8b67a05a-33a1-5115-a489-a53ec9314f4c', 4, 18, 'በተቀደሰው ተራራህ ከርስትህ ጥቂት ክፍል እናገኝ ዘንድ።'),
  ('169a56d6-32d4-525b-a7e6-76d191c8ccb7', '6bc20e29-83b2-5ebd-a809-c44389bc134c', '8b67a05a-33a1-5115-a489-a53ec9314f4c', 5, 19, 'ከጥንት እንዳልገዛኸን ስምህም በእኛ ላይ እንዳልተጠራ ሆነናልና።'),
  ('49f56e4f-1929-581b-ae1d-6dd3294b0a2d', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 1, 1, 'ሰማይን ብትከፍት ከአንተ የተነሣ ተራሮች ይንቀጠቀጣሉ፤ ይቀልጣሉም።'),
  ('ef548160-f2d4-5db5-aa77-840d4c093b4f', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 2, 2, 'አደሮ ማር በእሳት ፊት እንደሚቀልጥ እንዲሁ ጠላቶችህን እሳት ትበላቸዋለች፤ ስምህም በእነርሱ ላይ ይታወቃል፤ አሕዛብም በፊትህ ይደነግጣሉ።'),
  ('928cf8c6-84e4-56c6-aeb1-418b514086ea', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 3, 3, 'የክብርህንም ሥራ ባደረግህ ጊዜ፥ ተራሮች በፊትህ ተንቀጠቀጡ።'),
  ('00a75ef3-3b20-5b88-ac87-1d9c1d93719e', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 4, 4, 'ከጥንት ጀምሮ ይቅርታህን ለሚጠባበቁ ምሕረትን ከምታደርግላቸው ከአንተ በቀር ሌላ አምላክ አላየንም፤ አልሰማንምም።'),
  ('6b1a1a77-736d-5bf0-a448-fff345ec2feb', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 5, 5, 'በቸርነትህ የሚታገሡ መንገድህንም የሚያስቡ ይገናኙሃል፤ እነሆ፥ አንተ ተቈጣህ፤ እኛም ኀጢአት ሠራን፤ ስለዚህም ተሳሳትን።'),
  ('8264ecb4-25fc-579a-a8eb-6f45ef5325c7', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 6, 6, 'ሁላችን እንደ ርኩስ ሰው ሆነናል፤ ጽድቃችንም ሁሉ እንደ መርገም ጨርቅ ነው፤ በኀጢአታችን ምክንያት እንደ ቅጠል ረግፈናል፤ እንዲሁም ነፋስ ጠራርጎ ወስዶናል።'),
  ('7a96e678-25a7-596f-a07c-e440c3e54a40', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 7, 7, 'ስምህንም የሚጠራ፥ አንተንም የሚያስብ የለም፤ ፊትህንም ከእኛ መልሰሃል፤ ለኀጢአታችንም አሳልፈህ ሰጥተኸናል።'),
  ('980eb4d1-7022-5081-af03-eb498f3906d9', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 8, 8, 'አሁን ግን፥ ጌታ ሆይ፥ አንተ አባታችን ነህ፤ እኛ ጭቃ ነን፤ አንተም ሠሪያችን ነህ፤ እኛም ሁላችን የእጅህ ሥራ ነን።'),
  ('a9e6662d-6ac6-5144-a852-ea5f406eb213', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 9, 9, 'አቤቱ፥ እጅግ አትቈጣ፤ ለዘለዓለምም ኀጢአታችንን አታስብ፤ አሁንም እባክህ፥ ወደ እኛ ተመልከት፤ እኛ ሁላችን ሕዝብህ ነን።'),
  ('580f4436-0a21-5337-aa37-88c15904b2e5', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 10, 10, 'የተቀደሱ ከተሞችህ ምድረ በዳ ሆነዋል፤ ጽዮን ምድረ በዳ ኢየሩሳሌምም ውድማ ሆናለች።'),
  ('057881f5-d186-5791-a9a4-c2051059cc5a', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 11, 11, 'አባቶቻችን ያከበሩት ክብራችን ቤተ መቅደስህ በእሳት ተቃጥሎአል፤ ያማረውም ስፍራችን ፈርሶአል።'),
  ('448103b0-3d98-5837-ae1e-544f97894146', '37fa8785-216c-52b8-afcd-4d4a7529ff1f', 'bf52d942-88d2-58b1-a918-a0edc117f8f3', 12, 12, 'አቤቱ፥ በዚህ ነገር ሁሉ ታገሥኸን፤ ዝም አልኸን፤ እጅግም አዋረድኸን።'),
  ('30a39835-36ca-58b4-aa8d-2d17e1a2a341', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 1, 1, 'ያልፈለጉኝ አገኙኝ፤ ላልጠየቁኝም ተገኘሁ፤ ስሜን ላልጠራ ሕዝብ፥ “እነሆኝ” አልሁት።'),
  ('863cf53d-f7e1-5ef5-ac23-c3d0f225d3ef', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 2, 2, 'በጽድቅ መንገድ ወደማይሄዱ፥ ኀጢአታቸውን ወደሚከተሉ ዐመፀኞች ሕዝብ ቀኑን ሁሉ እጆችን ዘረጋሁ።'),
  ('f4249569-c9c1-5bab-a4db-716eb4f9192a', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 3, 3, 'እኒህ ሕዝብ ዘወትር የሚያስቈጡኝ ናቸው፤ እነርሱ በአትክልት ውስጥ የሚሠዉ በጡብም ላይ ለአጋንንት የሚያጥኑ፥'),
  ('242df213-32ac-5ee8-a2b1-a85a2ef0075f', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 4, 4, 'በመቃብርም መካከል የሚተኙ፥ በዋሻ ውስጥ የሚያልሙ፥ የእሪያ ሥጋም የሚበሉ ናቸው። የመሥዋዕታቸውን ደምና ዕቃቸውንም ሁሉ ያረክሳሉ።'),
  ('e4913da7-1cfb-5de6-a0ec-1f43c1a3c64b', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 5, 5, '“እኔ ንጹሕ ነኝና ከእኔ ራቁ፥ ወደ እኔም አትቅረቡ” ይላሉ። ስለዚህም የቍጣዬ ጢስ በዘመኑ ሁሉ እንደ እሳት ይነድድባቸዋል።'),
  ('3cdeb962-2a37-5ca4-afed-d08ca1c79716', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 6, 6, 'እነሆ፥ በፊቴ ተጽፎአል፦ ኀጢአቶቻችሁንና የአባቶቻችሁን ኀጢአት በአንድ ላይ ወደ ብብታቸው ፍዳ አድርጌ እመልሳለሁ እንጂ ዝም አልልም፤ ይላል እግዚአብሔር፤'),
  ('c5439014-6a38-5a43-aa76-bfd105bbb0b6', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 7, 7, 'በተራሮችም ላይ ስላጠኑ፥ በኮረብቶችም ላይ ስለ አሽሟጠጡኝ ስለዚህ አስቀድመው የሠሩትን ሥራቸውን በብብታቸው እሰፍራለሁ።'),
  ('6464be8b-3902-5e50-ad6e-240ba529d8f7', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 8, 8, 'እግዚአብሔር እንዲህ ይላል፥ “የወይን ፍሬ በዘለላው በተገኘች ጊዜ፦ በረከት በእርስዋ ላይ አለና አታጥፉት እንደሚባለው፥ ሁሉን እንዳላጠፋ ስለ ባሪያዎች እንዲህ አደርጋለሁ።'),
  ('6b6affd7-cf92-5e77-ae88-15213fd86dc7', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 9, 9, 'የያዕቆብን ዘርና የይሁዳን ዘር አመጣለሁ፤ የተቀደሰው ተራራዬንም ይወርሳሉ፤ እኔ የመረጥኋቸውና ባሪያዎችም ይወርሱአታል፤ በዚያም ይኖራሉ።'),
  ('66c9f6b6-1470-5610-a32d-d45cebddaafd', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 10, 10, 'በመንጋው መሰማሪያና በዛፍ መካከል በአኮር ሸለቆና በቆላውም የላሞች መመሰግያ ለፈለጉኝ ሕዝቤ ይሆናል።'),
  ('9bfd03ca-7204-593a-a90b-7dc384b986dd', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 11, 11, '“እናንተ ግን እኔን ተዋችሁኝ፤ ቅዱሱንም ተራራዬን ረሳችሁ፥ ለአጋንንትም ማዕድ አዘጋጃችሁ፤ ዕድል ለተባለ ጣዖትም የወይን ጠጅ ለመጠጥ ቍርባን ቀዳችሁ፤'),
  ('1777de4a-3bcc-53cc-a629-cd1acb6b298e', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 12, 12, 'እኔም ለሰይፍ አሳልፌ እሰጣችኋለሁ፤ ሁላችሁም በሰይፍ ትገደላላችሁ፤ በፊቴ ክፉ ነገር አደረጋችሁ፤ ያልወደድሁትንም መረጣችሁ እንጂ በጠራኋችሁ ጊዜ አልመለሳችሁልኝምና፥ በተናገርሁም ጊዜ አልሰማችሁኝምና።”'),
  ('20a3fe0f-7bed-5e6b-a2ee-d24ab6c11d1f', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 13, 13, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፥ “እነሆ፥ ባሪያዎች ይበላሉ፤ እናንተ ግን ትራባላችሁ፤ እነሆ፥ ባሪያዎች ይጠጣሉ፤ እናንተ ግን ትጠማላችሁ፤ እነሆ፥ ባሪያዎች ደስ ይላቸዋል፤ እናንተ ግን ትጐሰቍላላችሁ፤'),
  ('9b9c63db-b212-591c-ae3e-b7ea8334de1c', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 14, 14, 'እነሆ፥ ባሪያዎች ሐሤት ያደርጋሉ፤ እናንተ ግን ከልባችሁ ኀዘን የተነሣ ትጮኻላችሁ፤ መንፈሳችሁም ስለ ተሰበረ ወዮ! ትላላችሁ።'),
  ('11d7716d-eece-53c9-abf7-584b533a8231', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 15, 15, 'ስማችሁንም እኔ ለመረጥኋቸው ሕዝቤ ጥጋብ አድርጋችሁ ትተዋላችሁ፤ ጌታ እግዚአብሔርም ያጠፋችኋል፤ ባሪያዎች ግን በሐዲስ ስም ይጠራሉ።'),
  ('bdcb93b0-a949-5d0a-a4d6-a4dbe7e94f8e', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 16, 16, 'እንዲሁም በምድር ላይ የተባረኩ ይሆናሉ፤ እውነተኛውን አምላክ ያመሰግናሉና፥ በምድርም ላይ በእውነተኛው አምላክ ይምላሉና፤ የቀድሞውንም ጭንቀት ረስተዋልና፤ በልቡናቸውም አያስቡትምና።'),
  ('cd57b669-3ef3-581c-a509-2a8b4d06ca46', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 17, 17, '“እነሆ፥ አዲስ ሰማይና አዲስ ምድር ይሆናልና፤ የቀደሙትም አይታሰቡም፤ ወደ ልብም አይገቡም።'),
  ('acb73f4f-8b3e-54c5-a77f-5c8a68eaf417', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 18, 18, 'ነገር ግን በውስጥዋ ደስታንና ሐሤትን ያገኛሉ፤ እኔም ለኢየሩሳሌም ደስታን ለሕዝቤም ሐሤትን አደርጋለሁ።'),
  ('1a748b42-7d9c-56c4-a408-21e6d38f475f', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 19, 19, 'እኔም በኢየሩሳሌም ሐሤትን አደርጋለሁ፤ በሕዝቤም ደስ ይለኛል፤ ከዚያም ወዲያ የልቅሶ ድምፅና የዋይታ ድምፅ በውስጥዋ አይሰማም።'),
  ('916d3d3b-ac60-5874-ad5b-4bbaa58176a5', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 20, 20, 'ከዚያም ወዲያ ጥቂት ዘመን ብቻ የሚኖር ሕፃን፥ ወይም ዕድሜውን ያልፈጸመ ሽማግሌ አይገኝም፤ ጐልማሳው የመቶ ዓመት ሆኖት ይሞታልና፥ ኀጢአተኛውም የመቶ ዓመት ሆኖት የተረገመ ይሆናልና።'),
  ('822fe9ed-07c2-57e1-a288-9838bb1b5648', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 21, 21, 'ቤቶችንም ይሠራሉ፤ ይቀመጡባቸውማል፤ ወይኑን ይተክላሉ፤ ፍሬውንም ይበላሉ።'),
  ('2b21535d-27b6-540d-a5b8-b81e32d368f3', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 22, 22, 'ሌላ እንዲቀመጥበት አይሠሩም፤ ሌላም እንዲበላው አይተክሉም፤ የሕዝቤ ዕድሜ እንደ ሕይወት ዛፍ ዕድሜ ይሆናልና፥ እኔም የመረጥኋቸው በእጃቸው ሥራ ረዥም ዘመን ደስ ይላቸዋል።'),
  ('c68c16e4-c214-54eb-a512-4f4008449c20', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 23, 23, 'እነርሱ ከእነልጆቻቸው የእግዚአብሔር ቡሩካን ዘር ናቸውና በከንቱ አይደክሙም፤ ለርግማንም አይወልዱም።'),
  ('1200a48e-5e52-5834-a932-0a3975bff706', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 24, 24, '“እንዲህም ይሆናል፤ ሳይጠሩ እመልስላቸዋለሁ፤ ገናም ሲናገሩ እነሆ፥ አለሁ እላቸዋለሁ።'),
  ('29cdbe6e-b237-5ecd-ad48-a95d7452c66b', 'bc24f30a-d307-54e6-a184-257fc711e1aa', '25942860-5a32-55bf-aba8-0afdac927021', 25, 25, 'ያንጊዜ ተኵላና በግ በአንድነት ይሰማራሉ፤ አንበሳም እንደ በሬ ገለባ ይበላል፤ የእባብም መብል ትቢያ ይሆናል። በተቀደሰው ተራራዬ ሁሉ አይጐዱም፤ አያጠፉምም፥” ይላል እግዚአብሔር።'),
  ('1a886efd-aa60-58af-a7a1-218e4d495c55', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 1, 1, 'እግዚአብሔር እንዲህ ይላል፥ “ሰማይ ዙፋኔ ነው፤ ምድርም የእግሬ መረገጫ ናት፤ የምትሠሩልኝ ቤት ምን ዓይነት ነው? የማርፍበትስ ስፍራ ምንድን ነው?'),
  ('ce46ae20-7bb7-58ab-aefc-c33b8e1dd8f9', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 2, 2, 'ይህ ሁሉ የእጄ ሥራ ነው፤ ይህም ሁሉ የእኔ ነው፥” ይላል እግዚአብሔር፤ “ወደ የዋሁና ወደ ጸጥተኛው፥ ከቃሌም የተነሣ ወደሚንቀጠቀጥ ሰው ከአልሆነ በቀር ወደ ማን እመለከታለሁ?'),
  ('6c02e5e2-614f-5d6c-a1f8-c84e588cf86b', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 3, 3, 'በሬን የሚሠዋልኝ ኃጥእ ውሻን እንደሚያርድልኝ ነው፤ የእህልን ቍርባን የሚያቀርብም የእሪያን ደም እንደሚያቀርብ ነው፤ ዕጣንንም ለመታሰቢያ የሚያጥን አምላክን እንደሚፀርፍ ነው፤ እነዚህ የገዛ መንገዳቸውን መረጡ፤ ነፍሳቸውም በርኵሰታቸው ደስ ይላታል።'),
  ('af8c565a-a645-51af-a9d0-c68992116573', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 4, 4, 'እኔ ግን አዋርዳቸው ዘንድ፥ ስለ ኀጢአታቸውም እበቀላቸው ዘንድ እፈቅዳለሁ፤ እኔ በጠራሁ ጊዜ አልመለሱልኝምና፥ በተናገርሁም ጊዜ አልሰሙኝም፤ በፊቴም ክፉ ነገርን አደረጉ፤ ያልወደድሁትንም መረጡ።”'),
  ('1c600278-7042-585d-a0e2-aa63f6dbbce0', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 5, 5, 'በቃሉ የምትንቀጠቀጡ ሆይ፥ የእግዚአብሔርን ቃል ስሙ፥ “የእግዚአብሔር ስም ይከብር ዘንድ፦ ደስታችሁም ይገለጥ ዘንድ፥ እነርሱም ያፍሩ ዘንድ የሚጠሏችሁንና የሚጸየፉአችሁን ወንድሞቻችን በሏቸው።'),
  ('6de466d9-151e-5b1a-aa4c-54efbaa33454', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 6, 6, 'የጩኸት ድምፅ ከከተማ፥ ድምፅም ከመቅደስ፥ በጠላቶቹም ላይ ፍዳን የሚያመጣ የእግዚአብሔር ድምፅ ተሰምቶአል።'),
  ('e51d6385-ce56-5f4f-aefc-cf645d6100f3', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 7, 7, '“ሳታምጥ ወለደች፤ ምጥም ሳያገኛት ወንድ ልጅን ወለደች።'),
  ('f8735aa9-bdd9-56c1-a708-83267602e432', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 8, 8, 'ከቶ እንዲህ ያለ ነገርን ማን ሰምቶአል? እንዲህስ ያለ ነገርን ማን አይቶአል? በውኑ ሀገር በአንድ ቀን ታምጣለችን? ወይስ በአንድ ጊዜ ሕዝብ ይወለዳልን? ጽዮን እንዳማጠች ወዲያው ልጆችዋን ወልዳለችና።'),
  ('394a7634-32f3-5b96-a2e8-eaf59103677a', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 9, 9, 'እኔ ተስፋን ሰጠሁሽ፤ አንቺ ግን አላሰብሽኝም ይላል እግዚአብሔር። ሴት እንድትወልድ፥ መካንም እንዳትሆን የማደርግ እኔ አይደለሁምን?” ይላል አምላክሽ።'),
  ('712f8c96-1cf6-5cf6-a500-52aa9ddd9d79', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 10, 10, 'ኢየሩሳሌም ሆይ ደስ ይበልሽ፤ እርስዋንም የምትወድዱአት ሁሉ፥ በአንድነት ሐሤት አድርጉ፤ ስለ እርስዋም ያለቀሳችሁ ሁሉ፥ ከእርስዋ ጋር ደስ ይበላችሁ፤'),
  ('d3e03ed1-6caf-5688-a5d5-dadeaf4b8c17', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 11, 11, 'ትጠቡ ዘንድ ከማጽናናቷም ጡት ትጠግቡ ዘንድ እጅግ ጠጥታችሁ በክብርዋ ሙላት ደስ ይላችሁ ዘንድ።'),
  ('6ddbbadb-d9a1-51a1-a9d0-3c5d298348cc', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 12, 12, 'እግዚአብሔር እንዲህ ይላልና፥ “እነሆ፥ ሰላምን እንደ ወንዝ፥ የአሕዛብንም ክብር እንደሚጐርፍ ፈሳሽ እመልስላታለሁ፤ ልጆቻቸውንም በጫንቃቸው ላይ ይሸከሙአቸዋል፤ በጕልበታቸውም ላይ እያስቀመጡ ያቀማጥሏቸዋል።'),
  ('8cfc2c57-a6cb-5048-a184-204d77bfb7d6', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 13, 13, 'እናት ልጅዋን እንደምታጽናና እንዲሁ አጽናናችኋለሁ፤ በኢየሩሳሌምም ውስጥ ትጽናናላችሁ።'),
  ('9f698866-7f7b-58c4-ad22-9f93e023607e', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 14, 14, 'ታያላችሁ፤ ልባችሁም ሐሤት ታደርጋለች፤ አጥንታችሁም እንደ ለምለም ሣር ትበቅላለች፤ የእግዚአብሔርም እጅ ለሚፈሩት ትታወቃለች፤ ዐላውያንንም ያጠፋቸዋል።”'),
  ('d881be73-acad-5040-ad68-0ca3b02b5363', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 15, 15, 'እነሆ፥ እግዚአብሔር መዓቱን በቍጣ፥ ዘለፋውንም በእሳት ነበልባል ይመልስ ዘንድ እንደ እሳት ይመጣል፤ ሰረገሎቹም እንደ ዐውሎ ነፋስ ይሆናሉ።'),
  ('f9e4dc67-31f0-5c16-adc3-21563660b1a5', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 16, 16, 'ምድርም ሁሉ በእግዚአብሔር እሳት ሰውም ሁሉ በሰይፉ ይፈረድባቸዋል፤ በእግዚአብሔርም ተቀሥፈው የሞቱት ይበዛሉ።'),
  ('3d39dd3a-2ebd-5abd-a4ed-45d68b05b2b5', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 17, 17, '“በአትክልት ቦታ ውስጥ ሰውነታቸውን የሚያጠሩና የሚያነጹ፥ በምግብ ቦታም የእሪያን ሥጋ፥ አስጸያፊ ነገርንም አይጥንም የሚበሉ በአንድነት ይጠፋሉ፥ ይላል እግዚአብሔር።'),
  ('cdb76ac0-9a37-52a7-a96f-43e31c8aa04a', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 18, 18, '“ሥራቸውንና አሳባቸውን ዐውቄአለሁ፤ እነሆም እኔ እመጣለሁ፤ አሕዛብንና ልሳናትንም ሁሉ እሰበስባለሁ፤ እነርሱም ይመጣሉ፤ ክብሬንም ያያሉ።'),
  ('40dbfbe4-c57a-5fe7-aba6-a4f2939d1f52', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 19, 19, 'በመካከላቸውም ምልክት አደርጋለሁ፤ ከእነርሱም ከሞት የዳኑትን ዝናዬን ወዳልሰሙ፥ ክብሬንም ወዳላዩ ወደ አሕዛብ ወደ ተርሴስ፥ ወደ ፉጥ፥ ወደ ሉድ፥ ወደ ሞሳሕ፥ ወደ ቶቤል፥ ወደ ኤላድ በሩቅ ወዳሉ ደሴቶች እልካቸዋለሁ፤ በአሕዛብም መካከል ክብሬን ይናገራሉ።'),
  ('a3b159ec-c070-55ef-a8e3-bf48139ec7aa', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 20, 20, 'የእስራኤል ልጆች ቍርባናቸውን በምስጋና ወደ እግዚአብሔር ቤት እንደሚያመጡ፥ እንዲሁ ለእግዚአብሔር ቍርባን ይሆን ዘንድ ወንድሞቻችሁን ሁሉ፥ በፈረሶችና በሰረገሎች፥ በአልጋዎችና በበቅሎዎች፥ በጠያር ግመሎችም ላይ አድርገው፥ ከአሕዛብ ሁሉ ወደ ተቀደሰችው ከተማ ወደ ኢየሩሳሌም ያመጡአቸዋል፥ ይላል እግዚአብሔር።'),
  ('fca6c2f1-4dc6-5103-a7d2-ed2f6addf946', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 21, 21, 'ካህናትና ሌዋውያን እንዲሆኑ ከእነርሱ እወስዳለሁ፥ ይላል እግዚአብሔር።'),
  ('316f061a-e52a-5b90-a008-47380376d8e9', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 22, 22, '“እኔ የምሠራቸው አዲስ ሰማይና አዲስ ምድር በፊቴ ጸንተው እንደሚኖሩ፥ እንዲሁ ዘራችሁና ስማችሁ ጸንተው ይኖራሉ፥ ይላል እግዚአብሔር።'),
  ('eb67b534-f723-5828-a238-38c59a4bae0c', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 23, 23, 'እንዲህም ይሆናል፦ በየመባቻውና በየሰንበቱ ሥጋ ለባሽ ሁሉ በኢየሩሳሌም በፊቴ ይሰግድ ዘንድ ዘወትር ይመጣል፥ ይላል እግዚአብሔር።'),
  ('e125bdc8-07f6-5ed0-ad82-7fe82ad5f000', '60b68959-637f-5ba7-a3fd-e28f7ded8982', '44b03042-08d1-5377-a1f3-750478280057', 24, 24, 'ወጥተውም በእኔ ያመፁብኝን ሰዎች ሬሳቸውን ያያሉ፤ ትላቸው አይሞትም፤ እሳታቸውም አይጠፋም፤ ለሥጋ ለባሽም ሁሉ ምሳሌ ይሆናሉ።”'),
  ('61ce264d-49ab-515d-a2d4-3f904c48a9de', '2865231a-dc41-582d-a2d8-021823d4eafe', '029b8b60-ba0d-5543-a695-713a5f8b8432', 1, 1, 'በብንያም ሀገር በዓናቶት ከነበሩ ካህናት ወገን ወደ ሆነ ወደ ኬልቅያስ ልጅ ወደ ኤርምያስ የመጣ የእግዚአብሔር ቃል።'),
  ('fa98a574-90ea-5d90-aae6-9efd482aa94c', '2865231a-dc41-582d-a2d8-021823d4eafe', '029b8b60-ba0d-5543-a695-713a5f8b8432', 2, 2, 'በይሁዳ ንጉሥ በአሞጽ ልጅ በኢዮስያስ ዘመን በመንግሥቱ በዐሥራ ሦስተኛው ዓመት የእግዚአብሔር ቃል መጣለት።'),
  ('29d61d87-5cd0-5423-aca8-bfa832020a02', '2865231a-dc41-582d-a2d8-021823d4eafe', '029b8b60-ba0d-5543-a695-713a5f8b8432', 3, 3, 'በይሁዳም ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም ዘመን፥ እስከ ይሁዳ ንጉሥ እስከ ኢዮስያስ ልጅ እስከ ሴዴቅያስ እስከ ዐሥራ አንደኛው ዓመት ፍጻሜ፥ ኢየሩሳሌም እስከ ተማረከችበት እስከ አምስተኛው ወር ድረስ መጣ።'),
  ('ebf380e0-b166-548f-a13a-2df42b30c0ed', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 1, 4, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('015a11ce-8e69-500b-a4c0-fa7d856481ef', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 2, 5, '“በእናትህ ሆድ ሳልሠራህ አውቄሃለሁ፤ ከማኅፀንም ሳትወጣ ቀድሼሃለሁ፥ ለአሕዛብም ነቢይ አድርጌሃለሁ።”'),
  ('94d9402a-97b3-55e2-a9b1-05038dc01f56', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 3, 6, 'እኔም፥ “ወዮልኝ ጌታ እግዚአብሔር፥ እነሆ ሕፃን ነኝና እናገር ዘንድ አልችልም” አልሁ።'),
  ('3cde6927-0070-559c-a47f-8ba8de10ffcf', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 4, 7, 'እግዚአብሔር ግን እንዲህ አለኝ፥ “ወደምልክህ ሁሉ ዘንድ ትሄዳለህና፥ የማዝዝህንም ሁሉ ትናገራለህና፦ ሕፃን ነኝ አትበል።'),
  ('c8f86bae-006d-5c70-a2da-7f1381253689', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 5, 8, 'እኔ አድንህ ዘንድ ከአንተ ጋራ ነኝና ከፊታቸው የተነሣ አትፍራ” ይላል እግዚአብሔር።'),
  ('b19184d3-5c32-5853-a501-9554320337de', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 6, 9, 'እግዚአብሔርም እጁን ዘርግቶ አፌን ዳሰሰ፥ እግዚአብሔርም አለኝ፥ “እነሆ፥ ቃሌን በአፍህ ውስጥ አኑሬአለሁ፤'),
  ('0ebbe6c3-3092-564b-ac19-236bc10f65bc', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 7, 10, 'እነሆ ትነቅልና ታፈርስ ዘንድ፥ ታጠፋና ትገለብጥ ዘንድ፥ ትሠራና ትተክል ዘንድ በአሕዛብና በመንግሥታት ላይ ዛሬ ሾሜሃለሁ።”'),
  ('183ea895-d55e-5484-a669-158007cb0b54', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 8, 11, 'ደግሞ የእግዚአብሔር ቃል፥ “ኤርምያስ ሆይ! ምን ታያለህ?” እያለ ወደ እኔ መጣ። እኔም፥ “የሎሚ በትር አያለሁ” አልሁ።'),
  ('86fa2f24-1c0f-5708-a89f-665d72f1ab5b', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 9, 12, 'እግዚአብሔርም፥ “የተናገርሁትን እፈጽመው ዘንድ እተጋለሁና መልካም አይተሃል” አለኝ።'),
  ('27e6e58e-955c-508f-a8ad-f393afa2d1bd', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 10, 13, 'ሁለተኛም ጊዜ የእግዚአብሔር ቃል ወደ እኔ መጣ፤ እንዲህም አለኝ፥ “ምን ታያለህ?” እኔም፥ “የሚፈላ አፍላል አያለሁ፤ ፊቱም ወደ ሰሜን ወገን ነው” አልሁ።'),
  ('89705141-319a-516a-a775-b20980956349', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 11, 14, 'እግዚአብሔርም እንዲህ አለኝ፥ “ከሰሜን ወገን ክፉ ነገር በምድሪቱ በተቀመጡ ሁሉ ላይ ይፈስሳል።'),
  ('c208f19e-3b5e-54db-a4ac-eeb8c9151648', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 12, 15, 'እነሆ እኔ በሰሜን ያሉትን የመንግሥታቱን ወገኖች ሁሉ እጠራለሁ፥ ይላል እግዚአብሔር፤ እነርሱም ይመጣሉ እያንዳንዳቸውም በኢየሩሳሌም በር መግቢያ በዙሪያዋና በቅጥርዋ ሁሉ ላይ፥ በይሁዳም ከተሞች ሁሉ ላይ ዙፋናቸውን ያስቀምጣሉ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('eccee279-dc2e-530c-aaf6-2e1e01f28df7', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 13, 16, 'ስለ ክፋታቸውም ሁሉ፥ እኔን ስለ ተዉ፥ ለሌሎችም አማልክት ስለ ሠዉ፥ ለእጃቸውም ሥራ ስለ ሰገዱ፥ ፍርዴን በእነርሱ ላይ እናገራለሁ።'),
  ('137502f8-3403-5e7f-a887-68f793783a96', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 14, 17, 'አንተ ግን ወገብህን ታጠቅ፤ ተነሥም፤ ያዘዝሁህንም ሁሉ ንገራቸው፤ ከፊታቸውም የተነሣ አትፍራ። በፊታቸውም አትደንግጥ አድንህ ዘንድ እኔ ከአንተ ጋር ነኝና ይላል እግዚአብሔር።'),
  ('f9adc768-4e93-51ac-a296-67b2db3be019', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 15, 18, 'እነሆ በምድሪቱ ሁሉ ላይ፥ በይሁዳም ነገሥታት በአለቆችዋና በካህናቷ ላይ፥ በምድሪቱም ሕዝብ ላይ እንደ ተመሸገች ከተማ፥ እንደ ብረትም ዓምድ፥ እንደ ናስም ቅጥር ዛሬ አድርጌሃለሁ።'),
  ('0810fd8e-ae28-533c-ae64-e26c9a014ca0', '2865231a-dc41-582d-a2d8-021823d4eafe', 'b4c13fb5-a4d3-5773-ac1f-a34947b0dcdb', 16, 19, 'ከአንተ ጋር ይዋጋሉ፤ ነገር ግን አድንህ ዘንድ እኔ ከአንተ ጋር ነኝና ድል አይነሡህም፥” ይላል እግዚአብሔር።'),
  ('ad3a4df4-6754-5c14-a2b9-7a5642e1e8d5', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('e991ae23-b807-5f7a-aff3-2514feb8d274', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 2, 2, '“ሂድ፤ እንዲህ ብለህ በኢየሩሳሌም ጆሮ ተናገር፤ እግዚአብሔር እንዲህ ይላል፦ የብላቴንነትሽን ምሕረት፥ የታጨሽበትንም ፍቅር፥ በምድረ በዳ ዘር ባልተዘራበት ምድር እንደ ተከተልሽኝ አስቤአለሁ።'),
  ('5ad242d3-ddaa-5179-afc1-b962d89822aa', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 3, 3, 'እስራኤል ለእግዚአብሔር ቅዱስ ነበረ፤ የቡቃያው በኵራትም ነበረ፤ የበሉት እንደ በደለኞች ይቈጠራሉ፤ ክፉም ነገር ያገኛቸዋል፤ ይላል እግዚአብሔር።”'),
  ('1970b0e2-31cb-5f2c-a030-8cfb7cb54448', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 4, 4, 'የያዕቆብ ቤት የእስራኤልም ቤት ወገኖች ሁሉ ሆይ፥ የእግዚአብሔርን ቃል ስሙ።'),
  ('f2078826-d866-5767-a762-23dcd26a7678', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 5, 5, 'እግዚአብሔር እንዲህ ይላል፥ “አባቶቻችሁ ከእኔ ዘንድ የራቁ፥ ከንቱነትንም የተከተሉ፥ ከንቱም የሆኑ ምን ክፋት አግኝተውብኝ ነው?'),
  ('df0e301c-9489-51fa-a289-e9269e67be14', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 6, 6, 'እነርሱም፥ “ከግብፅ ምድር ያወጣን፥ በምድረ በዳና በባድማ፥ ዕንጨትና ውኃ፥ የእንጨት ፍሬም በሌለበት ምድር፥ ሰው በማያልፍበትና የሰው ልጅም በማይቀመጥበት ምድር የመራን እግዚአብሔር ወዴት አለ? አላሉም።'),
  ('acc30540-af82-548b-a1e9-d6d1d4cc72bd', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 7, 7, 'ፍሬዋንና በረከቷንም ትበሉ ዘንድ ወደ ቀርሜሎስ አገባኋችሁ፤ ነገር ግን በገባችሁ ጊዜ ምድሬን አረከሳችሁ፤ ርስቴንም አጐሳቈላችሁ።'),
  ('86d6490b-73fe-5098-a7dd-63e07c75b564', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '64d244ee-87c1-5fff-acb2-ae2c66542a76', 8, 8, 'ካህናቱም፦ እግዚአብሔር ወዴት አለ? አላሉም፤ ሕጌን የተማሩትም አላወቁኝም፤ ጠባቂዎችም ዐመፁብኝ፤ ነቢያትም በበዐል ትንቢት ተናገሩ፤ የማይጠቅማቸውንም ነገር ተከተሉ።'),
  ('d1821811-2cdf-508f-ae7a-da6b09e08384', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 1, 9, '“ስለዚህ እንደ ገና ከእናንተ ጋር እከራከራለሁ፤ ከልጆቻችሁም ልጆች ጋር እከራከራለሁ።'),
  ('95a1f08a-4b17-5efa-a219-f0e28d454271', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 2, 10, 'ወደ ኬቲም ደሴቶች እለፉና ተመልከቱ፤ ወደ ቄዳርም ላኩና እጅግ መርምሩ፤ እንደዚህም ያለ ነገር ሆኖ እንደ ሆነ እዩ።'),
  ('cd3691c3-2fd0-5912-a85c-7ba8c95f5c31', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 3, 11, 'አሕዛብ አማልክት ያልሆኑ አማልክቶቻቸውን ይለውጡ አንደ ሆነ እዩ፤ ነገር ግን ሕዝቤ ክብራቸውን ለማይረባ ነገር ለወጡ።'),
  ('fd1868db-cc87-54f9-a430-2936757682e5', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 4, 12, 'ሰማይ በዚህ ደነገጠ፤ እጅግም ተንቀጠቀጠ” ይላል እግዚአብሔር።'),
  ('9f6ddc65-a6c5-55d9-a8d8-65dab3c13483', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 5, 13, 'ሕዝቤ ሁለት ክፉ ነገሮችን አድርገዋልና፤ የሕይወት ውኃ ምንጭ እኔን ትተውኛል፥ የተነደሉትን ውኃውንም ይይዙ ዘንድ የማይችሉትን ጕድጓዶች ለራሳቸው ቈፍረዋል።'),
  ('49949ed2-8be9-5dcc-ac01-6fa1b2335135', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 6, 14, '“በውኑ እስራኤል ባሪያ ነውን? ወይስ የቤት ውላጅ ነውን? ስለ ምን ምርኮ ሆነ?'),
  ('5dca2a7d-4a85-550f-a72b-92b3c19343a5', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 7, 15, 'የአንበሳ ደቦሎች በእርሱ ላይ አገሡ፤ በእርሱም ላይ ደነፉ፤ ምድሩንም ባድማ አደረጉ፤ ከተሞቹንም አፈረሱ፤ የሚቀመጥባቸውም የለም።'),
  ('d8ff2395-c6da-51af-afab-b39b4da4a9d3', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 8, 16, 'የሜምፎስና የጣፍናስ ልጆች አስነወሩሽ፤ አላገጡብሽም።'),
  ('cdb2aeac-2e5a-5516-ac6a-c321a235eb1a', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 9, 17, 'ይህን ሁሉ ያመጣብሽ እኔን መርሳትሽ አይደለምን? ይላል እግዚአብሔር አምላክሽ።'),
  ('5cd7b073-18bd-55e6-a163-8ee17d15026e', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 10, 18, 'አሁንስ የግዮንን ውኃ ትጠጪ ዘንድ በግብፅ መንገድ ምን ጉዳይ አለሽ? የወንዞችንም ውኃ ትጠጪ ዘንድ በአሦር መንገድ ምን ጉዳይ አለሽ?'),
  ('c7a2ec1e-4a13-5286-a5fb-c5ba33757c43', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '0e3df1fc-1d95-55f2-aaab-9ecaa7bd333c', 11, 19, 'ክፋትሽ ይገሥጽሻል፤ ክዳትሽም ይዘልፍሻል፤ እኔን መተውሽም ክፉና መራራ ነገር መሆኑን ታውቂያለሽ፤ ትረጂማለሽ” ይላል አምላክሽ እግዚአብሔር፤ “መፈራቴም በአንቺ ዘንድ የለም፤ ይህም ደስ አላሰኘኝም” ይላል አምላክሽ የሠራዊት ጌታ እግዚአብሔር።'),
  ('8c8584e3-263e-538c-a62b-c343c38daf0d', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '5a343d41-58e5-5d33-ad44-16209b9e8892', 1, 20, 'ከጥንት ጀምሬ ቀንበርሽን ሰብሬአለሁ፤ እስራትሽንም ቈርጫለሁ፤ አንቺም፦ አላገለግልም አልሽ፤ ነገር ግን ከፍ ባለው ኮረብታ ሁሉ ላይ፤ ከለምለምም ዛፍ ሁሉ በታች ለማመንዘር ተጋደምሽ።'),
  ('58642ce6-6ff1-55ed-a752-a708177026fa', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '5a343d41-58e5-5d33-ad44-16209b9e8892', 2, 21, 'እኔ የተመረጠች ወይን፥ ፍጹምም እውነተኛ ዘር አድርጌ ተክዬሽ ነበር፤ አንቺ ግን ተለውጠሽ እንዴት መራራ የእንግዳ ወይን ግንድ ሆንሽ?'),
  ('ac5c21dd-39a6-5c93-aad2-a36c4e66a82a', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '5a343d41-58e5-5d33-ad44-16209b9e8892', 3, 22, 'በእንዶድ ብትታጠቢም፥ ለራስሽም ሳሙና ብታበዢ፥ በእኔ ፊት በኀጢአትሽ ረክሰሻል፥ ይላል ጌታ እግዚአብሔር።'),
  ('935a93fa-3975-5d06-ae2a-dadd35b4f9ec', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '5a343d41-58e5-5d33-ad44-16209b9e8892', 4, 23, 'አንቺስ፦ አልረከስሁም፤ በዓሊምንም አልተከተልሁም፤ እንዴት ትያለሽ? በሸለቆ ያለውን መንገድሽን ተመልከቺ፤ ያደረግሽውንም ዕወቂ። ማታ ማታ በመንገዶች ትጮኻለች፤'),
  ('02d1f516-b53f-530b-a425-e77a242b7d55', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '5a343d41-58e5-5d33-ad44-16209b9e8892', 5, 24, 'በምድረ በዳ ባሉ ውኃዎች ተዘረጋች፤ በሰውነቷም ምኞት ትወሰዳለች፤ ይይዟታል፤ የሚመልሳት ግን የለም፤ የሚሹአትም አይደክሙም፤ በተዋረደችበትም ጊዜ ያገኙአታል።'),
  ('d26c9b83-5e17-579d-ac95-094a7303cbc5', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', '5a343d41-58e5-5d33-ad44-16209b9e8892', 6, 25, 'እግርሽን ከሰንከልካላ መንገድ፥ ጕሮሮሽንም ከውኃ ጥም ከልክዪ፤ እርስዋ ግን፥ “እጨክናለሁ፤ እንግዶችንም ወድጄአለሁ” ብላ ተከተለቻቸው።'),
  ('928d8466-f33d-5f96-ad5e-77d681c78900', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 1, 26, 'ሌባ በተያዘ ጊዜ እንደሚያፍር፤ እንዲሁ የእስራኤል ልጆች፥ እነርሱና ንጉሦቻቸውም፥ አለቆቻቸውም፥ ካህናቶቻቸውም፥ ነቢያቶቻቸውም ያፍራሉ።'),
  ('f3e71139-db5f-5f8d-a912-03c9c906e607', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 2, 27, 'ግንዱን፥ “አንተ አባቴ ነህ፤ ድንጋዩንም፦ አንተ ወለድኸኝ” ይላሉ፤ ፊታቸውንም ሳይሆን ጀርባቸውን ሰጡኝ፤ በመከራቸው ጊዜ ግን፥ “ተነሥተህ አድነን ይላሉ።'),
  ('7adeda16-8d3d-533e-a24b-b57789945b72', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 3, 28, 'ለአንተ የሠራሃቸው አማልክትህ ግን ወዴት ናቸው? ይሁዳ ሆይ፥ አማልክትህ እንደ ከተሞችህ ቍጥር እንዲሁ ናቸውና ይነሡ፤ በመከራህም ጊዜ ያድኑህ። በኢየሩሳሌምም በመንገዶችዋ ቍጥር ለጣዖት ሠዉ።'),
  ('4a8b02e6-cecb-5568-a2db-0b45a006e72f', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 4, 29, '“ከእኔ ጋር ለምን ትከራከራላችሁ? ሁላችሁ ክዳችሁኛል፤ ሁላችሁም ዐምፃችሁብኛል” ይላል እግዚአብሔር።'),
  ('d0d9a493-79c5-58c5-a7ca-8017ae2807ee', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 5, 30, 'ልጆቻችሁን በከንቱ ቀሥፌአቸዋለሁ፤ ተግሣጼን አልተቀበላችሁም፤ ሰይፋችሁ እንደሚሰብር አንበሳ ነቢያቶቻችሁን በልቶአል፤ በዚህም አልፈራችሁኝም።'),
  ('05e86585-d29b-5222-a327-0ce6a3aba82f', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 6, 31, 'የእግዚአብሔርን ቃል ስሙ። በውኑ ለእስራኤል ምድረ በዳ ወይስ የጨለመች ምድር ሆንሁበትን? ሕዝቤስ ስለ ምን፦ እኛ አንገዛልህም፤ ከእንግዲህም ወዲህ ወደ አንተ አንመለስም ይላል?'),
  ('fb93674b-8112-58c5-a5d5-f072bb228a67', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 7, 32, 'በውኑ ሙሽራ ጌጥዋን ወይስ ድንግል ዝርግፍ ጌጥዋን ትረሳለችን? ሕዝቤ ግን ለማይቈጠር ወራት ረስቶኛል።'),
  ('049f7825-1865-5ad8-af45-cb89b566194e', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 8, 33, 'ፍቅርን ለመሻት እንግዲህ በመንገድሽ የምትፈልጊው መልካም ምንድን ነው? እንዲህ አይደለም፤ መንገድሽን ታረክሺ ዘንድ ዳግመኛ በደልሽ።'),
  ('fdcb4543-04be-5116-a799-2e7a5f7712d7', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 9, 34, 'በእጆችሽም የንጹሓን ድሆች ደም ተገኝቶአል፤ በዛፍ ሁሉ ላይ በግልጥ አገኘሁት እንጂ በጕድጓድ ፈልጌ አላገኘሁትም።'),
  ('3c06aca3-1b08-5662-aaa5-2e2a3773ae2a', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 10, 35, 'አንቺ ግን፦ ንጹሕ ነኝ፤ በእውነት ቍጣው ከእኔ ይመለስ አልሽ። እነሆ ኀጢአት አልሠራሁም ብለሻልና እፋረድሻለሁ።'),
  ('13ac158b-5360-575b-a592-cf4a6dff2a61', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 11, 36, 'መንገድሽን እጥፍ ታደርጊ ዘንድ ለምን እጅግ ትሮጫለሽ? በአሦር እንዳፈርሽ በግብፅም ታፍሪያለሽ።'),
  ('70b2875f-a1f1-5ccf-a99a-4b44e4777c67', '8cff0a48-cc3b-57cf-a1a2-584d955b59c7', 'a1d89239-ce77-5c40-aa04-0faadc603840', 12, 37, 'እግዚአብሔርም ተስፋሽን አስቈርጦሻልና፥ በእርሱም አይከናወንልሽምና እጅሽን በራስሽ ላይ አድርገሽ ከዚያ ደግሞ ትወጫለሽ።'),
  ('e3bd3ca3-8079-54dd-afb9-5e06bfff4fe8', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 1, 1, '“ሰው ሚስቱን ቢፈታ፥ ከእርሱም ዘንድ ሄዳ ሌላ ወንድ ብታገባ፥ በውኑ ደግሞ ወደ እርሱ ትመለሳለችን? ያች ሴት እጅግ የረከሰች አይደለችምን? አንቺም ከብዙ እረኞች ጋር አመንዝረሻል፤ ወደ እኔም ትመለሻለሽን? ይላል እግዚአብሔር።'),
  ('3ae7b709-0ffc-519c-ad00-1c304036fbb6', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 2, 2, 'ዐይኖችሽን አቅንተሽ አንሺ፤ ያልተጋደምሽበት ስፍራ እንዳለም ተመልከች። እንደ ምድረ በዳ ቍራዎች በመንገድ ላይ ተቀምጠሽ በዝሙትሽና በክፋትሽ ምድሪቱን አርክሰሻታልና።'),
  ('a0fce926-6b3b-556b-a59e-bcfcd486b926', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 3, 3, 'ለጕስቍልናሽ ከብዙዎች እረኞች ጋር ኖርሽ የአመንዝራም ሴት ፊት ነበረብሽ፥ በሁሉም ዘንድ ያለ ኀፍረት ሄድሽ። ስለዚህ የመከርና የበልግ ዝናም ተከለከለ።'),
  ('6e844ab3-8def-5c71-aa13-c36b29e1258c', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 4, 4, 'አሁንም፦ እንደ ጌታሽና እንደ አባትሽ፥ እንደ ልጅነት ባልሽም አልጠራሽኝምን?'),
  ('9d4838f3-1e9d-53fa-a0c9-a5c1f0c91764', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 5, 5, 'ቍጣው ለዘለዓለም ይኖራልን? እስከ ፍጻሜስ ድረስ ይጠብቀዋልን? እነሆ እንዲህ ብለሽ ተናገርሽ፤ እንደ ተቻለሽም መጠን ክፉን ነገር አደረግሽ።”'),
  ('bbd04d0a-0cf0-57b3-a439-b6ef161342fe', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 6, 6, 'እግዚአብሔርም በንጉሡ በኢዮስያስ ዘመን እንዲህ አለኝ፥ “ከዳተኛዪቱ እስራኤል ያደረገችውን አየህን? ወደ ረዘመው ተራራ ሁሉ፥ ወደ ለመለመ ዛፍም ሁሉ በታች ሄደች፤ በዚያም አመነዘረች።'),
  ('2e2b9af1-fd7b-56de-a0d3-9ba041d94a43', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 7, 7, 'ይህንም ሁሉ ካደረገች በኋላ፦ ወደ እኔ ተመለሽ አልኋት፤ ነገር ግን አልተመለሰችም፤ አታላይ እኅቷ ይሁዳም አየች።'),
  ('46a83e19-76d7-5d98-a839-ddc43d710223', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 8, 8, 'ከዳተኛዪቱም እስራኤል እንዳመነዘረች አየሁ፤ የፍችዋንም ደብዳቤ በእጅዋ ሰጥቼ ሰደድኋት፤ ጎስቋላ እኅቷ ይሁዳ ግን በዚያ አልፈራችም፤ እርስዋም ደግሞ ሄዳ አመነዘረች።'),
  ('5c6d3bd2-8a27-5b73-a693-70210aa33d73', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 9, 9, 'ዝሙቷም ከንቱ ሆነ፤ እርስዋም ከድንጋይና ከግንድ ጋር አመነዘረች።'),
  ('ba804bea-5c92-501d-aedf-d67d795871bc', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 10, 10, 'በዚህም ሁሉ ከዳተኛዪቱ ይሁዳ በሐሰት እንጂ በፍጹም ልብዋ ወደ እኔ አልተመለሰችም” ይላል እግዚአብሔር።'),
  ('4ae98162-db1a-5ce8-a87d-f9d1face8c55', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 11, 11, 'እግዚአብሔርም እንዲህ አለኝ፥ “ከጎስቋላዋ ይሁዳ ይልቅ ከዳተኛዪቱ እስራኤል ራስዋን አጸደቀች።'),
  ('a4697499-9be5-5ffd-aaf0-39264b2dc50e', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 12, 12, 'ሂድና ይህን ቃል ወደ ሰሜን ተናገር፤ እንዲህም በል፦ ከዳተኛዪቱ እስራኤል ሆይ! ወደ እኔ ተመለሽ፥ ይላል እግዚአብሔር፤ መሓሪ ነኝና፥ ለዘለዓለምም አልቈጣምና በእናንተ ላይ ፊቴን አላጸናም፥” ይላል እግዚአብሔር።'),
  ('bfc7ee5a-f7af-55a9-a08b-fe58931181fe', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 13, 13, 'በአምላክሽ በእግዚአብሔር ላይ እንዳመፅሽ፥ መንገድሽንም ከለመለመ ዛፍ ሁሉ በታች ለእንግዶች እንደ ዘረጋሽ፥ ቃሌንም እንዳልሰማሽ ኀጢአትሽን ብቻ ዕወቂ ይላል እግዚአብሔር።'),
  ('df822ea7-aa9c-5fb0-a292-d3b54e805f2a', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 14, 14, 'ከዳተኞች ልጆች ሆይ! እኔ እገዛችኋለሁና ተመለሱ፤ ይላል እግዚአብሔር። አንዱንም ከአንዲት ከተማ ሁለቱንም ከአንድ ወገን እወስዳችኋለሁ፤ ወደ ጽዮንም አመጣችኋለሁ፤'),
  ('b590ccd8-3790-5554-a99a-e82d397ddd2c', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 15, 15, 'እንደ ልቤም የሚሆኑ ጠባቂዎችን እሰጣችኋለሁ፤ በዕውቀትና በማስተዋልም ይጠብቁአችኋል።'),
  ('766268c1-d567-51ee-aa15-26e6cb99faa0', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 16, 16, '“በበዛችሁ ጊዜ፥ በምድርም ላይ በረባችሁ ጊዜ፥” ይላል እግዚአብሔር፤ በዚያ ዘመን፦ የእስራኤል ቅዱስ የእግዚአብሔር የቃል ኪዳኑ ታቦት እነኋት አይሉም፤ በልባቸውም አያስቧትም፤ በአፋቸውም አይጠሯትም፤ ከእንግዲህ ወዲህም አይሿትም።'),
  ('aeff531c-2f84-5a0b-a2f5-19b03ceb4cea', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 17, 17, 'ያንጊዜም ኢየሩሳሌምን የእግዚአብሔር ዙፋን ብለው ይጠሩአታል፤ አሕዛብም ሁሉ በእግዚአብሔር ስም ወደ ኢየሩሳሌም ይሰበሰባሉ፤ ከእንግዲህም ወዲህ ክፉውን እልከኛ ልባቸውን ተከትለው አይሄዱም።'),
  ('c67789f5-1837-5886-a050-74d41d59aadc', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '6ee8f18e-1bb3-591e-a5ec-98595186c738', 18, 18, 'በዚያም ዘመን የይሁዳ ቤት ወደ እስራኤል ቤት ይሄዳል፤ በአንድም ሆነው ከሰሜን ምድር ርስት አድርጌ ለአባቶቻቸው ወደ ሰጠኋት ምድር ይመጣሉ።'),
  ('91d88c48-3f7a-54d8-a1b6-7e06f7243c80', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 1, 19, '“እኔም፦ ይሁን አልሁ፤ በወንዶች ልጆች መካከል እሾምሃለሁ፤ አሕዛብን የሚገዛ ሁሉን ቻይ የሆነ የእግዚአብሔርን ርስት የተመረጠችውን ምድር ለአንተ እሰጥሃለሁ፤ አባቴ ትለኛለህ፤ ከእኔም አትመለስም አልሁ ብለሃልና።'),
  ('432e4fba-4e46-543a-a375-8c242168466b', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 2, 20, 'ሚስት ባልዋን እንደምትከዳ እንዲሁ የእስራኤል ቤት ከዱኝ” ይላል እግዚአብሔር።'),
  ('a7874279-d7da-5901-a3cd-3ad47cedc847', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 3, 21, 'የእስራኤል ልጆች በመንገዳቸው ዐምጸዋልና፥ ቅዱስ አምላካቸውንም ረስተዋልና ከብዙ ሰዎች ድምፅ ተሰማ፤ የእስራኤል ልጆች ልቅሶና ጩኸትም ተሰማ።'),
  ('0c6d5420-bf28-5a40-a09d-cc21a8df7ecf', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 4, 22, '“ከዳተኞች ልጆች ሆይ! ተመለሱ፤ ቍስላችሁንም እፈውሳለሁ። እነሆ እኛ አገልጋዮችህ እንሆናለን፤ አንተ አምላካችን እግዚአብሔር ነህና።'),
  ('07bb367f-2022-59b2-a3e0-7e88d1905714', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 5, 23, 'በእውነት የተራሮች ኀይል፥ የኮረብቶችም ኀይል ሐሰት ነው፤ ነገር ግን የእስራኤል መዳን በአምላካችን በእግዚአብሔር ዘንድ ነው።'),
  ('e8b06cea-a983-589c-a7e1-43f81660ee63', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 6, 24, 'ነገር ግን ከትንሽነታችን ጀምሮ የአባቶቻችንን ሥራ፥ በጎቻቸውንና ላሞቻቸውን፥ ወንዶችና ሴቶች ልጆቻቸውንም፥ እፍረት በልቶባቸዋል።'),
  ('b4f03f08-c2d8-55d9-ae95-2184a755768e', '99b65548-0f8a-5dca-ab26-4fb41c9c7ec7', '26421812-3f5b-57ab-a081-9c480a3048a3', 7, 25, 'ከትንሽነታችን ጀምሮ እስከ ዛሬ ድረስ እኛና አባቶቻችን በአምላካችን በእግዚአብሔር ላይ ኀጢአት ሠርተናልና፥ የአምላካችንንም የእግዚአብሔርን ቃል አልሰማንምና በእፍረታችን ተኝተናል፤ ውርደታችንም ሸፍኖናል።”'),
  ('e6bf7d9d-80e2-5d72-aef2-3e1a65d284c5', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '883e22d9-34b9-57aa-ae59-04dd20ec1467', 1, 1, 'እስራኤል ወደ እኔ ቢመለስ ይመለስ፥ ይላል እግዚአብሔር፤ ርኵሰቱንም ከአፉ ቢያስወግድ፤ ከፊቴም የተነሣ ቢፈራ፥'),
  ('21872594-6e79-5673-af0a-a083fe46e1be', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '883e22d9-34b9-57aa-ae59-04dd20ec1467', 2, 2, 'ሕያው እግዚአብሔርን! ብሎ በእውነትና በቅንነት፤ በጽድቅም ቢምል፥ አሕዛብ በእርሱ ይባረካሉ፤ በኢየሩሳሌምም እግዚአብሔርን ያመሰግናሉ።'),
  ('ed073c52-9ed9-57d5-aae1-ac0486f4f786', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '883e22d9-34b9-57aa-ae59-04dd20ec1467', 3, 3, 'እግዚአብሔር ለይሁዳ ወንዶችና ለኢየሩሳሌም ነዋሪዎች እንዲህ ይላልና፦ ልባችሁን አድሱ በእሾህም ላይ አትዝሩ።'),
  ('cc1665b5-7888-5273-aca9-791a901e822b', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '883e22d9-34b9-57aa-ae59-04dd20ec1467', 4, 4, 'እናንተም የይሁዳ ሰዎች በኢየሩሳሌም የምትኖሩ ሆይ፥ ስለ ሥራችሁ ክፋት ቍጣዬ እንደ እሳት እንዳይወጣ የሚያጠፋውም ሳይኖር እንዳይነድ ለአምላካችሁ ተገረዙ፤ የልባችሁንም ሸለፈት አስወግዱ።'),
  ('3fd17abf-b4a6-54f5-ab43-2dd46d89d430', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 1, 5, 'በይሁዳ ዘንድ ተናገሩ፤ በኢየሩሳሌምም ላይ አውሩና፦ በሀገሪቱ ላይ መለከት ንፉ በሉ፤ ጮኻችሁም፦ ሁላችሁ ተሰብሰቡ፤ ወደ ተመሸጉትም ከተሞች እንግባ በሉ።'),
  ('2c753906-910f-5d70-a834-22113b317459', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 2, 6, 'ከሰሜን ክፉ ነገርንና ጽኑ ጥፋትን አመጣለሁና ዓላማችሁን አንሡ፤ ወደ ጽዮንም ሽሹ፥ ፍጠኑ፥ አትዘግዩ።'),
  ('dab8fc1f-c7a6-5bc9-a650-fd60bbd84556', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 3, 7, 'አንበሳ ከጕድጓዱ ወጥቶአል፤ አሕዛብንም ሊያጠፋቸው የሚዘርፍ ተነሥቶአል፤ ምድርሽን ባድማ ያደርግ ዘንድ፥ ከተሞችሽንም ሰው እንዳይኖርባቸው ያፈርሳቸው ዘንድ ከስፍራው ወጥቶአል።'),
  ('97d4d2e5-ac14-50a0-af53-bf18b0361095', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 4, 8, 'የእግዚአብሔር ጽኑ ቍጣ ከእኛ ዘንድ አልተመለሰምና ማቅ ልበሱ፤ አልቅሱም፤ ዋይም በሉ።'),
  ('3067da78-45e8-50c9-a620-b44abf0935cf', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 5, 9, 'በዚያም ቀን ይላል እግዚአብሔር፤ የንጉሡና የመኳንንቱ ልብ ይጠፋል፤ ካህናቱም ይደነግጣሉ፤ ነቢያቱም ያደንቃሉ።'),
  ('93991ab5-691a-5ea4-a9a4-8711b7b7dd14', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 6, 10, 'እኔም፥ “ጌታ እግዚአብሔር ሆይ፥ ወዮ! አንተ ሰይፍ እስከ ሰውነታቸው ድረስ እስክትደርስ ሰላም ይሆንላችኋል” ብለህ ይህን ሕዝብና ኢየሩሳሌምን እጅግ አታለልህ አልሁ።'),
  ('6a59b8db-25db-56f4-a158-ed5fbcbb0d55', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 7, 11, 'በዚያ ጊዜ ለዚህ ሕዝብና ለኢየሩሳሌም እንዲህ ይሏቸዋል፦ በምድረ በዳ የሚያስት ጋኔን አለ፤ የሕዝቤ ሴት ልጅ መንገድም ለንጽሕና ወይም ለቅድስና አይደለም።'),
  ('b9f1211f-5c1d-502b-a511-65f945054236', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 8, 12, 'አሳች ጋኔን ይመጣል፤ አሁንም እኔ ፍርዴን በእነርሱ ላይ እናገራለሁ።'),
  ('f51798b4-c794-52a0-a654-185f85d7b3a3', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 9, 13, 'እነሆ! እንደ ደመና ይወጣል፤ ሰረገሎቹም እንደ ዐውሎ ነፋስ ናቸው፤ ፈረሶቹም ከንስር ይልቅ ፈጣኖች ናቸው። ተዋርደናልና ወዮልን።'),
  ('b32c0553-d7c2-56ce-a784-dc72533cace3', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 10, 14, 'ኢየሩሳሌም ሆይ! ትድኚ ዘንድ ልብሽን ከክፉ ነገር እጠቢ። ክፉ አሳብ የሚኖርብሽ እስከ መቼ ነው?'),
  ('fc074caf-4cde-51a9-aa1b-c9c5dc203d7c', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 11, 15, 'የወሬ ነጋሪ ድምፅ ከዳን ይመጣል፥ ከኤፍሬምም ተራሮች መከራ ይሰማል።'),
  ('87f6b7be-d0e4-5e14-aff8-7a76ab128ac5', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 12, 16, 'ለአሕዛብ አሳስቡ፥ “እነሆ፥ መጡ! ጠላቶች ከሩቅ ሀገር ይመጣሉ፤ በይሁዳም ከተሞች ላይ ይጮኻሉ ብላችሁ በኢየሩሳሌም ላይ አውጁ።'),
  ('a5bb927a-ab88-5bde-abcb-7f6d13ea77e8', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 13, 17, 'በእኔ ላይ ዐመፀኛ ሆናለችና በዙሪያዋ ከብበው እንደ እርሻ ጠባቂዎች ሆነውባታል” ይላል እግዚአብሔር።'),
  ('d23890c4-592f-560c-a9e0-e876f690b98f', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '362d7ed3-6721-5796-a08c-01167fb690f4', 14, 18, 'መንገድሽና ክፉ ሥራሽ ይህን አድርጎብሻል፤ ይህ ክፋትሽ መራራ ነው፤ ወደ ልብሽም ደርሶአል።'),
  ('68bc0f31-6f24-5635-ae5f-321c2303771d', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 1, 19, 'አንጀቴ! አንጀቴ! ልቤ በጣም ታምሞአል፤ ነፍሴም አእምሮዋን አጥታለች፤ በውስጤም ልቤ ታውኮብኛል፤ ነፍሴም የመለከትን ድምፅና የሰልፍን ውካታ ሰምታለችና ዝም እል ዘንድ አልችልም።'),
  ('41a32c27-0c4d-5d21-ad43-dda82abc6503', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 2, 20, 'መከራ በመከራ ላይ ተጠርቶአል፤ ምድር ሁሉ ተዋርዳለችና፤ በድንገትም ድንኳኔ ጠፋ፤ መጋረጃዎችም ተቀዳደዱ።'),
  ('3b99e5b7-9e67-5434-a94f-105d26bf4f27', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 3, 21, 'የሚሸሹትን የምመለከት፥ የመለከቱንስ ድምፅ የምሰማ እስከ መቼ ነው?'),
  ('0cee05b6-9650-51e8-aa4e-1effff2d8315', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 4, 22, 'የሕዝቤ አለቆች አላወቁኝም፤ እነርሱ ሰነፎች ልጆች ናቸው፤ ማስተዋልም የላቸውም፤ ክፉ ነገርን ለማድረግ ብልሃተኞች ናቸው፤ በጎ ነገርን ማድረግ ግን አያውቁም።'),
  ('7197d315-0dbd-54ad-a12e-793cda97af1d', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 5, 23, 'ምድሪቱን ተመለከትሁ፤ እነሆም ባዶ ነበረች፤ ሰማያትንም ተመለከትሁ፤ ብርሃንም አልነበረበትም።'),
  ('b8e5203f-04ed-539d-aa7f-d37e6cc13639', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 6, 24, 'ተራሮችን ተመለከትሁ፤ እነሆም ይንቀጠቀጡ ነበር፤ ኮረብቶችም ሁሉ ይናወጡ ነበር።'),
  ('72d8b92a-6a8e-5676-af34-e1d53b5b5d1a', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 7, 25, 'ተመለከትሁ፤ እነሆም ሰው አልነበረም፤ የሰማይም ወፎች ሁሉ ሸሽተው ነበር።'),
  ('0346c436-1eb5-54bf-a5c1-caf588a973bd', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 8, 26, 'ተመለከትሁ፤ እነሆም ቀርሜሎስ ምድረ በዳ ሆነች፤ ከተሞችም ሁሉ ከእግዚአብሔር ፊት የተነሣ በእሳት ተቃጠሉ፤ ከጽኑ ቍጣውም የተነሣ ፈጽመው ጠፉ።'),
  ('1e1d8651-3d17-5131-ac6c-1de561832dab', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 9, 27, 'እግዚአብሔርም እንዲህ ይላል፦ ምድር ሁሉ ባድማ ትሆናለች፤ ነገር ግን ፈጽሜ አላጠፋትም።'),
  ('f8ac2dab-6207-5693-a0b8-c585fb527675', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 10, 28, 'ስለዚህ ምድር ታለቅሳለች፤ በላይም ሰማይ ይጠቍራል፤ ተናግሬአለሁና፤ አልጸጸትም ወደፊት እሮጣለሁ፤ ከእርስዋም አልመለስም።'),
  ('6a081450-9b00-5388-a926-9f9e6c1021c3', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 11, 29, 'ከፈረሰኞችና ከቀስተኞች ድምፅ የተነሣ ሀገሯ ሁሉ ሸሽታለች፤ ወደ ዋሻዎች ይገባሉ፥ በዛፍ ሥር ተሸሸጉ፥ በቋጥኝም ላይ ይወጣሉ፤ ከተማዋ ሁሉ ተለቅቃለች፤ የሚቀመጥባትም ሰው የለም።'),
  ('df6a4fc0-9d0f-52af-ae4b-3ce7e0408764', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 12, 30, 'አንቺስ ምን ታደርጊያለሽ? ቀይ በለበስሽ ጊዜ፥ በወርቅ አንባርም ባጌጥሽ ጊዜ፥ ዐይንሽንም በኵል በተኳልሽ ጊዜ፥ በከንቱ ታጌጫለሽ፤ ፍቅረኞችሽ አቃለሉሽ፥ ነፍስሽን ይሹአታል።'),
  ('d7b03348-ba3c-5887-a2a1-ad7d1baffd7a', '04afa45c-cdbe-589a-a0c8-c6f2abf59c87', '6ede64b6-4b8f-5748-a02d-244d4ca3c9b3', 13, 31, 'እንደምታምጥ፥ የበኵር ልጅዋንም እንደምትወልድ ሴት ጩኸት፥ ጩኸትሽን ሰምቻለሁና፤ የጽዮን ሴት ልጅ ድምፅ በድካም ሰለለ፤ እጆችዋንም ትዘረጋለች፤ ተገድለው ከሞቱት የተነሣ ነፍሴ ዝላለችና ወዮልኝ! አለች።'),
  ('89e00d4f-1d49-5370-a2da-6841a9fff445', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 1, 1, '“በኢየሩሳሌም መንገዶች ሩጡ፤ ተመልከቱም፤ ዕወቁም፤ በአደባባይዋም ፈልጉ፤ ፍርድን የሚያደርገውን እውነትንም የሚሻውን ሰው ታገኙ እንደ ሆነ ይቅር እላቸዋለሁ ይላል እግዚአብሔር።'),
  ('0a1b35cb-081f-550f-a223-d878c08cf84a', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 2, 2, 'እነርሱም፦ ሕያው እግዚአብሔርን! ቢሉ የሚምሉት በሐሰት ነው።”'),
  ('0cb99696-9251-5ce1-ae08-b4dd6881b5e2', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 3, 3, 'አቤቱ! ዐይኖችህ ለሃይማኖት አይደሉምን? አንተ ቀሥፈሃቸዋል፤ ነገር ግን አላዘኑም፤ ቀጥቅጠሃቸውማል፤ ነገር ግን ተግሣጽን እንቢ አሉ፤ ፊታቸውን ከድንጋይ ይልቅ አጠንክረዋል፤ ይመለሱም ዘንድ እንቢ አሉ።'),
  ('3b1af546-c85a-5db1-a23f-d963f8b2d6b1', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 4, 4, 'እኔም እንዲህ አልሁ፥ “የእግዚአብሔርን መንገድና የአምላካቸውን ፍርድ አላወቁምና እነዚህ በእውነት ድሆችና ደካሞች ናቸው፤'),
  ('357d9852-7085-58f3-a2d4-9b945958a131', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 5, 5, 'ወደ ታላላቆቹ እሄዳለሁ እናገራቸውማለሁ፤ እነርሱ የእግዚአብሔርን መንገድና የአምላካቸውን ፍርድ ያውቃሉና።” እነዚህ ግን ቀንበሩን በአንድነት ሰብረዋል፤ እስራቱንም ቈርጠዋል።'),
  ('a7b6e156-591f-5ef6-a2c8-f2367fa940e8', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 6, 6, 'ስለዚህ ኀጢአታቸው በዝቶአልና፥ የዐመፃቸውም ብዛት ጸንቶአልና አንበሳ ከዱር ወጥቶ ይሰብራቸዋል፤ የበረሃም ተኵላ ያጠፋቸዋል፥ ነብርም በከተሞቻቸው ላይ ይተጋል፤ ከዚያም የሚወጣ ሁሉ ይነጠቃል።'),
  ('7a68b981-1f37-502e-a3e3-7a6f3abe8faf', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 7, 7, '“ከእነዚህ ነገሮች በየትኛው ይቅር እልሻለሁ? ልጆችሽ ትተውኛል፤ አማልክትም ባልሆኑ ምለዋል፤ አጠገብኋቸውም፤ እነርሱ ግን አመነዘሩ፤ በአመንዝራዎቹም ቤት ዐደሩ።'),
  ('8d3f244e-7b93-5147-a1a5-d08730030a31', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 8, 8, 'እንደ አለሌ ፈረሶች ሆኑ፤ እያንዳንዳቸውም የባልጀሮቻቸውን ሚስቶች አረከሱ።'),
  ('a6dc0ce8-a473-5617-a6ee-7ff8ff192ef8', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 9, 9, 'በውኑ ስለ እነዚህ ነገሮች አልቀሥፍምን? ይላል እግዚአብሔር፤ ነፍሴስ እንደዚህ ባለ ሕዝብ ላይ አትበቀልምን?'),
  ('085c69c6-0b55-5829-abf1-c6c46525b5e9', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 10, 10, '“ወደ ቅጥርዋ ወጥታችሁ አፍርሱ፤ ነገር ግን ፈጽማችሁ አታጥፉ፤ የእግዚአብሔር ናቸውና መጠጊያዎችዋን አትርፉ።'),
  ('364cd323-acde-5ed3-ac57-8fb6e4a8dd1e', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 11, 11, 'የእስራኤል ቤትና የይሁዳ ቤት በእኔ ላይ እጅግ ወንጅለዋል” ይላል እግዚአብሔር።'),
  ('ff6ecda3-baa2-56e6-a6ed-9d797e6fcaa4', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 12, 12, 'የይሁዳም ወገኖች በእግዚአብሔር ዋሹ፤ እንዲህም አሉ፥ “እንደዚህ አይደለም፤ ክፉ ነገርም አይመጣብንም ሰይፍንና ራብንም አናይም፤'),
  ('dd3a8a5e-522c-534a-a30b-0c1920cb34f1', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '5b823345-adc2-52dc-a233-3db8d2f37341', 13, 13, 'ነቢያቶቻችን ነፋስ ናቸው፤ የእግዚአብሔርም ቃል በእነርሱ ዘንድ የለም፤ እንዲህም ይደረግባቸዋል።”'),
  ('001b8437-37e0-580a-ac13-55742bdb4baf', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', 'dfdd886b-a6c6-5e21-a52b-4c5579d719da', 1, 14, 'ስለዚህም የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “እንደዚህ ያለ ቃል ተናግራችኋልና እነሆ በአፍህ ውስጥ ቃሌን እሳት፥ ይህንም ሕዝብ እንጨት አደርጋለሁ፤ ትበላቸውማለች።'),
  ('3965a562-4f36-5a5d-a0cb-8e5e7eae2e53', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', 'dfdd886b-a6c6-5e21-a52b-4c5579d719da', 2, 15, 'የእስራኤል ቤት ሆይ! እነሆ ሕዝብን ከሩቅ አመጣባችኋለሁ፥ ይላል እግዚአብሔር፤ ኀያል ጥንታዊ ሕዝብ ነው፤ ቋንቋቸውንም የማታውቀው፥ የሚናገሩትንም የማታስተውለው ሕዝብ ነው።'),
  ('46d40946-9dfe-5242-aad7-8a4d433c44ad', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', 'dfdd886b-a6c6-5e21-a52b-4c5579d719da', 3, 16, 'ከንፈራቸውም እንደ ተከፈተ መቃብር ነው፤ ሁሉም ኀያላን ናቸው።'),
  ('11aefca6-2798-54eb-a67d-54e07e03eb87', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', 'dfdd886b-a6c6-5e21-a52b-4c5579d719da', 4, 17, 'መከርህንና እንጀራህን ይበላሉ፤ ወንዶችና ሴቶች ልጆችህንም ይበሉአቸዋል፤ በጎችህንና ላሞችህንም ይበላሉ፤ ወይንህንና በለስህንም፥ ዘይትህንም ይበላሉ፤ የምትታመናቸውን የተመሸጉ ከተሞችህንም በሰይፍ ያጠፋሉ።”'),
  ('6cfde814-b473-557d-a269-9b7ee08d886e', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', 'dfdd886b-a6c6-5e21-a52b-4c5579d719da', 5, 18, 'ነገር ግን “በዚያ ዘመን ይላል እግዚአብሔር፤ ፈጽሜ አላጠፋችሁም።”'),
  ('4641f6dd-df5b-5ef6-ab53-067ea59cb118', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', 'dfdd886b-a6c6-5e21-a52b-4c5579d719da', 6, 19, 'እንዲህም ይሆናል፤ እናንተ፥ “አምላካችን እግዚአብሔር ይህን ነገር ሁሉ ስለ ምን አደረገብን?” ብትሉ፥ አንተ፥ “እንደ ተዋችሁኝ፥ በሀገራችሁም ሌሎችን አማልክት እንዳመለካችሁ፥ እንዲሁ ለእናንተ ባልሆነ ሀገር ለሌሎች ሰዎች ትገዛላችሁ” ትላቸዋለህ።'),
  ('838ba131-1454-57e0-a707-d73bf9b270d1', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 1, 20, 'ይህንም በያዕቆብ ቤት አውሩ፤ በይሁዳም አሰሙ፦'),
  ('c2ff4cc9-2eb1-597b-a733-0e77342fd3ee', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 2, 21, 'እናንተ ሰነፎች ልበ ቢሶች፥ ዐይን እያላችሁ የማታዩ፥ ጆሮም እያላችሁ የማትሰሙ ሕዝብ ሆይ! ይህን ስሙ።'),
  ('7385a63b-653f-5c07-ab3e-f9a0085704e2', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 3, 22, 'በውኑ እኔን አትፈሩምን? ከፊቴስ አትደነግጡምን? ይላል እግዚአብሔር፤ እንዳያልፍ አሸዋን በዘለዓለም ትእዛዝ ለባሕር ዳርቻ አድርጌአለሁ፤ ሞገዱም ቢትረፈረፍና ቢጮኽ ከእርሱ አያልፍም።'),
  ('5328f763-a30b-5e3d-a86d-91f826e7c1af', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 4, 23, 'ለዚህም ሕዝብ የማይሰማና የዐመፀ ልብ አላቸው፤ ተመልሰውም ሄደዋል።'),
  ('66c5f703-9497-520f-a51d-966a1cc49535', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 5, 24, 'በልባቸውም፦ የመከሩንና የበልጉን ዝናብ በጊዜ የሚሰጠውን፥ ለመከርም የተመደቡትን ወራት የሚጠብቅልንን አምላካችንን እግዚአብሔርን እንፍራ አላሉም።'),
  ('b1d54c5d-482d-5fd6-af70-92c8ec276d23', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 6, 25, 'በደላችሁም እነዚህን አስቀርታለች፤ ኀጢአታችሁም መልካምን ነገር ከእናንተ አርቃለች።'),
  ('a74b2d89-18f0-5ad4-aaff-5eb5bc5f93d8', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 7, 26, 'በሕዝቤ መካከል ክፉዎች ሰዎች ተገኝተዋል፤ ሰዎችንም ይዘው ይገድሉ ዘንድ ወጥመድን ይዘረጋሉ።'),
  ('92917844-a69e-5862-aaf1-7529cba8e554', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 8, 27, 'ቀፎ ወፎችን እንደሚሞላ፥ እንዲሁ ቤታቸው ሽንገላን ሞልታለች፤ በዚህም ከብረዋል ባለጸጎችም ሆነዋል።'),
  ('1505706b-d0e4-5641-a6be-73f15aac37d4', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 9, 28, 'ፍርድን አጣመሙ ለድሃአደጎች ፍርድን አልፈረዱም፤ ለመበለቷም አልተሟገቱም።'),
  ('5e133234-aee2-5507-ad8b-ccb6e9312e38', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 10, 29, 'በውኑ ስለ እነዚህ ነገሮች አልቀሥፍምን? ይላል እግዚአብሔር፤ ነፍሴስ እንደዚህ ባለ ሕዝብ ላይ አትበቀልምን?'),
  ('554f9837-83fc-549a-af52-bebdc8b70146', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 11, 30, 'የምትሰቀጥጥና የምታስደነግጥ ነገር በምድር ላይ ሆናለች፤'),
  ('da2589e1-282c-534d-a55f-d49f1f3b0e1f', 'e06547d2-d14a-5c3f-a0d9-32a79a7fbe08', '88f44d03-8435-5e03-a7ff-0adafe5ccf4b', 12, 31, 'ነቢያት በሐሰት ትንቢት ይናገራሉ፥ ካህናትም በእጃቸው ያጨበጭባሉ፥ ሕዝቤም እንዲህ ያለውን ነገር ይወድዳሉ፤ በፍጻሜውስ ምን ታደርጋላችሁ?'),
  ('96e17a0f-ed56-5b98-ad0a-ce0e3a967a7b', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 1, 1, 'እናንተ የብንያም ልጆች፥ ክፉ ነገር፥ ታላቅም ጥፋት ከመስዕ ይጐበኛልና ከኢየሩሳሌም ውስጥ ለመሸሽ ጽኑ፤ በቴቁሔ መለከቱን ንፉ፤ በቤትካሪም ላይ ምልክትን አንሡ።'),
  ('8d76009e-471b-56ba-a450-be0143ad2bb8', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 2, 2, 'ቅምጥል የጽዮን ልጅ ሆይ! ውበትሽ ይጐሳቈላል።'),
  ('ca3d1284-776e-53c8-a140-d8f79f7133ca', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 3, 3, 'እረኞችና መንጎቻቸው ወደ እርስዋ ይመጣሉ፤ በዙሪያዋም ድንኳኖቻቸውን ይተክሉባታል፤ በእጃቸውም መንጋቸውን ያሰማራሉ።'),
  ('cf778d16-d132-515b-a894-98d5cc6e86d6', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 4, 4, 'በእርስዋ ላይ ሰልፍ አዘጋጁ፤ ተነሡ፥ በቀትርም እንውጣ። ቀኑ መሽቶአልና፥ የቀኑም ጥላ አልፎአልና ወዮልን።'),
  ('96216ac6-24b1-5beb-a9c2-b7c87eb30185', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 5, 5, 'ተነሡ በሌሊትም እንውጣ፤ መሠረቶችዋንም እናፍርስ።'),
  ('b8899d23-c321-5d2d-ad57-78c2ce531a9e', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 6, 6, 'ኀያል እግዚአብሔር እንዲህ ይላልና፦ ዛፎችዋን ቍረጡ፤ በኢየሩሳሌምም ላይ ኀይልን አፍስሱ ይህች ከተማ የሐሰት ከተማ ናት፤ መካከልዋ ሁሉ ግፍ ብቻ ነው።'),
  ('622394bb-6728-51da-a52b-9db336be42b7', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 7, 7, 'በጕድጓድ ውኃ እንደሚፈልቅ፥ እንዲሁ ክፋቷ ከእርስዋ ዘንድ ይፈልቃል፤ ግፍና ቅሚያ በእርስዋ ዘንድ ይሰማል፤ ደዌና ቍስልም ሁልጊዜ በፊቷ አለ።'),
  ('45a4831d-e06a-5a49-a1ed-7069b2a7711f', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', 'a4b9a2a1-6f41-5322-a8e2-7d0ce094c01e', 8, 8, 'ኢየሩሳሌም ሆይ፤ ነፍሴ ከአንቺ እንዳትለይ፥ አንቺንም ባድማና ወና እንዳላደርግሽ፥ ተግሣጽን ተቀበዪ።'),
  ('a2c23699-7e07-595a-ac5c-9594ec915160', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 1, 9, 'እግዚአብሔር እንዲህ ይላል፥ “ሰው ወይንን እንደሚቃርም፥ እንዲሁ ከእስራኤል የቀሩትን ይቃርሙአቸዋል፤ እጅህን እንደ ወይን ለቃሚ ወደ እንቅብ ዘርጋ።'),
  ('111270ed-48a7-5840-a391-4a45ebbd0a4f', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 2, 10, 'ይሰሙኝስ ዘንድ ለማን እናገራለሁ? ለማንስ አዳኛለሁ? እነሆ፥ ጆሮአቸው ያልተገረዘች ናት፤ ለመስማትም አይችሉም፤ እነሆ፥ የእግዚአብሔር ቃል ለስድብ ሆኖባቸዋል፥ ይሰሙት ዘንድ አልፈቀዱምና።'),
  ('c2767d4e-65c4-52b6-a03c-911b3164609f', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 3, 11, 'ስለዚህ ቍጣዬን መላሁባቸው፤ ታገሥሁ፤ ፈጽሜም አላጠፋኋቸውም፤ በሜዳ በሕፃናት ላይ በጐልማሶችም ጉባኤ ላይ መዓቴን በአንድነት አፈስስባቸዋለሁ፤ ባል ከሚስቱ ጋር ሽማግሌውም ከጎበዙ ጋር ይያያዛልና።'),
  ('27bfa7e7-b3ee-5b65-a780-a0d6ec26e19c', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 4, 12, 'እጄን በዚች ምድር በሚኖሩ ላይ እዘረጋለሁና ቤቶቻቸዉ፥ እርሻዎቻቸውም፥ ሴቶቻቸውም በአንድነት ለሌሎች ይሰጣሉ፥ ይላል እግዚአብሔር፤'),
  ('0a6e7c26-0121-5103-a76e-d59dfb642459', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 5, 13, 'ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ሁሉ ኀጢአትን አድርገዋልና፥ ከሐሳዊ ነቢይ ጀምሮ እስከ ካህኑ ድረስ ሁሉም ሐሰትን አደረጉ።'),
  ('42692ede-3aec-542c-ac3a-92a881e3fc99', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 6, 14, 'የሕዝቤንም ስብራት በጥቂቱ ይፈውሳሉ፤ ሰላም ሳይሆን፦ ሰላም ሰላም ይላሉ።'),
  ('b71decf3-984f-5b6c-ae69-558f1f43b19f', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 7, 15, 'ርኩስ ነገርን ስለ ሠሩ አፍረዋልን? ምንም አላፈሩም፤ ውርደትንም አላወቁም፤ ስለዚህም ከሚወድቁ ጋር ይወድቃሉ፤ በጐበኘኋቸው ጊዜ ይዋረዳሉ፥” ይላል እግዚአብሔር።'),
  ('b876824d-96a5-5586-a5c9-22b5a51f7e75', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 8, 16, 'እግዚአብሔር እንዲህ ይላል፥ “በመንገድ ላይ ቁሙ ተመልከቱም፤ የቀደመችውንም መንገድ ጠይቁ፤ መልካሚቱ መንገድ ወዴት እንደ ሆነች ዕወቁ፤ በእርስዋም ላይ ሂዱ፤ ለነፍሳችሁም መድኀኒትን ታገኛላችሁ፤” እነርሱ ግን፥ “አንሄድባትም” አሉ።'),
  ('7c743340-bfcf-5dc8-ad77-9d73beb408c3', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 9, 17, 'እኔም፥ “የመለከቱን ድምፅ አድምጡ” ብዬ ጠባቂዎችን ሾምሁባቸው፤ እነርሱ ግን፥ “አናዳምጥም” አሉ።'),
  ('7271d881-cd93-5a53-ae98-3a9ad87ca003', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 10, 18, 'አሕዛብና የመንጋው ጠባቂዎች ሆይ፥ ስለዚህ ስሙ።'),
  ('546a0742-357a-59b1-a83f-4a05cccba423', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 11, 19, 'ምድር ሆይ፥ ስሚ! እነሆ ቃሌን ስላልሰሙ፥ ሕጌንም ስለ ጣሉ፥ እኔንም ስለ ናቁ በዚህ ሕዝብ ላይ እንደ ሥራቸው ፍሬ፥ ክፉን ነገር አመጣባቸዋለሁ።'),
  ('97f0ef8f-09ce-5811-ae90-463d5ca5897f', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 12, 20, 'ስለ ምንስ ከሳባ ዕጣንን፥ ከሩቅም ሀገር ቀረፋን ታቀርቡልኛላችሁ? የሚቃጠለውን መሥዋዕታችሁን አልቀበለውም፤ ቍርባናችሁም ደስ አያሰኘኝም።'),
  ('33a9e944-0b29-51a1-a1a7-3ba886b0776b', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '01cfa068-084e-5b90-a0ab-625455e6045e', 13, 21, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ እነሆ በዚህ ሕዝብ ላይ ደዌን አሳድራለሁ፤ አባቶችና ልጆችም በአንድነት ይታመማሉ፤ ጎረቤትና ባልንጀራም ይጠፋሉ።'),
  ('e10d8091-2553-5d96-ac95-6e5b862ff17a', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 1, 22, 'እግዚአብሔር እንዲህ ይላል፦ እነሆ ሕዝብ ከሰሜን ሀገር ይመጣል፤ ታላቅ ሕዝብም ከምድር ዳርቻ ይነሣል።'),
  ('a6e697a1-d9cb-5124-a570-9fbf900e4531', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 2, 23, 'ቀስትንና ጦርን ይይዛሉ፤ ጨካኞች ናቸው፤ ምሕረትም አያደርጉም፤ ድምፃቸው እንደ ባሕር ሞገድ ይተምማል፤ በሰረገላና በፈረሶችም ላይ ይቀመጣሉ፤ የጽዮን ሴት ልጅ ሆይ! እንደ እሳት ያጠፉሻል።'),
  ('abf7df18-597e-5fa9-a371-5557b327f755', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 3, 24, 'ጩኸታቸውን ሰምተን፥ እጃችን ደክማለች፤ ወላድን ሴት ምጥ እንደሚይዛት ጭንቀት ይዞናል።'),
  ('ff8ba023-992c-5a6a-a33a-08428539943c', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 4, 25, 'የጠላት ሰይፍ ከብበዋችኋልና ወደ ሜዳ አትውጡ፤ በመንገድም ላይ አትሂዱ።'),
  ('6632e078-6dd0-52b8-aba4-4c04ec2cd276', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 5, 26, 'የሕዝቤ ልጅ ሆይ፥ ማቅ ልበሺ፤ በራስሺም ላይ አመድ ነስንሺ፥ አጥፊ በላያችን በድንገት ይመጣብናልና ለተወዳጅ ልጅ እንደሚደረግ ልቅሶ መራራ ልቅሶ አልቅሺ።'),
  ('ebf79604-bd09-5e9c-a364-b8f641b8f8a8', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 6, 27, 'በተፈታኝ ሕዝቤ መካከል ፈታኝ አድርጌሃለሁ፤ መንገዳቸውንም በፈተንሁ ጊዜ ታውቀኛለህ።'),
  ('6a91f4ad-9cc5-53bc-a812-4c320ae008d8', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 7, 28, 'እነርሱ ሁሉ እጅግ ደንቆሮዎች ናቸው፤ በጠማማነት ይሄዳሉ፤ ሁሉም እንደ ናስና ብረት የዛጉ ናቸው።'),
  ('cbfee079-3fab-5e5a-ad88-3ee884cb9cf8', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 8, 29, 'ወናፉን የሚአናፋው ደከመ፤ እርሳሱም በእሳት ቀለጠ፤ አንጥረኛውም መልሶ በከንቱ ያቀልጠዋል፤ ኀጢአታቸውም አልተወገደም።'),
  ('1b0afe9d-c531-5ca8-a10c-dcefb9bc7117', 'bddd0169-b884-51e9-a16e-a93967f0a0a0', '8e39c5ea-0061-576f-a526-ce99870ca71d', 9, 30, 'እግዚአብሔር ንቆአቸዋልና የተናቀ ብር ብላችሁ ጥሩአቸው።'),
  ('2e1e77f6-83ff-598b-ac6c-53e50533879d', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 1, 1, 'ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣ ቃል ይህ ነው፤ እንዲህም አለ፦'),
  ('e73e2587-d63c-5661-a863-94e6740b1461', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 2, 2, '“በእግዚአብሔር ቤት በር ቁም፤ ይህንም ቃል እንዲህ ብለህ ተናገር፦ ለእግዚአብሔር ትሰግዱ ዘንድ በእነዚህ በሮች የምትገቡ ከይሁዳ ያላችሁ ሁሉ የእግዚአብሔርን ቃል ስሙ።'),
  ('da674323-43b2-5e1d-ab70-2e0a5c6a429a', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 3, 3, 'የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ መንገዳችሁንና ሥራችሁን አቅኑ፤ በዚህም ስፍራ አሳድራችኋለሁ።'),
  ('3f621934-f45f-5a3d-a3b4-c1c0198a0588', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 4, 4, 'የእግዚአብሔር መቅደስ፥ የእግዚአብሔር መቅደስ ይህ ነው እያላችሁ በሐሰት ቃል በራሳችሁ አትታመኑ።'),
  ('d37e8677-9284-508b-aabc-1e05ca69dd98', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 5, 5, 'መንገዳችሁንና ሥራችሁን ፈጽማችሁ ብታቃኑ፥ በሰውና በጓደኛው መካከል ቅን ፍርድ ብትፈርዱ፤'),
  ('752931d2-656f-5888-a56f-606260c28fc7', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 6, 6, 'መጻተኛውንና ድሃአደጉን፥ መበለቲቱንም ባትገፉ፥ በዚህም ስፍራ ንጹሕ ደምን ባታፈስሱ፥ ክፉም ሊሆንባችሁ እንግዶችን አማልክት ባትከተሉ፤'),
  ('d6fb758b-5467-5df7-a451-6dccc59166ad', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 7, 7, 'ከዘለዓለም እስከ ዘለዓለም ለአባቶቻችሁ በሰጠኋቸው ምድር በዚህ ስፍራ አሳድራችኋለሁ።'),
  ('e83f57b7-ba49-5712-aaa6-d3da113fdda0', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 8, 8, '“እነሆ በማትጠቀሙበት በሐሰት ቃል ብትተማመኑም፤'),
  ('c9ab08c1-54b8-5408-ad9b-9988bb882bd7', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 9, 9, 'ብትገድሉም፥ ብታመነዝሩም፥ ብትሰርቁም፥ በሐሰትም ብትምሉ፥ ለበአልም ብታጥኑ፥ የማታውቋቸውንም እንግዶች አማልክት ብትከተሉ ክፉ ያገኛችኋል።'),
  ('792f3218-9dab-5f86-a7d2-6bb2609ce3cc', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 10, 10, 'መጥታችሁም ስሜ በተጠራበት በዚህ ቤት በፊቴ ብትቆሙ፦ ይህን አስጸያፊ የሆነ ነገርን ሁሉ ከማድረግ ተለይተናል ብትሉ፥'),
  ('b14421b6-c531-5901-a85f-e22e8752caca', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 11, 11, 'ይህ ስሜ የተጠራበት ቤት በዐይናችሁ የሌቦች ዋሻ ነውን? እነሆ፥ እኔ አይቻለሁ፥ ይላል እግዚአብሔር።'),
  ('2b6bd54f-32a7-5fda-a512-cc44929c6447', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 12, 12, '“ነገር ግን በቀድሞ ዘመን ስሜን ወዳሳደርሁበት በሴሎ ወደ ነበረው ስፍራዬ ሂዱ፤ ከሕዝቤም ከእስራኤል ክፋት የተነሣ ያደረግሁበትን እዩ።'),
  ('7807afdb-650b-5dc3-a626-7a2b05c578a8', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 13, 13, 'አሁንም ይህን ነገር ሁሉ ስላደረጋችሁ፥ ተናገርኋችሁ፤ ነገር ግን አልሰማችሁም፤ ጠራኋችሁም፤ ነገር ግን አልመለሳችሁም፤'),
  ('65d698b1-af6e-500c-a10d-5724558e73f5', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 14, 14, 'ስለዚህ በሴሎ እንዳደረግሁ እንዲሁ ስሜ በተጠራበት፥ እናንተም በምትተማመኑበት ቤት ለእናንተና ለአባቶቻችሁም በሰጠኋችሁ ስፍራ እንዲሁ አደርጋለሁ።'),
  ('a86f2fbc-6183-5758-ac4a-04f3eca6069b', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 15, 15, 'ወንድሞቻችሁን የኤፍሬምን ዘር ሁሉ፥ እንደ ጣልሁ፥ እንዲሁ ከፊቴ እጥላችኋለሁ።”'),
  ('5196a82e-254e-5f28-aa15-d3f780b75ed1', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 16, 16, 'እግዚአብሔርም አለኝ፥ “ስለዚህ ሕዝብ አንተ አትጸልይ፤ ይቅር እላቸው ዘንድ አትማልደኝ፤ የእነርሱን ነገር አልሰማህምና ትለምንላቸው ዘንድ ወደ እኔ አትምጣ።”'),
  ('330044c3-e4b3-5ddf-ac77-818e53fb393a', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 17, 17, 'እነርሱስ በይሁዳ ከተሞች ውስጥና በኢየሩሳሌም መንገዶች የሚያደርጉትን አታይምን?'),
  ('3a5724bc-256f-5cfd-a702-5a926625511a', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 18, 18, 'ያስቈጡኝ ዘንድ፥ ለሰማይ ንግሥት እንጎቻ እንዲያደርጉ፥ ለሌሎችም አማልክት የመጠጥ ቍርባን እንዲያፈስሱ ልጆች እንጨት ይሰበስባሉ፤ አባቶችም እሳት ያነድዳሉ፤ ሴቶችም ዱቄት ይለውሳሉ።'),
  ('5a7f4b94-c492-5e5a-a9bc-66a5c885ea9b', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 19, 19, 'እኔን ያስቈጣሉን? ይላል እግዚአብሔር፤ ፊታቸው ያፍር ዘንድ ለራሳቸው አይደለምን?'),
  ('c034dbaf-b2e3-57ab-acae-03e58f94b400', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 20, 20, 'እንግዲህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ ቍጣዬና መዓቴ በዚህ ስፍራ ላይ፥ በሰውና በእንስሳ ላይ፥ በዱር ዛፎችና በምድር ፍሬ ላይ ይፈስሳል፤ ይነድዳል፤ አይጠፋምም።”'),
  ('d5928b0d-a6dc-5238-a7fc-747d2a9a1f13', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 21, 21, 'የሠራዊት ጌታ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “ከቍርባናችሁ ጋር የሚቃጠለውን መሥዋዕታችሁን ጨምሩ፤ ሥጋውንም ብሉ።'),
  ('d62946f6-ed7f-5c0e-a275-76256ef8930e', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 22, 22, 'ከግብፅ ምድር ባወጣኋችሁ ቀን ስለሚቃጠል መሥዋዕትና ስለ ቍርባን ለአባቶቻችሁ አልተናገርሁምና፥ አላዘዝኋቸውምም።'),
  ('2707a47d-0c67-585f-aa62-0f1ba8eb1eb9', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 23, 23, 'ነገር ግን፦ ቃሌን ስሙ፤ እኔ አምላክ እሆናችኋለሁ፤ እናንተም ሕዝብ ትሆኑኛላችሁ፤ መልካምም ይሆንላችሁ ዘንድ ባዘዝኋችሁ መንገድ ሂዱ ብዬ በዚህ ነገር አዘዝኋቸው።'),
  ('621d2273-465e-5fec-a49a-e53f1648eb9a', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 24, 24, 'ነገር ግን በክፉ ልባቸው አሳብና እልከኝነት ሄዱ፤ ወደፊትም ሳይሆን ወደ ኋላቸው ሄዱ እንጂ አልሰሙኝም ጆሮአቸውንም አላዘነበሉም።'),
  ('309705b7-f01a-5b68-a03d-bdce0de2609f', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 25, 25, 'አባቶቻቸው ከግብፅ ምድር ከወጡበት ቀን ጀምሮ እስከ ዛሬ ድረስ፤ በቀንና በሌሊት ባሪያዎችን ነቢያትን ሁሉ ልኬባቸው ነበር፤ አዎ ልኬባቸዋለሁ።'),
  ('9d071d13-ef24-50b0-aed7-3d4b869b92fa', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 26, 26, 'ነገር ግን አንገታቸውን አደነደኑ እንጂ አልሰሙኝም፤ ጆሮአቸውንም አላዘነበሉም፤ አባቶቻቸውም ከአደረጉት ይልቅ የባሰ አደረጉ።'),
  ('f77562ab-4ab1-5ef1-a33c-e2a95ad15402', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 27, 27, '“ይህን ሁሉ ቃል ለዚህ ሕዝብ ትነግራለህ፤ ነገር ግን አይሰሙህም፤ ትጠራቸውማለህ፤ ነገር ግን አይመልሱልህም።'),
  ('0accf151-035b-58fb-ae63-889f447b0733', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 28, 28, 'አንተም፦ የአምላኩን የእግዚአብሔርን ቃል ያልሰማ፥ ተግሣጽንም ያልተቀበለ ሕዝብ ይህ ነው፤ እውነት ጠፍቶአል፤ ከአፋቸውም ተቈርጦአል ትላቸዋለህ።'),
  ('4ac635e4-23e0-5432-a44d-b000357b7f62', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 29, 29, '“እግዚአብሔር የቍጣውን ትውልድ ጥሎአልና፥ ትቶታልምና ጠጕርሽን ቈርጠሽ፥ ጣዪው፤ በከንፈሮችሽም ሙሾ አውርጂ።'),
  ('46e06c41-df82-5d1b-af8c-8aa59ef14f5a', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 30, 30, 'የይሁዳ ልጆች በፊቴ ክፉ ነገርን ሠርተዋል፥ ይላል እግዚአብሔር፤ ያረክሱትም ዘንድ ስሜ በተጠራበት ቤት ርኵሰታቸውን አኑረዋል።'),
  ('58304a93-b4be-55d6-aa5d-08bfe46934e8', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 31, 31, 'እኔም ያላዘዝሁትንና በልቤ ያላሰብሁትን፥ ወንዶችና ሴቶች ልጆቻቸውን በእሳት ያቃጥሉ ዘንድ በሄኖም ልጅ ሸለቆ ያለችውን የቶፌትን መሥዊያዎች ሠርተዋል።'),
  ('5ef04a78-c0da-5d26-a071-d4596803b3ff', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 32, 32, '“ስለዚህ እነሆ ስፍራ ከማጣት የተነሣ በቶፌት ይቀበራሉና የታረዱት ሰዎች ሸለቆ ይባላል እንጂ የቶፌት ኮረብታ ወይም የሄኖም ልጅ ሸለቆ ዳግመኛ የማይባልበት ዘመን ይመጣል፥” ይላል እግዚአብሔር።'),
  ('6424043e-05ad-53d8-a33b-b524c321515c', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 33, 33, 'የዚህ ሕዝብ ሬሳ ለሰማይ ወፎችና ለምድር አራዊት መብል ይሆናል፥ የሚቀብራቸው የለምና።'),
  ('6924a015-8f73-5fcf-a7fb-3d04a060c71b', 'b7547823-43a9-5dc5-a540-aa6c1ebe1521', '3da3e033-b968-5942-a02b-18f1486a1c5a', 34, 34, 'ምድሪቱም ባድማ ትሆናለችና ከይሁዳ ከተሞችና ከኢየሩሳሌም አደባባይ የእልልታን ድምፅና የደስታን ድምፅ፥ የወንድ ሙሽራን ድምፅና የሴት ሙሽራን ድምፅ አጠፋለሁ።'),
  ('64bf67cf-a56e-5046-a7ee-442a31941b82', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 1, 1, '“በዚያም ዘመን ይላል እግዚአብሔር፤ የይሁዳ ነገሥታትን አጥንትና የመኳንንቱን አጥንት፥ የካህናቱን አጥንትና የነቢያቱን አጥንት፥ የኢየሩሳሌምንም ሰዎች አጥንት ከመቃብሮቻቸው ያወጣሉ።'),
  ('7ed2c34a-d4a1-56c4-a8bc-f120513dca7f', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 2, 2, 'በወደዱአቸውና በአመለኳቸው፥ በተከተሉአቸውና በፈለጓቸው፥ በሰገዱላቸውም በፀሐይና በጨረቃ፥ በከዋክብትም፥ በሰማይም ሠራዊት ሁሉ ፊት ይዘረጓቸዋል፤ አያለቅሱላቸውም፤ አይቀብሯቸውምም፤ በምድርም ፊት ላይ እንደ ጕድፍ ይሆናሉ።'),
  ('9675aa62-9da3-554a-a1c8-fb2a80bcafb5', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 3, 3, 'እኔም ባሳደድኋቸው ስፍራ ሁሉ የቀሩ፥ ከዚህች ክፉ ትውልድ የተረፉ ቅሬቶች ሁሉ፥ ከሕይወት ይልቅ ሞትን ይመርጣሉ።”'),
  ('e07ec39d-7faa-5f64-a6c4-4c1c96af866b', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 4, 4, 'እንዲህም ትላቸዋለህ፥ “እግዚአብሔር እንዲህ ይላል፦ የወደቀ አይነሣምን? የሳተስ አይመለስምን?'),
  ('f165cc66-48ff-51f4-a5bf-854cbfa366b0', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 5, 5, 'ሕዝቤ በኢየሩሳሌም ስለ ምን ወደ ኋላቸው ተመለሱ? ዐመፅን ዐምፀዋል፥ መመለስንም እንቢ ብለዋል።'),
  ('753a5ca0-5790-5c61-a43c-6abe0eae65b5', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 6, 6, 'አደመጥሁ፤ ሰማሁም፤ ቅንን ነገር አልተናገሩም፤ ማናቸውም፦ ምን አድርጌአለሁ? ብሎ ከክፋቱ ንስሓ የገባ የለም፤ የሚሮጠውም ወደ ሰልፍ እንደሚሮጥ ፈረስ ሲሮጥ ደከመ።'),
  ('1eb1465b-6799-57a8-adc0-bd41ff372fbb', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 7, 7, 'ሽመላ በሰማይ ጊዜዋን አውቃለች፤ ዋኖስና ጨረባ፥ ዋሊያም የመምጣታቸውን ጊዜ ይጠብቃሉ፤ ሕዝቤ ግን የእግዚአብሔርን ፍርድ አላወቁም።'),
  ('ca882490-59d2-5691-aa19-ee6c5463fe04', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 8, 8, '“እናንተስ፦ ጥበበኞች ነን የእግዚአብሔርም ሕግ ከእኛ ጋር ነው እንዴት ትላላችሁ? እነሆ ጸሓፊዎቻቸውም ከንቱ ሆኑ፤ በሐሰትም ብርዕ ተጠቀሙ።'),
  ('267a79ac-81f9-5f03-a5ec-970b1b5ebcab', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 9, 9, 'ጥበበኞች አፍረዋል፤ ደንግጠውማል፤ ተማርከውማል፤ እነሆ የእግዚአብሔርን ቃል ጥለዋል፤ ምን ዓይነት ጥበብ አላቸው?'),
  ('045b2491-51d3-5b6a-a43f-066b624ba152', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 10, 10, 'ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ሁሉ ስስትን ያስባሉና፥ ከነቢዩም ጀምሮ እስከ ካህኑ ድረስ ሁሉ በተንኰል ያደርጋሉና ስለዚህ ሚስቶቻቸውን ለሌሎች፥ እርሻቸውንም ለሚወርሱባቸው እሰጣለሁ።'),
  ('78592362-bea3-50bd-adcd-04341075b5ce', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 11, 11, 'የሕዝቤንም ሴት ልጅ ስብራት በማቃለል ይፈውሳሉ፤ ሰላም ሳይሆን፦ ሰላም ሰላም ይላሉ።'),
  ('bb5648c6-129c-5daa-a51e-0fce0cd81b47', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 12, 12, 'አስጸያፊ ነገርን ስለ ሠሩ አፍረዋልን? ምንም አላፈሩም፤ እፍረትንም አላወቁም፤ ስለዚህ ከሚወድቁ ጋር ይወድቃሉ፤ በጐበኘኋቸውም ጊዜ ይዋረዳሉ፤ ይላል እግዚአብሔር።'),
  ('03993d25-fbe0-5325-abb3-287069efd1e1', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 13, 13, 'አዝመራቸውን ይሰበስባሉ፤ ይላል እግዚአብሔር፤ ነገር ግን በወይን ላይ ፍሬ፥ በበለስ ዛፍ ላይ በለስ የለም፤ ቅጠልም ይረግፋል፤ ሰጠኋቸው፤ አለፈባቸውም።'),
  ('178efb2f-96a8-5df8-a5cd-66c49b667ebc', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 14, 14, '“ዝም ብለን ለምን እንቀመጣለን? እግዚአብሔርን ስለ በደልን አምላካችን እግዚአብሔር አጥፍቶናልና፥ የሐሞትንም ውኃ አጠጥቶናልና ተሰብስባችሁ ወደ ተመሸጉ ከተሞች እንግባ በዚያም እንጥፋ።'),
  ('a0491d95-4880-59b3-a75c-e80eb1ac1f16', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 15, 15, 'ሰላምን በተስፋ ተጠባበቅን፤ ለይቅርታም ጊዜ መልካም ነገርን አጣን፤ እነሆም ድንጋጤ ሆነ።'),
  ('64c33e51-736d-54e9-afa7-b406c7a5c88f', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 16, 16, 'የፈረሶቹን የሩጫ ድምፅ ከዳን ሰማን፤ ከሠራዊቱ ፈረሶች ሩጫ ድምፅ የተነሣም ምድር በመላዋ ተንቀጠቀጠች፤ መጥተውም ምድሪቱንና በእርስዋም ያለውን ሁሉ፥ ከተማዪቱንና የተቀመጡባትንም በሉ።'),
  ('b5cac7b3-cc10-5235-afbd-fc3f58ee3072', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 17, 17, 'እነሆ አስማት የማይከለክላቸውን የሚገድሉ እባቦችን እሰድድባችኋለሁ፤ እነርሱም ይነድፉአችኋል፥” ይላል እግዚአብሔር።'),
  ('fbc3ae11-2b3b-5399-acb0-0d7863c2bd58', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 18, 18, 'ልባችሁን ታምማችሁ ትቅበዘበዛላችሁ። ከሚያቅበዘብዝ የልብ ሕመማችሁ የሚያድናችሁ የለም።'),
  ('5bccf7af-bf00-5157-a8b9-b122de893831', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 19, 19, 'እነሆ እግዚአብሔር በጽዮን የለምን? ወይስ ንጉሥዋ በእርስዋ ዘንድ የለምን? የሚል የወገኔ ሴት ልጅ ጩኸት ድምፅ ከሩቅ ሀገር ተሰማ። በተቀረፁ ምስሎቻቸውና በባዕድ ከንቱነትስ ያስቈጡኝ ስለ ምንድን ነው?'),
  ('3de40cc1-e72e-5a57-a3f1-8f8e966d443c', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 20, 20, 'መከሩ አልፎአል፤ በጋውም ዐልቋል፤ እኛም አልዳንንም።'),
  ('6ee88827-351e-5d9c-a7a6-5bc1c9710c1c', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 21, 21, 'በሕዝቤ ሴት ልጅ ስብራት እኔ ወድቄ ተሰብሬአለሁ፤ ጠቍሬማለሁ፤ ራስ ማዞርም ይዞኛል፤ ምጥ እንደያዛትም ሴት በመከራው እጨነቃለሁ።'),
  ('b14c931b-2aba-5139-af9c-d3d9206d95ac', '546e7b51-8018-53ba-a374-6d2e2bf099f3', 'a3886e30-48c1-5265-a05e-af558de05517', 22, 22, 'በገለዓድ መድኀኒት የለምን? ወይስ በዚያ ሐኪም የለምን? የወገኔ ሴት ልጅ ፈውስ ስለ ምን አልሆነም?'),
  ('47316cc7-7a8b-57fe-aabc-5a9c92376855', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 1, 1, 'ስለ ተገደሉ ስለ ሕዝቤ ሴት ልጅ ሰዎች ሌሊትና ቀን አለቅስ ዘንድ ለራሴ ውኃን፥ ለዐይኔም የዕንባን ምንጭ ማን በሰጠኝ?'),
  ('2f51a2a2-3c75-5c55-a72c-4e5f9318c9f5', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 2, 2, 'ሁሉም አመንዝሮች፥ የዐመጸኞች ጉባኤ ናቸውና ሕዝቤን እተዋቸው ዘንድ ከእነርሱም እለይ ዘንድ በምድረ በዳ ማደሪያን ማን በሰጠኝ?'),
  ('aa95acaf-65df-540e-abab-b4ae7dc67c0c', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 3, 3, '“ምላሳቸውን ለሐሰት እንደ ቀስት ገተሩ፤ በምድርም በረቱ፤ ነገር ግን ለእውነት አይደለም፤ ከክፋት ወደ ክፋት ይሄዳሉና፥ እኔንም አላወቁምና፥” ይላል እግዚአብሔር።'),
  ('bd67159a-69e7-5cf7-a1d0-35c330b9bb59', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 4, 4, 'ወንድምም ሁሉ ያሰናክላልና፥ ባልንጀራም ሁሉ በጠማማነት ይሄዳልና እናንተ ሁሉ ከባልንጀሮቻችሁ ተጠንቀቁ፤ በወንድሞቻችሁም አትታመኑ።'),
  ('37bafcda-5272-5705-a66c-bfe7ab33acc4', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 5, 5, 'እያንዳንዱ በባልንጀራው ላይ ይሣለቃል በእውነትም አይናገርም፤ ሐሰት መናገርንም ምላሳቸው ተምሮአል፤ በደሉ መመለስንም እንቢ አሉ።'),
  ('67fe9e6d-af98-5e9f-a03a-8ca38378764c', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 6, 6, 'አራጣንም በአራጣ ላይ ይቀበላሉ፤ ተንኰልን በተንኰል ላይ ይሠራሉ፤ “እኔንም ያውቁኝ ዘንድ እንቢ ብለዋል፥” ይላል እግዚአብሔር።'),
  ('39351480-5afe-544c-a0bc-0c45facaf35c', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 7, 7, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ አቀልጣቸዋለሁ፤ እፈትናቸውማለሁ፤ ስለ ሕዝቤ ሴት ልጅ ክፋት እንደዚሁ አደርጋለሁና።'),
  ('cc383596-545d-566f-a571-009a24413234', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 8, 8, 'ምላሳቸው የተሳለ ፍላጻ ነው፤ ንግግራቸው ሽንገላ ነው፤ ለባልንጀራቸው ሰላምን ይናገራሉ፤ በልባቸው ግን ጥላቻን ይይዛሉ።'),
  ('c9e0800b-fd78-5491-ae85-c38e2b4e3f2d', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 9, 9, 'በውኑ ስለዚህ ነገር በመቅሠፍት አልጐበኝምን? ይላል እግዚአብሔር፤ ነፍሴስ እንደዚህ ባለ ሕዝብ ላይ አትበቀልምን?'),
  ('2839b854-5831-5e9c-abf8-36057339372c', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 10, 10, 'በተራሮቹ ላይ አልቅሱ፤ በምድረ በዳም ጎዳና ላይ እዘኑ፤ ሰው ጠፍትዋልና፤ የሚመላለስም የለምና ሙሾውንም አሙሹ፤ የሰማይ ወፍ ድምፅንም እስከ ከብት ድምፅ ድረስ አይሰሙም፤ ደንግጠውም ተማርከው ሄዱ።'),
  ('4488afa1-166d-5e94-a140-ab5aeac3c62c', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 11, 11, 'ኢየሩሳሌምንም የፍርስራሽ ክምር፥ የቀበሮም ማደሪያ አደርጋታለሁ፤ የይሁዳንም ከተሞች ሰው እንዳይቀመጥባቸው አጠፋቸዋለሁ።'),
  ('f4560c6e-0274-5f4d-ab3e-559c03228db6', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 12, 12, 'ይህን የሚያስተውል ጠቢብ ሰው ማን ነው? ያወራስ ዘንድ የእግዚአብሔር አፍ ለማን ተናገረ? ሰው እንዳያልፍባት ምድርስ ስለ ምን ጠፋች፤ እንደ ምድረ በዳስ ስለ ምን ተቃጠለች?'),
  ('5898ce0d-235c-534e-abd7-424fb340b059', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 13, 13, 'እግዚአብሔርም እንዲህ አለኝ፦ ሕዝቤ በፊታቸው የሰጠኋቸውን ሕጌን ትተዋል፤ ቃሌንም አልሰሙም።'),
  ('310e88d6-df05-5dc0-afef-4b8cbbde5b4d', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 14, 14, 'ነገር ግን የልባቸውን ምኞትና አባቶቻቸው ያስተማሩአቸውን ጣዖት ተከትለዋል፤'),
  ('17b078b2-bab6-54ce-a127-7e07cc75720e', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 15, 15, 'ስለዚህ የእስራኤል አምላክ፥ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ ይህን ሕዝብ መከራን አበላዋለሁ፤ የሐሞትንም ውኃ አጠጣዋለሁ።'),
  ('9f8b836b-9bfc-5157-ac35-f1f12ee625f1', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 16, 16, 'እነርሱና አባቶቻቸውም በአላወቋቸው አሕዛብ መካከል እበትናቸዋለሁ፤ እስከ አጠፋቸውም ድረስ በስተ ኋላቸው ሰይፍን እሰድድባቸዋለሁ።'),
  ('94457f56-1816-5669-ac87-692500105b52', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 17, 17, 'እግዚአብሔር እንዲህ ይላል፦ እንዲመጡ አልቃሾች ሴቶችን ጥሩ፤ ወደ ብልሃተኞች ሴቶችም ላኩ፤ መጥተውም ይንገሩአችሁ፤'),
  ('ea8d0e1c-5d51-59d9-a931-be134d680afb', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 18, 18, 'ፈጥነውም ሙሾ ያሙሹላችሁ፤ ዐይኖቻችሁም እንባን ያፍስሱ፤ ከዐይኖቻችሁም ሽፋሽፍቶች ውኃ ይፍለቅ።'),
  ('96937287-f594-5133-a103-fd1a0ddd7388', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 19, 19, 'ምድርን ትተናልና፥ ቤቶቻችንንም ጥለን ሄደናልና እንዴት ጐሰቈልን! እንዴት አፈርን! የሚል የልቅሶ ድምፅ በጽዮን ተሰምቶአል።'),
  ('c23ce8eb-ee59-5e60-a6bb-503fb6319128', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 20, 20, 'እናንተ ሴቶች ሆይ! የእግዚአብሔርን ቃል ስሙ፤ ጆሮአችሁም የአፉን ቃል ትቀበል፤ ለሴቶች ልጆቻችሁም ልቅሶውን፥ እያንዳንድዋም ለባልንጀራዋ ዋይታን ታስተምር።'),
  ('aab2e15e-0929-5bd8-a843-01aad173abfa', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 21, 21, 'ሕፃናቱንም በመንገድ፤ ጐልማሶቹንም በአደባባዮቻችን ያጠፋ ዘንድ ሞት በመስኮቶቻችን ወደ ሀገራችን ገብቶአልና።'),
  ('23b1e3d6-261d-5811-ab79-cd472587da4a', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 22, 22, 'የሰዎቻችሁም ሬሳ እንደ ጕድፍ በእርሻ ላይ፥ ማንም እንደማይሰበስበው ከአጫጆች በኋላ እንደሚቀር ቃርሚያ ይወድቃል።'),
  ('87e38701-a15a-54c8-a2ba-ce45b7fc76a8', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 23, 23, 'እግዚአብሔር እንዲህ ይላል፥ “ጠቢብ በጥበቡ አይመካ፤ ኀያልም በኀይሉ አይመካ፤ ባለጠጋም በብልጥግናው አይመካ፤'),
  ('cca661dc-0cfe-566a-aaac-db1d40e2ee3a', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 24, 24, 'ነገር ግን የሚመካው፦ ምሕረትንና ፍርድን፥ ጽድቅንም በምድር ላይ የማደርግ እኔ እግዚአብሔር መሆኔን በማወቁና በማስተዋሉ በዚህ ይመካ፤ ደስ የሚያሰኘኝ ይህ ነውና፥” ይላል እግዚአብሔር።'),
  ('411b5792-5fbe-5e7a-aedc-17d025af3a96', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 25, 25, '“እነሆ ዘመን ይመጣል፥ ይላል እግዚአብሔር። የተገረዙትንና ያልተገረዙትን ሁሉ በአንድነት እጐበኛለሁ።'),
  ('e56e0d12-a11b-5d4d-a858-1de2973aecc2', '2a23e8e9-071a-5b2e-a234-f83ccb9ae945', 'adfe6003-a757-51bb-a73f-cc4c831c2b50', 26, 26, 'አሕዛብ ሁሉ ያልተገረዙ ናቸውና፥ የእስራኤልም ቤት ሁሉ ልባቸው ያልተገረዘ ነውና የተገረዙትን ሁሉ፥ ግብጽንና ይሁዳን፥ ኤዶምያስንም፥ የአሞንንም ልጆች፥ ሞዓብንም፥ በምድረ በዳም የተቀመጡትን ጠጕራቸውን በዙሪያ የተላጩትንም ሁሉ የምጐበኝበት ዘመን እነሆ ይመጣል።”'),
  ('dd176f24-40b0-5983-a149-a02d36006260', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 1, 1, 'እናንተ የእስራኤል ቤት ሆይ! እግዚአብሔር በእናንተ ላይ የተናገረውን ቃል ስሙ።'),
  ('b0d91e83-a713-5f7a-afd0-39499c7a4779', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 2, 2, 'እግዚአብሔር እንዲህ ይላል፥ “የአሕዛብን መንገድ አትማሩ፤ ከሰማይ ምልክትም አትፍሩ፤ አሕዛብ ከእነርሱ የተነሣ ይፈራሉና።'),
  ('863c2f0c-f315-5845-a8fd-244b68bacf5b', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 3, 3, 'የአሕዛብ ልማድ ከንቱ ነውና፥ ከዱር በመጥረቢያ እንደሚቈረጥ፥ በሠራተኛም እጅ እንደሚሠራ እንጨት ነው።'),
  ('0dafca3e-9eb2-575f-a652-f22dcecb7187', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 4, 4, 'በብርና በወርቅ ይለብጡታል፤ እንዳይናወጥም በችንካርና በመዶሻ ይቸነክሩታል።'),
  ('d1de404e-7afb-5b15-a7d1-7be4f822cbb7', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 5, 5, 'እንደ ተቀረጸ ብር ናቸው፤ እነርሱም አይናገሩም፤ መራመድም አይቻላቸውምና ይሸከሙአቸዋል። ክፉ መሥራትም አይቻላቸውምና፥ ደግሞም መልካም ይሠሩ ዘንድ አይችሉምና አትፍሩአቸው።”'),
  ('7cda7d55-7774-5888-ae11-e2cd6c0b3b51', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 6, 6, 'አቤቱ! እንደ አንተ ያለ የለም፤ አንተ ታላቅ ነህ ስምህም በኀይል ታላቅ ነው።'),
  ('d162b2b4-4139-57e4-a025-851c9989a7ea', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 7, 7, 'የአሕዛብ ንጉሥ ሆይ! በአሕዛብ ጥበበኞች ሁሉ መካከል፥ በመንግሥታቸውም ሁሉ እንደ አንተ ያለ ስለሌለ፥ ለአንተ ክብር ይገባልና አንተን የማይፈራ ማን ነው?'),
  ('f7fd6e85-bf70-517a-ae7c-0002e2b64b28', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 8, 8, 'በአንድ ጊዜ ሰንፈዋል፥ ደንቍረውማል፤ ጣዖታት የሚያስተምሩት የእንጨት ነገር ብቻ ነው።'),
  ('429c6af2-3f7a-5e4d-a6e4-ef6872f4a71b', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 9, 9, 'የሠራተኛና የአንጥረኛ እጅ ሥራ የሆነ ከተርሴስ ጥፍጥፍ ብር፥ ከአፌዝም ወርቅ ይመጣል፤ ልብሳቸውም ሰማያዊና ቀይ ግምጃ ነው፤ ሁሉም የብልሃተኞች ሥራ ናቸው።'),
  ('bd6a9bc3-308f-55ad-a58b-065e4a6b928e', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 10, 10, 'እግዚአብሔር ግን እውነተኛ አምላክ ነው፤ እርሱም ሕያው አምላክና የዘለዓለም ንጉሥ ነው፤ ከቍጣው የተነሣ ምድር ትንቀጠቀጣለች፤ አሕዛብም መዓቱን አይችሉም።')
